{
  "name": "Nutriplan",
  "description": "Une application de planification nutritionnelle intelligente qui génère des repas personnalisés et des listes de courses automatiques basées sur vos préférences alimentaires.",
  "requestFramePermissions": [
    "camera"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum DietPreference {
  OMNIVORE = 'Omnivore',
  VEGETARIAN = 'Végétarien',
  VEGAN = 'Végan',
  KETO = 'Keto',
  PALEO = 'Paléo',
  GLUTEN_FREE = 'Sans Gluten'
}

export interface User {
  id: string;
  name: string;
  email: string;
  diet: DietPreference;
  allergies: string[];
  subscriptionType: 'free' | 'premium';
}

export interface Meal {
  id: string;
  name: string;
  description: string;
  calories: number;
  ingredients: string[];
  instructions: string[];
  image: string;
  type: 'breakfast' | 'lunch' | 'dinner';
}

export interface DayPlan {
  day: string;
  meals: {
    breakfast: Meal;
    lunch: Meal;
    dinner: Meal;
  };
}

export interface ShoppingListItem {
  item: string;
  amount: string;
  category: string;
  checked: boolean;
}

export interface AuthState {
  user: User | null;
  token: string | null;
  isAuthenticated: boolean;
  isLoading: boolean;
}

import { GoogleGenAI, Type } from "@google/genai";
import { DietPreference, DayPlan, ShoppingListItem } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

const MEAL_PLAN_SCHEMA = {
  type: Type.ARRAY,
  items: {
    type: Type.OBJECT,
    properties: {
      day: { type: Type.STRING },
      meals: {
        type: Type.OBJECT,
        properties: {
          breakfast: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              description: { type: Type.STRING },
              calories: { type: Type.NUMBER },
              ingredients: { type: Type.ARRAY, items: { type: Type.STRING } },
              instructions: { type: Type.ARRAY, items: { type: Type.STRING } },
              image: { type: Type.STRING }
            }
          },
          lunch: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              description: { type: Type.STRING },
              calories: { type: Type.NUMBER },
              ingredients: { type: Type.ARRAY, items: { type: Type.STRING } },
              instructions: { type: Type.ARRAY, items: { type: Type.STRING } },
              image: { type: Type.STRING }
            }
          },
          dinner: {
            type: Type.OBJECT,
            properties: {
              name: { type: Type.STRING },
              description: { type: Type.STRING },
              calories: { type: Type.NUMBER },
              ingredients: { type: Type.ARRAY, items: { type: Type.STRING } },
              instructions: { type: Type.ARRAY, items: { type: Type.STRING } },
              image: { type: Type.STRING }
            }
          }
        }
      }
    }
  }
};

export const generateMealPlan = async (diet: DietPreference, allergies: string[]): Promise<DayPlan[]> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Génère un menu complet pour 7 jours pour un régime ${diet}. 
                Allergies à éviter: ${allergies.join(', ') || 'Aucune'}. 
                Chaque repas doit avoir un nom, description, calories, ingrédients et instructions courtes. 
                Ajoute une URL d'image générique de Unsplash pertinente pour le plat.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: MEAL_PLAN_SCHEMA
      }
    });

    return JSON.parse(response.text);
  } catch (error) {
    console.error("Error generating meal plan:", error);
    throw error;
  }
};

export const generateShoppingList = async (mealPlan: DayPlan[]): Promise<ShoppingListItem[]> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `À partir de ce plan de repas, crée une liste de courses consolidée et catégorisée (Produits frais, Boucherie, Crémerie, Épicerie, etc.): ${JSON.stringify(mealPlan)}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              item: { type: Type.STRING },
              amount: { type: Type.STRING },
              category: { type: Type.STRING },
              checked: { type: Type.BOOLEAN }
            }
          }
        }
      }
    });

    return JSON.parse(response.text);
  } catch (error) {
    console.error("Error generating shopping list:", error);
    throw error;
  }
};

import React, { useState, useEffect, createContext, useContext } from 'react';
import { DietPreference, User, AuthState } from './types';
import LandingPage from './pages/LandingPage';
import Dashboard from './pages/Dashboard';
import Auth from './pages/Auth';
import Preferences from './pages/Preferences';
import ShoppingList from './pages/ShoppingList';
import Subscription from './pages/Subscription';
import Navbar from './components/Navbar';

// Context
const AuthContext = createContext<{
  authState: AuthState;
  login: (email: string, pass: string) => Promise<void>;
  logout: () => void;
  updateUser: (data: Partial<User>) => void;
} | null>(null);

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) throw new Error("useAuth must be used within AuthProvider");
  return context;
};

const App: React.FC = () => {
  const [view, setView] = useState<'landing' | 'auth' | 'dashboard' | 'preferences' | 'shopping' | 'subscription'>('landing');
  const [authState, setAuthState] = useState<AuthState>({
    user: null,
    token: null,
    isAuthenticated: false,
    isLoading: false
  });

  const login = async (email: string, pass: string) => {
    setAuthState(prev => ({ ...prev, isLoading: true }));
    // Simulating API call to /login
    await new Promise(resolve => setTimeout(resolve, 1000));

    const mockUser: User = {
      id: '1',
      name: 'Utilisateur Nutriplan',
      email,
      diet: DietPreference.OMNIVORE,
      allergies: [],
      subscriptionType: 'free'
    };

    setAuthState({
      user: mockUser,
      token: 'fake-jwt-token',
      isAuthenticated: true,
      isLoading: false
    });
    setView('dashboard');
  };

  const logout = () => {
    setAuthState({
      user: null,
      token: null,
      isAuthenticated: false,
      isLoading: false
    });
    setView('landing');
  };

  const updateUser = (data: Partial<User>) => {
    if (authState.user) {
      setAuthState(prev => ({
        ...prev,
        user: { ...prev.user!, ...data }
      }));
    }
  };

  const renderView = () => {
    switch (view) {
      case 'landing': return <LandingPage onGetStarted={() => setView('auth')} />;
      case 'auth': return <Auth />;
      case 'dashboard': return <Dashboard />;
      case 'preferences': return <Preferences />;
      case 'shopping': return <ShoppingList />;
      case 'subscription': return <Subscription />;
      default: return <LandingPage onGetStarted={() => setView('auth')} />;
    }
  };

  return (
    <AuthContext.Provider value={{ authState, login, logout, updateUser }}>
      <div className="min-h-screen flex flex-col">
        {authState.isAuthenticated && <Navbar currentView={view} setView={setView} />}
        <main className="flex-grow">
          {renderView()}
        </main>
      </div>
    </AuthContext.Provider>
  );
};

export default App;

