export default Navbar;

import React, { useState } from 'react';
import { useAuth } from '../App';

const Auth: React.FC = () => {
  const [isLogin, setIsLogin] = useState(true);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const { login, authState } = useAuth();

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    login(email, password);
  };

  return (
    <div className="min-h-[calc(100vh-80px)] flex items-center justify-center p-6">
      <div className="w-full max-w-md bg-white rounded-[32px] p-8 shadow-2xl shadow-slate-200 border border-slate-100">
        <div className="text-center mb-8">
          <div className="w-16 h-16 bg-emerald-600 rounded-2xl flex items-center justify-center text-white font-bold text-3xl mx-auto mb-4">N</div>
          <h2 className="text-3xl font-bold text-slate-900">{isLogin ? 'Bon retour !' : 'Créer un compte'}</h2>
          <p className="text-slate-500 mt-2">Prêt à simplifier votre alimentation ?</p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-6">
          <div>
            <label className="block text-sm font-semibold text-slate-700 mb-2">Email</label>
            <input 
              type="email" 
              required
              className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-emerald-500 focus:border-transparent outline-none transition-all"
              placeholder="votre@email.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
            />
          </div>
          <div>
            <label className="block text-sm font-semibold text-slate-700 mb-2">Mot de passe</label>
            <input 
              type="password" 
              required
              className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-2 focus:ring-emerald-500 focus:border-transparent outline-none transition-all"
              placeholder="••••••••"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
            />
          </div>

          <button 
            type="submit"
            disabled={authState.isLoading}
            className="w-full py-4 bg-emerald-600 text-white font-bold rounded-2xl hover:bg-emerald-700 transition-all shadow-lg shadow-emerald-100 disabled:opacity-50"
          >
            {authState.isLoading ? 'Chargement...' : isLogin ? 'Se connecter' : "S'inscrire"}
          </button>
        </form>

        <div className="mt-8 text-center">
          <button 
            onClick={() => setIsLogin(!isLogin)}
            className="text-sm font-medium text-emerald-600 hover:underline"
          >
            {isLogin ? "Pas encore de compte ? S'inscrire" : "Déjà un compte ? Se connecter"}
          </button>
        </div>
      </div>
    </div>
  );
};

export default Auth;

import React, { useState, useEffect } from 'react';
import { useAuth } from '../App';
import { generateMealPlan } from '../services/gemini';
import { DayPlan, DietPreference } from '../types';

const Dashboard: React.FC = () => {
  const { authState } = useAuth();
  const [mealPlan, setMealPlan] = useState<DayPlan[]>([]);
  const [loading, setLoading] = useState(false);
  const [activeDay, setActiveDay] = useState(0);

  const fetchPlan = async () => {
    if (!authState.user) return;
    setLoading(true);
    try {
      const data = await generateMealPlan(authState.user.diet, authState.user.allergies);
      setMealPlan(data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchPlan();
  }, []);

  if (loading) {
    return (
      <div className="p-8 flex flex-col items-center justify-center min-h-[60vh]">
        <div className="w-16 h-16 border-4 border-emerald-600 border-t-transparent rounded-full animate-spin mb-4"></div>
        <p className="text-slate-500 font-medium">L'IA génère votre menu personnalisé...</p>
      </div>
    );
  }

  return (
    <div className="p-6 max-w-7xl mx-auto">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
        <div>
          <h1 className="text-3xl font-bold text-slate-900">Bienvenue, {authState.user?.name}</h1>
          <p className="text-slate-500">Voici votre menu hebdomadaire équilibré.</p>
        </div>
        <button 
          onClick={fetchPlan}
          className="px-6 py-3 bg-white border border-slate-200 rounded-xl text-sm font-bold text-slate-700 hover:bg-slate-50 transition-all flex items-center gap-2"
        >
          <span>🔄</span> Régénérer le menu
        </button>
      </div>

      {mealPlan.length > 0 && (
        <>
          {/* Day Selector */}
          <div className="flex gap-2 mb-8 overflow-x-auto pb-2 scrollbar-hide">
            {mealPlan.map((plan, idx) => (
              <button
                key={idx}
                onClick={() => setActiveDay(idx)}
                className={`px-6 py-3 rounded-2xl whitespace-nowrap font-bold transition-all ${
                  activeDay === idx 
                    ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-200' 
                    : 'bg-white text-slate-500 border border-slate-100 hover:bg-slate-50'
                }`}
              >
                {plan.day}
              </button>
            ))}
          </div>

          {/* Meals for the day */}
          <div className="grid lg:grid-cols-3 gap-8">
            <MealSection title="Petit-Déjeuner" meal={mealPlan[activeDay].meals.breakfast} />
            <MealSection title="Déjeuner" meal={mealPlan[activeDay].meals.lunch} />
            <MealSection title="Dîner" meal={mealPlan[activeDay].meals.dinner} />
          </div>
        </>
      )}
    </div>
  );
};

const MealSection = ({ title, meal }: { title: string, meal: any }) => (
  <div className="bg-white rounded-[32px] overflow-hidden border border-slate-100 shadow-sm hover:shadow-md transition-all group">
    <div className="h-48 relative">
      <img 
        src={meal.image || `https://images.unsplash.com/photo-1493770348161-369560ae357d?auto=format&fit=crop&q=80&w=400`} 
        className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" 
        alt={meal.name} 
      />
      <div className="absolute top-4 left-4 px-3 py-1 bg-white/90 backdrop-blur rounded-lg text-xs font-bold text-slate-900">
        {title}
      </div>
      <div className="absolute bottom-4 right-4 px-3 py-1 bg-emerald-600 text-white rounded-lg text-xs font-bold">
        {meal.calories} kcal
      </div>
    </div>
    <div className="p-6">
      <h3 className="text-xl font-bold text-slate-900 mb-2">{meal.name}</h3>
      <p className="text-sm text-slate-500 mb-6 line-clamp-2">{meal.description}</p>

      <div className="mb-4">
        <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2">Ingrédients principaux</h4>
        <div className="flex flex-wrap gap-2">
          {meal.ingredients?.slice(0, 3).map((ing: string, i: number) => (
            <span key={i} className="px-2 py-1 bg-slate-50 text-[10px] font-semibold text-slate-600 rounded-md">
              {ing}
            </span>
          ))}
          {meal.ingredients?.length > 3 && <span className="text-[10px] text-slate-400">+{meal.ingredients.length - 3}</span>}
        </div>
      </div>

      <button className="w-full py-3 bg-emerald-50 text-emerald-600 font-bold rounded-xl text-sm hover:bg-emerald-100 transition-colors">
        Voir la recette
      </button>
    </div>
  </div>
);

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { useAuth } from '../App';
import { generateShoppingList } from '../services/gemini';
import { ShoppingListItem } from '../types';

const ShoppingList: React.FC = () => {
  const [list, setList] = useState<ShoppingListItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [supermarket, setSupermarket] = useState<'delhaize' | 'colruyt' | 'ah'>('delhaize');

  useEffect(() => {
    // In a real app, we'd pull the current meal plan from context or state
    const fetchList = async () => {
      setLoading(true);
      // Simulate providing the meal plan context
      try {
        const data = await generateShoppingList([]);
        setList(data);
      } catch (e) {
        console.error(e);
      } finally {
        setLoading(false);
      }
    };
    fetchList();
  }, []);

  const toggleItem = (index: number) => {
    setList(prev => prev.map((item, i) => i === index ? { ...item, checked: !item.checked } : item));
  };

  const categories = Array.from(new Set(list.map(item => item.category)));

  if (loading) {
    return (
      <div className="p-8 flex flex-col items-center justify-center min-h-[60vh]">
        <div className="w-16 h-16 border-4 border-emerald-600 border-t-transparent rounded-full animate-spin mb-4"></div>
        <p className="text-slate-500 font-medium">Préparation de votre liste de courses...</p>
      </div>
    );
  }

  return (
    <div className="p-6 max-w-4xl mx-auto">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-8">
        <div>
          <h1 className="text-3xl font-bold text-slate-900">Ma Liste de Courses</h1>
          <p className="text-slate-500">Optimisée pour votre semaine de repas.</p>
        </div>

        <div className="flex bg-slate-100 p-1 rounded-2xl">
          {(['delhaize', 'colruyt', 'ah'] as const).map(s => (
            <button
              key={s}
              onClick={() => setSupermarket(s)}
              className={`px-4 py-2 rounded-xl text-xs font-bold transition-all uppercase ${
                supermarket === s ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'
              }`}
            >
              {s}
            </button>
          ))}
        </div>
      </div>

      <div className="space-y-8">
        {categories.map(cat => (
          <div key={cat} className="bg-white rounded-3xl p-6 border border-slate-100 shadow-sm">
            <h3 className="text-sm font-bold text-slate-400 uppercase tracking-widest mb-4">{cat}</h3>
            <div className="space-y-3">
              {list.filter(i => i.category === cat).map((item, idx) => (
                <div 
                  key={idx} 
                  className="flex items-center gap-4 group cursor-pointer"
                  onClick={() => toggleItem(list.indexOf(item))}
                >
                  <div className={`w-6 h-6 rounded-lg border-2 flex items-center justify-center transition-all ${
                    item.checked ? 'bg-emerald-600 border-emerald-600' : 'border-slate-200 group-hover:border-emerald-300'
                  }`}>
                    {item.checked && <span className="text-white text-xs">✓</span>}
                  </div>
                  <div className="flex-grow flex justify-between items-center">
                    <span className={`text-slate-700 font-medium ${item.checked ? 'line-through text-slate-400' : ''}`}>
                      {item.item}
                    </span>
                    <span className="text-sm text-slate-400 bg-slate-50 px-2 py-1 rounded-md">{item.amount}</span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>

      <div className="mt-12 flex gap-4">
        <button className="flex-1 py-4 bg-emerald-600 text-white font-bold rounded-2xl hover:bg-emerald-700 shadow-lg shadow-emerald-100">
          Exporter vers le panier {supermarket.toUpperCase()}
        </button>
        <button className="px-6 py-4 bg-white border border-slate-200 text-slate-700 font-bold rounded-2xl hover:bg-slate-50">
          Imprimer PDF
        </button>
      </div>
    </div>
  );
};

export default ShoppingList;

