    try {
      const data = await generateMealPlan(selectedDiet, selectedAllergies);
      setMealPlan(data || []);
      setActiveDay(0);
    } catch (err) {
      console.error("Generation failed:", err);
      setMealPlan([]);
    } finally {
      setLoading(false);
    }
  };

  const currentDayPlan = mealPlan[activeDay];

  if (loading) {
    return (
      <div className="p-8 flex flex-col items-center justify-center min-h-[60vh]">
        <div className="w-20 h-20 border-4 border-emerald-600 border-t-transparent rounded-full animate-spin mb-6"></div>
