        <p className="text-slate-500 mt-2 italic">L'IA concocte des recettes {selectedDiet.toLowerCase()} sans {selectedAllergies.length ? selectedAllergies.join(', ') : 'allergènes'}.</p>
      </div>
    );
  }

  return (
    <div className="p-6 max-w-7xl mx-auto">
      {mealPlan.length > 0 ? (
        <>
          <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
            <div>
              <h1 className="text-3xl font-bold text-slate-900">Votre Semaine Nutriplan</h1>
              <p className="text-slate-500">Menu personnalisé : {selectedDiet} {selectedAllergies.length > 0 && `(Sans ${selectedAllergies.join(', ')})`}</p>
            </div>
            <button 
              onClick={() => setMealPlan([])} // Return to setup view
              className="px-6 py-3 bg-white border border-slate-200 rounded-xl text-sm font-bold text-slate-700 hover:bg-slate-50 transition-all shadow-sm"
            >
              Modifier les critères
            </button>
          </div>

          {/* Day Selector */}
          <div className="flex gap-2 mb-8 overflow-x-auto pb-2 no-scrollbar">
            {mealPlan.map((plan, idx) => (
              <button
                key={idx}
                onClick={() => setActiveDay(idx)}
                className={`px-6 py-3 rounded-2xl whitespace-nowrap font-bold transition-all ${
                  activeDay === idx 
                    ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-200' 
                    : 'bg-white text-slate-500 border border-slate-100 hover:bg-slate-50'
                }`}
              >
                {plan.day || `Jour ${idx + 1}`}
              </button>
            ))}
          </div>

          {/* Meals for the day */}
          <div className="grid lg:grid-cols-3 gap-8">
            <MealSection title="Petit-Déjeuner" meal={currentDayPlan?.meals?.breakfast} />
            <MealSection title="Déjeuner" meal={currentDayPlan?.meals?.lunch} />
            <MealSection title="Dîner" meal={currentDayPlan?.meals?.dinner} />
          </div>
        </>
      ) : (
        <div className="max-w-4xl mx-auto">
          <div className="text-center mb-12">
            <h1 className="text-4xl font-extrabold text-slate-900 mb-4">Créez votre menu sur-mesure</h1>
            <p className="text-slate-500">Sélectionnez vos préférences avant de générer votre semaine.</p>
          </div>

          <div className="bg-white rounded-[40px] p-8 md:p-12 shadow-xl shadow-slate-100 border border-slate-100">
            {/* Diet Selection Buttons */}
            <div className="mb-10">
              <h3 className="text-lg font-bold text-slate-800 mb-6 flex items-center gap-2">
                <span>🥗</span> Choisissez votre régime
              </h3>
              <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-6 gap-3">
                {Object.values(DietPreference).map(pref => (
                  <button
                    key={pref}
                    onClick={() => setSelectedDiet(pref)}
                    className={`flex flex-col items-center justify-center p-4 rounded-2xl border-2 transition-all ${
                      selectedDiet === pref 
                        ? 'border-emerald-600 bg-emerald-50 text-emerald-700 shadow-md' 
                        : 'border-slate-100 bg-white text-slate-400 hover:border-emerald-200'
                    }`}
                  >
                    <span className="text-xl mb-1">{getEmoji(pref)}</span>
                    <span className="text-[10px] font-bold uppercase tracking-tighter">{pref}</span>
                  </button>
                ))}
              </div>
            </div>

            {/* Quick Allergy Buttons */}
            <div className="mb-12">
              <h3 className="text-lg font-bold text-slate-800 mb-6 flex items-center gap-2">
                <span>🚫</span> Allergies à exclure
              </h3>
              <div className="flex flex-wrap gap-3">
                {['Gluten', 'Lactose', 'Arachides', 'Fruits à coque', 'Oeufs', 'Soja'].map(allergy => (
                  <button
                    key={allergy}
                    onClick={() => toggleAllergy(allergy)}
                    className={`px-6 py-3 rounded-full border-2 font-bold text-sm transition-all ${
                      selectedAllergies.includes(allergy)
                        ? 'bg-red-500 border-red-500 text-white shadow-md'
                        : 'bg-white border-slate-100 text-slate-500 hover:bg-slate-50'
                    }`}
                  >
                    {allergy}
                  </button>
                ))}
              </div>
            </div>

            <button 
              onClick={handleGenerate}
              className="w-full py-5 bg-emerald-600 text-white font-black text-lg rounded-3xl hover:bg-emerald-700 transition-all shadow-xl shadow-emerald-200 flex items-center justify-center gap-3"
            >
              <span>✨</span> GÉNÉRER MON MENU PERSONNALISÉ
            </button>

            <p className="text-center text-slate-400 text-xs mt-6">
              L'intelligence artificielle créera un menu équilibré basé sur ces critères.
            </p>
          </div>
        </div>
      )}
    </div>
  );
};

const getEmoji = (pref: DietPreference) => {
  switch (pref) {
    case DietPreference.OMNIVORE: return '🍗';
    case DietPreference.VEGETARIAN: return '🥕';
    case DietPreference.VEGAN: return '🌿';
    case DietPreference.KETO: return '🥑';
    case DietPreference.PALEO: return '🥩';
    case DietPreference.GLUTEN_FREE: return '🌾';
    default: return '🍽️';
  }
};

const MealSection = ({ title, meal }: { title: string, meal?: Meal }) => {
  if (!meal) return null;

  return (
    <div className="bg-white rounded-[32px] overflow-hidden border border-slate-100 shadow-sm hover:shadow-md transition-all group">
      <div className="h-48 relative">
        <img 
          src={meal.image || `https://images.unsplash.com/photo-1493770348161-369560ae357d?auto=format&fit=crop&q=80&w=400`} 
          className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" 
          alt={meal.name} 
        />
        <div className="absolute top-4 left-4 px-3 py-1 bg-white/90 backdrop-blur rounded-lg text-xs font-bold text-slate-900">
          {title}
        </div>
        <div className="absolute bottom-4 right-4 px-3 py-1 bg-emerald-600 text-white rounded-lg text-xs font-bold">
          {meal.calories || 0} kcal
        </div>
      </div>
      <div className="p-6">
        <h3 className="text-xl font-bold text-slate-900 mb-2 leading-tight">{meal.name}</h3>
        <p className="text-sm text-slate-500 mb-6 line-clamp-2">{meal.description}</p>

        <div className="mb-4">
          <h4 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-2">Ingrédients</h4>
          <div className="flex flex-wrap gap-2">
            {meal.ingredients?.slice(0, 3).map((ing: string, i: number) => (
              <span key={i} className="px-2 py-1 bg-slate-50 text-[10px] font-semibold text-slate-600 rounded-md">
                {ing}
              </span>
            ))}
            {(meal.ingredients?.length || 0) > 3 && (
              <span className="text-[10px] text-slate-400">+{meal.ingredients.length - 3}</span>
            )}
          </div>
        </div>

        <button className="w-full py-3 bg-emerald-50 text-emerald-600 font-bold rounded-xl text-sm hover:bg-emerald-100 transition-colors">
          Voir la recette
        </button>
      </div>
    </div>
  );
};

