        <form onSubmit={handleSubmit} className="space-y-6 relative">
          <div>
            <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Email</label>
            <input 
              type="email" 
              required
              className="w-full px-6 py-5 bg-slate-50 border border-slate-100 rounded-2xl focus:ring-4 focus:ring-emerald-500/10 focus:bg-white focus:border-emerald-500 outline-none transition-all font-medium text-slate-700"
              placeholder="votre@email.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
            />
          </div>
          <div>
            <div className="flex justify-between items-center mb-2 ml-1">
              <label className="block text-xs font-black text-slate-400 uppercase tracking-widest">Mot de passe</label>
              {isLogin && <button type="button" className="text-[10px] font-bold text-emerald-600 hover:underline">Oublié ?</button>}
            </div>
            <input 
              type="password" 
              required
              className="w-full px-6 py-5 bg-slate-50 border border-slate-100 rounded-2xl focus:ring-4 focus:ring-emerald-500/10 focus:bg-white focus:border-emerald-500 outline-none transition-all font-medium text-slate-700"
              placeholder="••••••••"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
            />
          </div>

          <button 
            type="submit"
            disabled={authState.isLoading}
            className="w-full py-5 bg-emerald-600 text-white font-black rounded-[20px] hover:bg-emerald-700 transition-all shadow-xl shadow-emerald-100 disabled:opacity-50 flex items-center justify-center gap-2"
          >
            {authState.isLoading ? (
              <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
            ) : isLogin ? 'SE CONNECTER' : "CRÉER MON COMPTE"}
          </button>
        </form>

        <div className="mt-10 text-center relative">
          <button 
            onClick={() => setIsLogin(!isLogin)}
            className="text-xs font-bold text-slate-500 hover:text-emerald-600 transition-colors"
          >
            {isLogin ? "Nouveau sur Nutriplan ? S'inscrire" : "Déjà membre ? Se connecter"}
          </button>
        </div>

        {/* Info for tester */}
        <div className="mt-8 p-4 bg-amber-50 rounded-2xl border border-amber-100 text-[10px] font-bold text-amber-700 leading-relaxed">
          COMPTE TEST DÉTECTÉ :<br/>
          Email: Test@gmail.com | Mdp: test1234
        </div>
      </div>
    </div>
  );
};

export default Auth;

export enum DietPreference {
  OMNIVORE = 'Omnivore',
  VEGETARIAN = 'Végétarien',
  VEGAN = 'Végan',
  KETO = 'Keto',
  PALEO = 'Paléo',
  GLUTEN_FREE = 'Sans Gluten'
}

export interface User {
  id: string;
  name: string;
  email: string;
  diet: DietPreference;
  allergies: string[];
  subscriptionType: 'free' | 'premium';
}

export interface Meal {
  id: string;
  name: string;
  description: string;
  calories: number;
  ingredients: string[];
  instructions: string[];
  image: string;
  type: 'breakfast' | 'lunch' | 'dinner';
}

export interface DayPlan {
  day: string;
  meals: {
    breakfast: Meal;
    lunch: Meal;
    dinner: Meal;
  };
}

export interface SavedPlan {
  id: string;
  name: string;
  date: string;
  plan: DayPlan[];
  diet: DietPreference;
}

export interface ShoppingListItem {
  item: string;
  amount: string;
  category: string;
  checked: boolean;
}

export interface AuthState {
  user: User | null;
  token: string | null;
  isAuthenticated: boolean;
  isLoading: boolean;
}

import React, { useState, createContext, useContext, useEffect } from 'react';
import { DietPreference, User, AuthState, DayPlan, SavedPlan } from './types';
import LandingPage from './pages/LandingPage';
import Dashboard from './pages/Dashboard';
import Auth from './pages/Auth';
import Preferences from './pages/Preferences';
import ShoppingList from './pages/ShoppingList';
import Subscription from './pages/Subscription';
import Navbar from './components/Navbar';

interface AppContextType {
  authState: AuthState;
  login: (email: string, pass: string) => Promise<void>;
  logout: () => void;
  updateUser: (data: Partial<User>) => void;
  currentMealPlan: DayPlan[] | null;
  setCurrentMealPlan: (plan: DayPlan[] | null) => void;
  savedPlans: SavedPlan[];
  saveCurrentPlan: (name: string) => void;
}

const AppContext = createContext<AppContextType | null>(null);

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useApp must be used within AppProvider");
  return context;
};

// Alias for backwards compatibility if needed in some components
export const useAuth = useApp;

const App: React.FC = () => {
  const [view, setView] = useState<'landing' | 'auth' | 'dashboard' | 'preferences' | 'shopping' | 'subscription'>('landing');
  const [currentMealPlan, setCurrentMealPlan] = useState<DayPlan[] | null>(null);
  const [savedPlans, setSavedPlans] = useState<SavedPlan[]>([]);

  const [authState, setAuthState] = useState<AuthState>({
    user: null,
    token: null,
    isAuthenticated: false,
    isLoading: false
  });

  const login = async (email: string, pass: string) => {
    setAuthState(prev => ({ ...prev, isLoading: true }));
    await new Promise(resolve => setTimeout(resolve, 800));

    const isTestAccount = email.toLowerCase() === 'test@gmail.com' && pass === 'test1234';

    const mockUser: User = {
      id: '1',
      name: isTestAccount ? 'Test User' : 'Utilisateur Nutriplan',
      email: email,
      diet: DietPreference.OMNIVORE,
      allergies: [],
      subscriptionType: 'free'
    };

    setAuthState({
      user: mockUser,
      token: 'fake-jwt-token',
      isAuthenticated: true,
      isLoading: false
    });
    setView('dashboard');
  };

  const logout = () => {
    setAuthState({ user: null, token: null, isAuthenticated: false, isLoading: false });
    setCurrentMealPlan(null);
    setView('landing');
  };

  const updateUser = (data: Partial<User>) => {
    if (authState.user) {
      setAuthState(prev => ({
        ...prev,
        user: { ...prev.user!, ...data }
      }));
    }
  };

  const saveCurrentPlan = (name: string) => {
    if (!currentMealPlan || !authState.user) return;
    const newSavedPlan: SavedPlan = {
      id: Math.random().toString(36).substr(2, 9),
      name: name || `Menu du ${new Date().toLocaleDateString()}`,
      date: new Date().toISOString(),
      plan: currentMealPlan,
      diet: authState.user.diet
    };
    setSavedPlans(prev => [newSavedPlan, ...prev]);
  };

  const renderView = () => {
    switch (view) {
      case 'landing': return <LandingPage onGetStarted={() => setView('auth')} />;
      case 'auth': return <Auth />;
      case 'dashboard': return <Dashboard />;
      case 'preferences': return <Preferences />;
      case 'shopping': return <ShoppingList />;
      case 'subscription': return <Subscription />;
      default: return <LandingPage onGetStarted={() => setView('auth')} />;
    }
  };

  return (
    <AppContext.Provider value={{ 
      authState, login, logout, updateUser, 
      currentMealPlan, setCurrentMealPlan, 
      savedPlans, saveCurrentPlan 
    }}>
      <div className="min-h-screen flex flex-col bg-slate-50">
        {authState.isAuthenticated && <Navbar currentView={view} setView={setView} />}
        <main className="flex-grow">
          {renderView()}
        </main>
      </div>
    </AppContext.Provider>
  );
};

export default App;

import React, { useState } from 'react';
import { useApp } from '../App';
import { generateMealPlan } from '../services/gemini';
import { DayPlan, DietPreference, Meal } from '../types';

const Dashboard: React.FC = () => {
  const { authState, updateUser, currentMealPlan, setCurrentMealPlan, savedPlans, saveCurrentPlan } = useApp();
  const [loading, setLoading] = useState(false);
  const [activeDay, setActiveDay] = useState(0);
  const [isSaving, setIsSaving] = useState(false);
  const [saveName, setSaveName] = useState('');

  // Local state for setup
  const [tempDiet, setTempDiet] = useState<DietPreference>(authState.user?.diet || DietPreference.OMNIVORE);
  const [tempAllergies, setTempAllergies] = useState<string[]>(authState.user?.allergies || []);

  const toggleAllergy = (allergy: string) => {
    setTempAllergies(prev => 
      prev.includes(allergy) ? prev.filter(a => a !== allergy) : [...prev, allergy]
    );
  };

  const handleGenerate = async () => {
    if (!authState.user) return;
    updateUser({ diet: tempDiet, allergies: tempAllergies });
    setLoading(true);
    try {
      const data = await generateMealPlan(tempDiet, tempAllergies);
      setCurrentMealPlan(data || []);
      setActiveDay(0);
    } catch (err) {
      console.error("Erreur génération:", err);
    } finally {
      setLoading(false);
    }
  };

  const handleSavePlan = () => {
    if (!saveName) {
      alert("Donnez un nom à votre dossier !");
      return;
    }
    saveCurrentPlan(saveName);
    setIsSaving(false);
    setSaveName('');
    alert("Menu enregistré dans vos dossiers !");
  };

  if (loading) {
    return (
      <div className="p-8 flex flex-col items-center justify-center min-h-[60vh]">
        <div className="w-20 h-20 border-4 border-emerald-600 border-t-transparent rounded-full animate-spin mb-6"></div>
        <p className="text-xl font-bold text-slate-900">IA en action...</p>
        <p className="text-slate-500 mt-2">Création d'un menu {tempDiet.toLowerCase()} sans {tempAllergies.length ? tempAllergies.join(', ') : 'allergènes'}.</p>
      </div>
    );
  }

  return (
    <div className="p-6 max-w-7xl mx-auto">
      <div className="grid lg:grid-cols-4 gap-8">

        {/* Sidebar: Mes Dossiers / Historique */}
        <aside className="lg:col-span-1 space-y-6">
          <div className="bg-white rounded-3xl p-6 shadow-sm border border-slate-100">
            <h3 className="text-sm font-black text-slate-400 uppercase tracking-widest mb-4">📂 Mes Dossiers</h3>
            <div className="space-y-3">
              {savedPlans.length === 0 ? (
                <p className="text-xs text-slate-400 italic">Aucun menu enregistré.</p>
              ) : (
                savedPlans.map(plan => (
                  <button 
                    key={plan.id}
                    onClick={() => setCurrentMealPlan(plan.plan)}
                    className="w-full text-left p-3 rounded-xl hover:bg-emerald-50 border border-transparent hover:border-emerald-100 transition-all group"
                  >
                    <p className="text-sm font-bold text-slate-700 group-hover:text-emerald-700">{plan.name}</p>
                    <p className="text-[10px] text-slate-400">{new Date(plan.date).toLocaleDateString()}</p>
                  </button>
                ))
              )}
            </div>
          </div>

          <div className="bg-emerald-600 rounded-3xl p-6 text-white shadow-lg shadow-emerald-100">
            <h4 className="font-bold mb-2">💡 Astuce</h4>
            <p className="text-xs opacity-90 leading-relaxed">Générez un menu, puis enregistrez-le pour le retrouver plus tard dans vos dossiers !</p>
          </div>
        </aside>

        {/* Main Content */}
        <div className="lg:col-span-3">
          {currentMealPlan && currentMealPlan.length > 0 ? (
            <>
              <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
                <div>
                  <h1 className="text-3xl font-bold text-slate-900">Menu Actuel</h1>
                  <div className="flex flex-wrap gap-2 mt-2">
                    <span className="px-3 py-1 bg-emerald-100 text-emerald-700 text-[10px] font-bold rounded-full uppercase">{authState.user?.diet}</span>
                    {authState.user?.allergies.map(a => (
                      <span key={a} className="px-3 py-1 bg-red-50 text-red-600 text-[10px] font-bold rounded-full uppercase">Sans {a}</span>
                    ))}
                  </div>
                </div>
                <div className="flex gap-3">
                  <button 
                    onClick={() => setIsSaving(true)}
                    className="px-5 py-3 bg-white border border-slate-200 rounded-xl text-sm font-bold text-slate-700 hover:bg-slate-50 transition-all shadow-sm"
                  >
                    💾 Enregistrer
                  </button>
                  <button 
                    onClick={() => setCurrentMealPlan(null)}
                    className="px-5 py-3 bg-slate-900 text-white rounded-xl text-sm font-bold hover:bg-slate-800 transition-all shadow-sm"
                  >
                    🆕 Nouveau
                  </button>
                </div>
              </div>

              {isSaving && (
                <div className="mb-8 p-6 bg-emerald-50 border border-emerald-100 rounded-3xl flex flex-col sm:flex-row gap-4 items-center">
                  <input 
                    type="text" 
                    placeholder="Nom du menu (ex: Semaine Detox Janvier)"
                    className="flex-grow px-4 py-3 rounded-xl border border-emerald-200 outline-none focus:ring-2 focus:ring-emerald-500"
                    value={saveName}
                    onChange={(e) => setSaveName(e.target.value)}
                  />
                  <div className="flex gap-2">
                    <button onClick={handleSavePlan} className="px-6 py-3 bg-emerald-600 text-white font-bold rounded-xl text-sm">Confirmer</button>
                    <button onClick={() => setIsSaving(false)} className="px-6 py-3 bg-white text-slate-500 font-bold rounded-xl text-sm border border-slate-200">Annuler</button>
                  </div>
                </div>
              )}

              <div className="flex gap-2 mb-8 overflow-x-auto pb-2 no-scrollbar">
                {currentMealPlan.map((plan, idx) => (
                  <button
                    key={idx}
                    onClick={() => setActiveDay(idx)}
                    className={`px-6 py-3 rounded-2xl whitespace-nowrap font-bold transition-all ${
                      activeDay === idx 
                        ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-200' 
                        : 'bg-white text-slate-500 border border-slate-100 hover:bg-slate-50'
                    }`}
                  >
                    {plan.day || `Jour ${idx + 1}`}
                  </button>
                ))}
              </div>

              <div className="grid md:grid-cols-3 gap-6">
                <MealCard title="Petit-Déjeuner" meal={currentMealPlan[activeDay]?.meals?.breakfast} />
                <MealCard title="Déjeuner" meal={currentMealPlan[activeDay]?.meals?.lunch} />
                <MealCard title="Dîner" meal={currentMealPlan[activeDay]?.meals?.dinner} />
              </div>
            </>
          ) : (
            <div className="bg-white rounded-[40px] p-8 md:p-12 shadow-2xl shadow-slate-200 border border-slate-100">
              <div className="text-center mb-10">
                <h2 className="text-3xl font-extrabold text-slate-900 mb-2">Créez votre Menu</h2>
                <p className="text-slate-500">Choisissez vos préférences et laissez l'IA travailler.</p>
              </div>

              <div className="space-y-10">
                <div>
                  <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-4">Régime Alimentaire</label>
                  <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
                    {Object.values(DietPreference).map(pref => (
                      <button
                        key={pref}
                        onClick={() => setTempDiet(pref)}
                        className={`flex flex-col items-center justify-center p-4 rounded-2xl border-2 transition-all ${
                          tempDiet === pref ? 'border-emerald-600 bg-emerald-50 text-emerald-700' : 'border-slate-50 bg-slate-50/50 text-slate-400'
                        }`}
                      >
                        <span className="text-2xl mb-1">{getDietEmoji(pref)}</span>
                        <span className="text-[10px] font-bold uppercase">{pref}</span>
                      </button>
                    ))}
                  </div>
                </div>

                <div>
                  <label className="block text-xs font-black text-slate-400 uppercase tracking-widest mb-4">Allergies (Profil Test)</label>
                  <div className="flex flex-wrap gap-2">
                    {['Gluten', 'Lactose', 'Arachides', 'Oeufs', 'Soja'].map(allergy => (
                      <button
                        key={allergy}
                        onClick={() => toggleAllergy(allergy)}
                        className={`px-4 py-2 rounded-xl border-2 font-bold text-xs transition-all ${
                          tempAllergies.includes(allergy) ? 'bg-red-500 border-red-500 text-white' : 'bg-white border-slate-100 text-slate-500'
                        }`}
                      >
                        {allergy}
                      </button>
                    ))}
                  </div>
                </div>

                <button 
                  onClick={handleGenerate}
                  className="w-full py-5 bg-emerald-600 text-white font-black text-lg rounded-3xl hover:bg-emerald-700 transition-all shadow-xl shadow-emerald-200"
                >
                  ✨ GÉNÉRER LE MENU SEMAINE
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

const getDietEmoji = (pref: DietPreference) => {
  switch (pref) {
    case DietPreference.OMNIVORE: return '🍗';
    case DietPreference.VEGETARIAN: return '🥕';
    case DietPreference.VEGAN: return '🌿';
    case DietPreference.KETO: return '🥑';
    case DietPreference.PALEO: return '🥩';
    case DietPreference.GLUTEN_FREE: return '🌾';
    default: return '🍽️';
  }
};

const MealCard = ({ title, meal }: { title: string, meal?: Meal }) => {
  if (!meal) return null;
  return (
    <div className="bg-white rounded-[32px] overflow-hidden border border-slate-100 shadow-sm hover:shadow-xl transition-all group flex flex-col h-full">
      <div className="h-44 relative overflow-hidden">
        <img src={meal.image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" alt={meal.name} />
        <div className="absolute top-3 left-3 px-3 py-1 bg-white/90 backdrop-blur rounded-xl text-[9px] font-black text-slate-900 uppercase tracking-wider">{title}</div>
      </div>
      <div className="p-5 flex flex-col flex-grow">
        <h3 className="font-bold text-slate-900 mb-1 leading-tight">{meal.name}</h3>
        <p className="text-[10px] text-slate-400 line-clamp-2 mb-4 leading-relaxed">{meal.description}</p>
        <div className="mt-auto pt-4 border-t border-slate-50 flex justify-between items-center">
          <span className="text-[10px] font-bold text-emerald-600">{meal.calories} kcal</span>
          <button className="text-[10px] font-black uppercase text-slate-900 hover:text-emerald-600 transition-colors">Recette →</button>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { useApp } from '../App';
import { generateShoppingList } from '../services/gemini';
import { ShoppingListItem } from '../types';

const ShoppingList: React.FC = () => {
  const { currentMealPlan } = useApp();
  const [list, setList] = useState<ShoppingListItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [exporting, setExporting] = useState(false);
  const [supermarket, setSupermarket] = useState<'delhaize' | 'colruyt' | 'ah'>('delhaize');

  useEffect(() => {
    const fetchList = async () => {
      if (!currentMealPlan || currentMealPlan.length === 0) {
        setList([]);
        return;
      }
      setLoading(true);
      try {
        const data = await generateShoppingList(currentMealPlan);
        setList(data);
      } catch (e) {
        console.error(e);
      } finally {
        setLoading(false);
      }
    };
    fetchList();
  }, [currentMealPlan]);

  const handleExportDelhaize = async () => {
    setExporting(true);
    // Simulation d'exportation réelle vers Delhaize.be via API ou deep linking
    // Dans une app réelle, on pourrait construire un lien de panier ou appeler leur API partenaire.
    await new Promise(resolve => setTimeout(resolve, 2000));

    const itemsToExport = list.filter(i => !i.checked);
    console.log("Exportation vers Delhaize de :", itemsToExport);

    alert(`Succès ! ${itemsToExport.length} articles ont été ajoutés à votre panier Delhaize.be via Nutriplan.`);
    setExporting(false);
  };

  const toggleItem = (index: number) => {
    setList(prev => prev.map((item, i) => i === index ? { ...item, checked: !item.checked } : item));
  };

  const categories = Array.from(new Set(list.map(item => item.category)));

  if (loading) {
    return (
      <div className="p-8 flex flex-col items-center justify-center min-h-[60vh]">
        <div className="w-16 h-16 border-4 border-emerald-600 border-t-transparent rounded-full animate-spin mb-4"></div>
        <p className="text-slate-500 font-medium">Analyse des ingrédients et création de la liste...</p>
      </div>
    );
  }

  if (!currentMealPlan || currentMealPlan.length === 0) {
    return (
      <div className="p-12 text-center flex flex-col items-center justify-center min-h-[60vh]">
        <div className="text-6xl mb-6">🛒</div>
        <h2 className="text-2xl font-bold text-slate-900 mb-2">Liste de courses vide</h2>
        <p className="text-slate-500 mb-8 max-w-sm">Générez d'abord un menu hebdomadaire pour obtenir votre liste automatique.</p>
      </div>
    );
  }

  return (
    <div className="p-6 max-w-4xl mx-auto">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-8">
        <div>
          <h1 className="text-3xl font-bold text-slate-900">Ma Liste de Courses</h1>
          <p className="text-slate-500">Optimisée pour Delhaize, Colruyt et Albert Heijn.</p>
        </div>

        <div className="flex bg-slate-100 p-1 rounded-2xl">
