import React, { useState, useEffect } from 'react';
import { useApp } from '../App';
import { generateShoppingList } from '../services/gemini';
import { ShoppingListItem } from '../types';

const ShoppingList: React.FC = () => {
  const { currentMealPlan } = useApp();
  const [list, setList] = useState<ShoppingListItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [exportStep, setExportStep] = useState<number | null>(null);
  const [supermarket, setSupermarket] = useState<'delhaize' | 'colruyt' | 'ah'>('delhaize');

  useEffect(() => {
    const fetchList = async () => {
      if (!currentMealPlan || currentMealPlan.length === 0) {
        setList([]);
        return;
      }
      setLoading(true);
      try {
        const data = await generateShoppingList(currentMealPlan);
        setList(data);
      } catch (e) {
        console.error(e);
      } finally {
        setLoading(false);
      }
    };
    fetchList();
  }, [currentMealPlan]);

  const handleExportDelhaize = async () => {
    const itemsToExport = list.filter(i => !i.checked);
    if (itemsToExport.length === 0) {
      alert("Votre liste est vide ou tous les articles sont déjà cochés !");
      return;
    }

    setExportStep(0);

    // Simulation de l'automatisation demandée
    // On parcourt les articles un par un avec un délai pour simuler le remplissage du panier
    for (let i = 0; i <= itemsToExport.length; i++) {
      await new Promise(resolve => setTimeout(resolve, 600)); // Temps de "recherche" par article
      setExportStep(i);
    }

    // Finalisation
    setTimeout(() => {
      setExportStep(null);
      // Redirection vers le checkout delhaize comme demandé
      window.open('https://www.delhaize.be/checkout', '_blank');
      alert(`Synchronisation terminée ! Vos ${itemsToExport.length} articles ont été préparés pour Delhaize.be.\n\nNote: Pour des raisons de sécurité, veuillez valider les produits suggérés dans votre panier sur Delhaize.`);
    }, 1000);
  };

  const toggleItem = (index: number) => {
    setList(prev => prev.map((item, i) => i === index ? { ...item, checked: !item.checked } : item));
  };

  const categories = Array.from(new Set(list.map(item => item.category)));

  if (loading) {
    return (
      <div className="p-8 flex flex-col items-center justify-center min-h-[60vh]">
        <div className="w-16 h-16 border-4 border-emerald-600 border-t-transparent rounded-full animate-spin mb-4"></div>
        <p className="text-slate-500 font-medium">Analyse des ingrédients par l'IA...</p>
      </div>
    );
  }

  const itemsToExport = list.filter(i => !i.checked);

  return (
    <div className="p-6 max-w-4xl mx-auto relative">
      {/* Overlay d'exportation "Ne rien toucher" */}
      {exportStep !== null && (
        <div className="fixed inset-0 z-[100] bg-slate-900/90 backdrop-blur-md flex items-center justify-center p-6 text-center">
          <div className="max-w-md w-full bg-white rounded-[40px] p-10 shadow-2xl">
            <div className="mb-8">
              <div className="w-24 h-24 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center text-4xl mx-auto mb-6 animate-pulse">
                🛒
              </div>
              <h2 className="text-2xl font-black text-slate-900 mb-2">Exportation en cours...</h2>
              <p className="text-red-500 font-bold text-sm uppercase tracking-widest">⚠️ Ne rien toucher et ne pas fermer l'application</p>
            </div>

            <div className="space-y-4 mb-8">
              <div className="h-3 w-full bg-slate-100 rounded-full overflow-hidden">
                <div 
                  className="h-full bg-emerald-500 transition-all duration-500 ease-out" 
                  style={{ width: `${(exportStep / itemsToExport.length) * 100}%` }}
                ></div>
              </div>
              <div className="flex justify-between text-[10px] font-black text-slate-400 uppercase">
                <span>Synchronisation Panier</span>
                <span>{exportStep} / {itemsToExport.length} articles</span>
              </div>
            </div>

            <div className="bg-slate-50 rounded-2xl p-4 text-left h-32 overflow-hidden relative">
              <div className="space-y-2">
                {itemsToExport.map((item, idx) => (
                  <div key={idx} className={`flex items-center gap-2 text-xs transition-opacity duration-300 ${idx < exportStep ? 'text-emerald-600 font-bold' : idx === exportStep ? 'text-slate-900 animate-pulse' : 'text-slate-300'}`}>
                    <span>{idx < exportStep ? '✓' : '•'}</span>
                    <span>Recherche de "{item.item}" sur Delhaize.be...</span>
                  </div>
                ))}
              </div>
              <div className="absolute bottom-0 left-0 right-0 h-12 bg-gradient-to-t from-slate-50 to-transparent"></div>
            </div>

            <p className="text-[10px] text-slate-400 mt-6 leading-relaxed italic">
              Nutriplan interagit avec le sélecteur "header-search-bar-input" pour préparer votre commande.
            </p>
          </div>
        </div>
      )}

      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-8">
        <div>
          <h1 className="text-3xl font-bold text-slate-900">Ma Liste de Courses</h1>
          <p className="text-slate-500">Gérée automatiquement selon votre menu de la semaine.</p>
        </div>

        <div className="flex bg-slate-100 p-1 rounded-2xl">
          {(['delhaize', 'colruyt', 'ah'] as const).map(s => (
            <button
              key={s}
              onClick={() => setSupermarket(s)}
              className={`px-4 py-2 rounded-xl text-xs font-bold transition-all uppercase ${
                supermarket === s ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'
              }`}
            >
              {s}
            </button>
          ))}
        </div>
      </div>

      <div className="space-y-8">
        {categories.length > 0 ? categories.map(cat => (
          <div key={cat} className="bg-white rounded-3xl p-6 border border-slate-100 shadow-sm">
            <h3 className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-4">{cat}</h3>
            <div className="space-y-3">
              {list.filter(i => i.category === cat).map((item, idx) => {
                const globalIndex = list.findIndex(li => li === item);
                return (
                  <div 
                    key={idx} 
                    className="flex items-center gap-4 group cursor-pointer"
                    onClick={() => toggleItem(globalIndex)}
                  >
                    <div className={`w-6 h-6 rounded-lg border-2 flex items-center justify-center transition-all ${
                      item.checked ? 'bg-emerald-600 border-emerald-600' : 'border-slate-200 group-hover:border-emerald-300'
                    }`}>
                      {item.checked && <span className="text-white text-xs">✓</span>}
                    </div>
                    <div className="flex-grow flex justify-between items-center">
                      <span className={`text-slate-700 font-medium ${item.checked ? 'line-through text-slate-400' : ''}`}>
                        {item.item}
                      </span>
                      <span className="text-sm text-slate-400 bg-slate-50 px-2 py-1 rounded-md">{item.amount}</span>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )) : (
          <div className="p-12 text-center bg-white rounded-[40px] border border-dashed border-slate-200">
            <div className="text-5xl mb-4 opacity-20">🛒</div>
            <p className="text-slate-400 font-medium">Aucun article dans la liste.</p>
          </div>
        )}
      </div>

      {list.length > 0 && (
        <div className="mt-12 flex flex-col sm:flex-row gap-4 sticky bottom-6 z-10">
          {supermarket === 'delhaize' ? (
            <button 
              onClick={handleExportDelhaize}
              className="flex-grow py-5 bg-emerald-600 text-white font-black rounded-2xl hover:bg-emerald-700 shadow-2xl shadow-emerald-200 flex items-center justify-center gap-3 transition-transform active:scale-95"
            >
              <span>🛒</span> EXPORTER VERS DELHAIZE.BE
            </button>
          ) : (
            <button 
              disabled
              className="flex-grow py-5 bg-slate-200 text-slate-400 font-bold rounded-2xl cursor-not-allowed"
            >
              EXPORT {supermarket.toUpperCase()} PRÉVU PROCHAINEMENT
            </button>
          )}
          <button className="px-8 py-5 bg-white border border-slate-200 text-slate-700 font-bold rounded-2xl hover:bg-slate-50 transition-all">
            Imprimer
          </button>
        </div>
      )}
    </div>
  );
};

export default ShoppingList;

import React, { useState } from 'react';
import { useApp } from '../App';
import { generateMealPlan } from '../services/gemini';
import { DayPlan, DietPreference, Meal } from '../types';

const Dashboard: React.FC = () => {
  const { authState, updateUser, currentMealPlan, setCurrentMealPlan, savedPlans, saveCurrentPlan } = useApp();
  const [loading, setLoading] = useState(false);
  const [activeDay, setActiveDay] = useState(0);
  const [isSaving, setIsSaving] = useState(false);
  const [saveName, setSaveName] = useState('');

  // Local state for setup
  const [tempDiet, setTempDiet] = useState<DietPreference>(authState.user?.diet || DietPreference.OMNIVORE);
  const [tempAllergies, setTempAllergies] = useState<string[]>(authState.user?.allergies || []);

  const toggleAllergy = (allergy: string) => {
    setTempAllergies(prev => 
      prev.includes(allergy) ? prev.filter(a => a !== allergy) : [...prev, allergy]
    );
  };

  const handleGenerate = async () => {
    if (!authState.user) return;
    updateUser({ diet: tempDiet, allergies: tempAllergies });
    setLoading(true);
    try {
      const data = await generateMealPlan(tempDiet, tempAllergies);
      setCurrentMealPlan(data || []);
      setActiveDay(0);
    } catch (err) {
      console.error("Erreur génération:", err);
    } finally {
      setLoading(false);
    }
  };

  const handleSavePlan = () => {
    if (!saveName) {
      alert("Donnez un nom à votre dossier !");
      return;
    }
    saveCurrentPlan(saveName);
    setIsSaving(false);
    setSaveName('');
    alert("Menu enregistré dans vos dossiers !");
  };

  if (loading) {
    return (
      <div className="p-8 flex flex-col items-center justify-center min-h-[60vh]">
        <div className="w-20 h-20 border-4 border-emerald-600 border-t-transparent rounded-full animate-spin mb-6"></div>
        <p className="text-xl font-bold text-slate-900">IA Nutriplan en cours...</p>
        <p className="text-slate-500 mt-2 italic">Préparation de vos recettes {tempDiet.toLowerCase()}...</p>
      </div>
    );
