  return (
    <div className="p-6 max-w-7xl mx-auto">
      <div className="grid lg:grid-cols-4 gap-8">

        {/* Sidebar: Mes Dossiers */}
        <aside className="lg:col-span-1 space-y-6">
          <div className="bg-white rounded-[32px] p-6 shadow-sm border border-slate-100">
            <h3 className="text-xs font-black text-slate-400 uppercase tracking-[0.2em] mb-6">📂 Mes Dossiers</h3>
            <div className="space-y-4">
              {savedPlans.length === 0 ? (
                <div className="p-4 bg-slate-50 rounded-2xl border border-dashed border-slate-200">
                  <p className="text-[10px] text-slate-400 italic text-center">Aucun menu enregistré.</p>
                </div>
              ) : (
                savedPlans.map(plan => (
                  <button 
                    key={plan.id}
                    onClick={() => {
                      setCurrentMealPlan(plan.plan);
                      setActiveDay(0);
                    }}
                    className={`w-full text-left p-4 rounded-2xl transition-all group flex flex-col gap-1 border ${
                      JSON.stringify(currentMealPlan) === JSON.stringify(plan.plan) 
                        ? 'bg-emerald-50 border-emerald-100 shadow-sm' 
                        : 'bg-white border-transparent hover:bg-slate-50'
                    }`}
                  >
                    <p className={`text-sm font-bold ${JSON.stringify(currentMealPlan) === JSON.stringify(plan.plan) ? 'text-emerald-700' : 'text-slate-700'}`}>
                      {plan.name}
                    </p>
                    <p className="text-[10px] text-slate-400 font-medium">{new Date(plan.date).toLocaleDateString()} • {plan.diet}</p>
                  </button>
                ))
              )}
            </div>
          </div>

          <div className="bg-gradient-to-br from-emerald-600 to-teal-700 rounded-[32px] p-6 text-white shadow-xl shadow-emerald-100 relative overflow-hidden">
            <div className="absolute top-0 right-0 w-24 h-24 bg-white/10 rounded-full -mr-10 -mt-10 blur-xl"></div>
            <h4 className="font-bold mb-2 flex items-center gap-2"><span>💡</span> Astuce IA</h4>
            <p className="text-[11px] opacity-90 leading-relaxed font-medium">
              Chaque génération est unique. Si un menu vous plaît, n'oubliez pas de l'enregistrer dans un dossier !
            </p>
          </div>
        </aside>

        {/* Main Content */}
        <div className="lg:col-span-3">
          {currentMealPlan && currentMealPlan.length > 0 ? (
            <>
              <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-8">
                <div>
                  <h1 className="text-3xl font-black text-slate-900 tracking-tight">Menu Hebdomadaire</h1>
                  <div className="flex flex-wrap gap-2 mt-2">
                    <span className="px-3 py-1 bg-emerald-600 text-white text-[10px] font-black rounded-full uppercase tracking-widest">{authState.user?.diet}</span>
                    {authState.user?.allergies.map(a => (
                      <span key={a} className="px-3 py-1 bg-red-50 text-red-600 text-[10px] font-black rounded-full uppercase tracking-widest">Sans {a}</span>
                    ))}
                  </div>
                </div>
                <div className="flex gap-3">
                  <button 
                    onClick={() => setIsSaving(true)}
                    className="px-6 py-3 bg-white border border-slate-200 rounded-2xl text-xs font-bold text-slate-700 hover:bg-slate-50 transition-all shadow-sm"
                  >
                    💾 Sauvegarder
                  </button>
                  <button 
                    onClick={() => {
                      if(confirm("Créer un nouveau menu ? Le menu actuel ne sera pas perdu s'il est enregistré.")) {
                        setCurrentMealPlan(null);
                      }
                    }}
                    className="px-6 py-3 bg-slate-900 text-white rounded-2xl text-xs font-bold hover:bg-slate-800 transition-all shadow-xl shadow-slate-200"
