                    <button onClick={() => setIsSaving(false)} className="px-6 py-4 bg-slate-100 text-slate-500 font-bold rounded-xl text-sm border border-slate-200">Annuler</button>
                  </div>
                </div>
              )}

              {/* Day Selection */}
              <div className="flex gap-3 mb-10 overflow-x-auto pb-4 no-scrollbar">
                {currentMealPlan.map((plan, idx) => (
                  <button
                    key={idx}
                    onClick={() => setActiveDay(idx)}
                    className={`px-8 py-4 rounded-[20px] whitespace-nowrap font-black text-xs uppercase tracking-widest transition-all ${
