                    {Object.values(DietPreference).map(pref => (
                      <button
                        key={pref}
                        onClick={() => setTempDiet(pref)}
                        className={`flex flex-col items-center justify-center p-6 rounded-[24px] border-2 transition-all ${
                          tempDiet === pref 
                            ? 'border-emerald-600 bg-emerald-50 text-emerald-700 shadow-md ring-4 ring-emerald-100/50' 
                            : 'border-slate-50 bg-slate-50/50 text-slate-400 hover:border-slate-200 hover:bg-slate-50'
                        }`}
                      >
                        <span className="text-3xl mb-2">{getDietEmoji(pref)}</span>
                        <span className="text-[10px] font-black uppercase tracking-widest">{pref}</span>
                      </button>
                    ))}
                  </div>
                </div>

                <div>
                  <label className="block text-xs font-black text-slate-400 uppercase tracking-[0.2em] mb-6 text-center">Allergies (Profil : {authState.user?.email})</label>
                  <div className="flex flex-wrap justify-center gap-3">
                    {['Gluten', 'Lactose', 'Arachides', 'Oeufs', 'Soja', 'Fruits de mer'].map(allergy => (
                      <button
