const getDietEmoji = (pref: DietPreference) => {
  switch (pref) {
    case DietPreference.OMNIVORE: return '🍗';
    case DietPreference.VEGETARIAN: return '🥕';
    case DietPreference.VEGAN: return '🌿';
    case DietPreference.KETO: return '🥑';
    case DietPreference.PALEO: return '🥩';
    case DietPreference.GLUTEN_FREE: return '🌾';
    default: return '🍽️';
  }
};

const MealCard = ({ title, meal }: { title: string, meal?: Meal }) => {
  if (!meal) return null;
  return (
    <div className="bg-white rounded-[40px] overflow-hidden border border-slate-100 shadow-sm hover:shadow-2xl transition-all group flex flex-col h-full">
      <div className="h-56 relative overflow-hidden">
        <img src={meal.image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" alt={meal.name} />
        <div className="absolute top-4 left-4 px-4 py-2 bg-white/90 backdrop-blur-md rounded-2xl text-[10px] font-black text-slate-900 uppercase tracking-[0.1em] shadow-sm">{title}</div>
        <div className="absolute bottom-4 right-4 px-3 py-1.5 bg-emerald-600 text-white rounded-xl text-xs font-bold shadow-lg">
          {meal.calories} kcal
        </div>
      </div>
      <div className="p-7 flex flex-col flex-grow">
        <h3 className="text-xl font-bold text-slate-900 mb-3 leading-tight group-hover:text-emerald-600 transition-colors">{meal.name}</h3>
        <p className="text-xs text-slate-500 line-clamp-3 mb-6 leading-relaxed font-medium">{meal.description}</p>
        <div className="mt-auto pt-6 border-t border-slate-50 flex justify-between items-center">
          <div className="flex gap-1">
             {meal.ingredients.slice(0, 2).map((ing, i) => (
               <span key={i} className="text-[9px] bg-slate-100 px-2 py-1 rounded-md text-slate-400 font-bold uppercase">{ing}</span>
             ))}
          </div>
          <button className="text-[10px] font-black uppercase text-slate-900 hover:translate-x-1 transition-transform flex items-center gap-1">Détails →</button>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, createContext, useContext, useEffect } from 'react';
import { DietPreference, User, AuthState, DayPlan, SavedPlan } from './types';
import LandingPage from './pages/LandingPage';
import Dashboard from './pages/Dashboard';
import Auth from './pages/Auth';
import Preferences from './pages/Preferences';
import ShoppingList from './pages/ShoppingList';
import Subscription from './pages/Subscription';
import Navbar from './components/Navbar';

interface AppContextType {
  authState: AuthState;
  login: (email: string, pass: string) => Promise<void>;
  logout: () => void;
  updateUser: (data: Partial<User>) => void;
  currentMealPlan: DayPlan[] | null;
  setCurrentMealPlan: (plan: DayPlan[] | null) => void;
  savedPlans: SavedPlan[];
  saveCurrentPlan: (name: string) => void;
}

const AppContext = createContext<AppContextType | null>(null);

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useApp must be used within AppProvider");
  return context;
};

export const useAuth = useApp;

const App: React.FC = () => {
  const [view, setView] = useState<'landing' | 'auth' | 'dashboard' | 'preferences' | 'shopping' | 'subscription'>('landing');

  // Persistence avec LocalStorage
  const [currentMealPlan, setCurrentMealPlan] = useState<DayPlan[] | null>(() => {
    const saved = localStorage.getItem('nutriplan_current_plan');
    return saved ? JSON.parse(saved) : null;
  });

  const [savedPlans, setSavedPlans] = useState<SavedPlan[]>(() => {
    const saved = localStorage.getItem('nutriplan_saved_plans');
    return saved ? JSON.parse(saved) : [];
  });

  const [authState, setAuthState] = useState<AuthState>(() => {
    const saved = localStorage.getItem('nutriplan_auth');
    return saved ? JSON.parse(saved) : {
      user: null,
      token: null,
      isAuthenticated: false,
      isLoading: false
    };
  });

  // Sauvegarde auto quand l'état change
  useEffect(() => {
    localStorage.setItem('nutriplan_current_plan', JSON.stringify(currentMealPlan));
  }, [currentMealPlan]);

  useEffect(() => {
    localStorage.setItem('nutriplan_saved_plans', JSON.stringify(savedPlans));
  }, [savedPlans]);

  useEffect(() => {
    localStorage.setItem('nutriplan_auth', JSON.stringify(authState));
  }, [authState]);

  const login = async (email: string, pass: string) => {
    setAuthState(prev => ({ ...prev, isLoading: true }));
    await new Promise(resolve => setTimeout(resolve, 800));

    const isTestAccount = email.toLowerCase() === 'test@gmail.com' && pass === 'test1234';

    const mockUser: User = {
      id: '1',
      name: isTestAccount ? 'Test User' : 'Utilisateur Nutriplan',
      email: email,
      diet: DietPreference.OMNIVORE,
      allergies: [],
      subscriptionType: 'free'
    };

    setAuthState({
      user: mockUser,
      token: 'fake-jwt-token',
      isAuthenticated: true,
      isLoading: false
    });
    setView('dashboard');
  };

  const logout = () => {
    setAuthState({ user: null, token: null, isAuthenticated: false, isLoading: false });
    setCurrentMealPlan(null);
    localStorage.clear();
    setView('landing');
  };

  const updateUser = (data: Partial<User>) => {
    if (authState.user) {
      setAuthState(prev => ({
        ...prev,
        user: { ...prev.user!, ...data }
      }));
    }
  };

  const saveCurrentPlan = (name: string) => {
    if (!currentMealPlan || !authState.user) return;
    const newSavedPlan: SavedPlan = {
      id: Math.random().toString(36).substr(2, 9),
      name: name || `Menu du ${new Date().toLocaleDateString()}`,
      date: new Date().toISOString(),
      plan: currentMealPlan,
      diet: authState.user.diet
    };
    setSavedPlans(prev => [newSavedPlan, ...prev]);
  };

  const renderView = () => {
    switch (view) {
      case 'landing': return <LandingPage onGetStarted={() => setView('auth')} />;
      case 'auth': return <Auth />;
      case 'dashboard': return <Dashboard />;
      case 'preferences': return <Preferences />;
      case 'shopping': return <ShoppingList />;
      case 'subscription': return <Subscription />;
      default: return <LandingPage onGetStarted={() => setView('auth')} />;
    }
  };

  return (
    <AppContext.Provider value={{ 
      authState, login, logout, updateUser, 
      currentMealPlan, setCurrentMealPlan, 
      savedPlans, saveCurrentPlan 
    }}>
      <div className="min-h-screen flex flex-col bg-slate-50">
        {authState.isAuthenticated && <Navbar currentView={view} setView={setView} />}
        <main className="flex-grow">
          {renderView()}
        </main>
      </div>
    </AppContext.Provider>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { useApp } from '../App';
import { generateShoppingList } from '../services/gemini';
import { ShoppingListItem } from '../types';

const ShoppingList: React.FC = () => {
  const { currentMealPlan } = useApp();
  const [list, setList] = useState<ShoppingListItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [exportStep, setExportStep] = useState<number | null>(null);
  const [currentItem, setCurrentItem] = useState('');
  const [supermarket, setSupermarket] = useState<'delhaize' | 'colruyt' | 'ah'>('delhaize');

  useEffect(() => {
    const fetchList = async () => {
      if (!currentMealPlan || currentMealPlan.length === 0) {
        setList([]);
        return;
      }
      setLoading(true);
      try {
        const data = await generateShoppingList(currentMealPlan);
        setList(data);
      } catch (e) {
        console.error(e);
      } finally {
        setLoading(false);
      }
    };
    fetchList();
  }, [currentMealPlan]);

  const handleExportDelhaize = async () => {
    const itemsToExport = list.filter(i => !i.checked);
    if (itemsToExport.length === 0) {
      alert("Votre liste est vide !");
      return;
    }

    setExportStep(0);

    // Automatisation simulée par étapes
    for (let i = 0; i < itemsToExport.length; i++) {
      setCurrentItem(itemsToExport[i].item);

      // Phase 1: Injection dans le champ de recherche Delhaize
      await new Promise(resolve => setTimeout(resolve, 800)); 

      // Phase 2: Clic sur le bouton Panier (Simulation de l'action sur le SVG)
      await new Promise(resolve => setTimeout(resolve, 600)); 

      setExportStep(i + 1);
    }

    // Finalisation : Redirection vers Delhaize Checkout
    setTimeout(() => {
      setExportStep(null);
      window.open('https://www.delhaize.be/checkout', '_blank');
      alert(`BRAVO ! ${itemsToExport.length} articles ont été synchronisés.\n\nL'onglet Delhaize va s'ouvrir sur votre panier. Vérifiez les correspondances avant de payer.`);
    }, 1000);
  };

  const toggleItem = (index: number) => {
    setList(prev => prev.map((item, i) => i === index ? { ...item, checked: !item.checked } : item));
  };

  const categories = Array.from(new Set(list.map(item => item.category)));

  if (loading) {
    return (
      <div className="p-8 flex flex-col items-center justify-center min-h-[60vh]">
        <div className="w-16 h-16 border-4 border-emerald-600 border-t-transparent rounded-full animate-spin mb-4"></div>
        <p className="text-slate-500 font-medium font-mono uppercase tracking-widest text-xs">Extraction des ingrédients par l'IA...</p>
      </div>
    );
  }

  const itemsToExport = list.filter(i => !i.checked);

  return (
    <div className="p-6 max-w-4xl mx-auto relative">
      {/* ÉCRAN CRITIQUE D'EXPORTATION */}
      {exportStep !== null && (
        <div className="fixed inset-0 z-[100] bg-slate-900 flex items-center justify-center p-6 text-center">
          <div className="max-w-xl w-full bg-white rounded-[50px] p-12 shadow-2xl relative overflow-hidden">
            {/* Warning header */}
            <div className="absolute top-0 left-0 right-0 h-2 bg-red-600 animate-pulse"></div>

            <div className="mb-10">
              <div className="w-24 h-24 bg-red-50 text-red-600 rounded-3xl flex items-center justify-center text-5xl mx-auto mb-8 animate-bounce">
                ⚠️
              </div>
              <h2 className="text-3xl font-black text-slate-900 mb-4 uppercase tracking-tighter">Exportation Active</h2>
              <div className="px-6 py-4 bg-red-600 text-white rounded-2xl font-black text-lg animate-pulse shadow-lg shadow-red-200">
                NE RIEN TOUCHER ET NE PAS FERMER L'APP
              </div>
            </div>

            <div className="space-y-6 mb-10 text-left">
              <div className="p-6 bg-slate-50 rounded-[32px] border border-slate-100">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-4">Interaction en cours :</p>
                <div className="flex items-center gap-4 text-emerald-600">
                  <div className="w-8 h-8 rounded-full bg-emerald-100 flex items-center justify-center animate-spin">⚙️</div>
                  <p className="font-bold text-sm">Action sur <code className="bg-emerald-50 px-2 py-1 rounded">#header-search-bar-input</code></p>
                </div>
                <div className="mt-4 p-4 bg-white rounded-2xl border border-slate-100 font-mono text-xs text-slate-500">
                  {`> Searching: "${currentItem}"`}
                  <br/>
                  {`> Clicking SVG Cart Icon...`}
                  <br/>
                  {`> Verifying product name match...`}
                </div>
              </div>

              <div className="space-y-2">
                <div className="h-4 w-full bg-slate-100 rounded-full overflow-hidden">
                  <div 
                    className="h-full bg-emerald-500 transition-all duration-700 ease-in-out" 
                    style={{ width: `${(exportStep / itemsToExport.length) * 100}%` }}
                  ></div>
                </div>
                <div className="flex justify-between text-[10px] font-black text-slate-400 uppercase tracking-widest">
                  <span>Progression Panier</span>
                  <span>{exportStep} / {itemsToExport.length} ARTICLES</span>
                </div>
              </div>
            </div>

            <p className="text-[10px] text-slate-400 leading-relaxed max-w-xs mx-auto italic">
              Nutriplan prépare votre commande Delhaize.be via le checkout officiel.
            </p>
          </div>
        </div>
      )}

      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-10">
        <div>
          <h1 className="text-4xl font-black text-slate-900 tracking-tighter">Ma Liste</h1>
          <p className="text-slate-500 font-medium">Synchronisation Delhaize.be automatique.</p>
        </div>

        <div className="flex bg-slate-200/50 p-1.5 rounded-2xl border border-slate-200">
          {(['delhaize', 'colruyt', 'ah'] as const).map(s => (
            <button
              key={s}
              onClick={() => setSupermarket(s)}
              className={`px-6 py-2.5 rounded-xl text-[10px] font-black transition-all uppercase tracking-widest ${
                supermarket === s ? 'bg-white text-emerald-600 shadow-md' : 'text-slate-400 hover:text-slate-600'
              }`}
            >
              {s}
            </button>
          ))}
        </div>
      </div>

      <div className="space-y-6">
        {categories.length > 0 ? categories.map(cat => (
          <div key={cat} className="bg-white rounded-[32px] p-8 border border-slate-100 shadow-sm hover:shadow-md transition-shadow">
            <h3 className="text-[10px] font-black text-slate-300 uppercase tracking-[0.3em] mb-6 border-b border-slate-50 pb-4">{cat}</h3>
            <div className="space-y-4">
              {list.filter(i => i.category === cat).map((item, idx) => {
                const globalIndex = list.findIndex(li => li === item);
                return (
                  <div 
                    key={idx} 
                    className="flex items-center gap-6 group cursor-pointer"
                    onClick={() => toggleItem(globalIndex)}
                  >
                    <div className={`w-7 h-7 rounded-xl border-2 flex items-center justify-center transition-all ${
                      item.checked ? 'bg-emerald-500 border-emerald-500' : 'border-slate-100 group-hover:border-emerald-200'
                    }`}>
                      {item.checked && <span className="text-white font-bold text-sm">✓</span>}
                    </div>
                    <div className="flex-grow flex justify-between items-center">
                      <span className={`text-slate-700 font-bold tracking-tight ${item.checked ? 'line-through text-slate-300' : ''}`}>
                        {item.item}
                      </span>
                      <span className="text-[10px] font-black text-slate-400 bg-slate-50 px-3 py-1.5 rounded-lg border border-slate-100">{item.amount}</span>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )) : (
          <div className="p-20 text-center bg-white rounded-[50px] border-4 border-dashed border-slate-100">
            <div className="text-7xl mb-6 opacity-30">🛒</div>
            <p className="text-slate-400 font-bold uppercase tracking-widest text-sm">Générez un menu pour voir la liste</p>
          </div>
        )}
      </div>

      {list.length > 0 && (
        <div className="mt-16 flex flex-col sm:flex-row gap-4 sticky bottom-8 z-20">
          {supermarket === 'delhaize' ? (
            <button 
              onClick={handleExportDelhaize}
              className="flex-grow py-6 bg-emerald-600 text-white font-black rounded-[24px] hover:bg-emerald-700 shadow-2xl shadow-emerald-200 flex items-center justify-center gap-4 transition-all active:scale-95 group"
            >
              <span className="text-2xl group-hover:rotate-12 transition-transform">🛍️</span> EXPORTER VERS MON PANIER DELHAIZE
            </button>
          ) : (
            <button 
              disabled
              className="flex-grow py-6 bg-slate-100 text-slate-300 font-black rounded-[24px] cursor-not-allowed uppercase tracking-widest"
            >
              Support {supermarket.toUpperCase()} à venir
            </button>
          )}
          <button className="px-10 py-6 bg-white border border-slate-200 text-slate-700 font-bold rounded-[24px] hover:bg-slate-50 transition-all shadow-sm">
            PDF
          </button>
        </div>
      )}
    </div>
  );
};

export default ShoppingList;

import React, { useState } from 'react';
import { useApp } from '../App';
import { generateMealPlan } from '../services/gemini';
import { DayPlan, DietPreference, Meal } from '../types';

const Dashboard: React.FC = () => {
  const { authState, updateUser, currentMealPlan, setCurrentMealPlan, savedPlans, saveCurrentPlan } = useApp();
  const [loading, setLoading] = useState(false);
  const [activeDay, setActiveDay] = useState(0);
  const [isSaving, setIsSaving] = useState(false);
  const [saveName, setSaveName] = useState('');

  // Local state for setup
  const [tempDiet, setTempDiet] = useState<DietPreference>(authState.user?.diet || DietPreference.OMNIVORE);
  const [tempAllergies, setTempAllergies] = useState<string[]>(authState.user?.allergies || []);

  const toggleAllergy = (allergy: string) => {
    setTempAllergies(prev => 
      prev.includes(allergy) ? prev.filter(a => a !== allergy) : [...prev, allergy]
    );
  };

  const handleGenerate = async () => {
    if (!authState.user) return;
    updateUser({ diet: tempDiet, allergies: tempAllergies });
    setLoading(true);
    try {
      const data = await generateMealPlan(tempDiet, tempAllergies);
      setCurrentMealPlan(data || []);
      setActiveDay(0);
    } catch (err) {
      console.error("Erreur génération:", err);
    } finally {
      setLoading(false);
    }
  };

  const handleSavePlan = () => {
    if (!saveName) {
      alert("Donnez un nom à votre dossier !");
      return;
    }
    saveCurrentPlan(saveName);
    setIsSaving(false);
    setSaveName('');
    alert("Menu enregistré avec succès !");
  };

  if (loading) {
    return (
      <div className="p-8 flex flex-col items-center justify-center min-h-[60vh]">
        <div className="w-20 h-20 border-4 border-emerald-600 border-t-transparent rounded-full animate-spin mb-6"></div>
        <p className="text-xl font-bold text-slate-900 tracking-tighter">IA Nutriplan concocte votre menu...</p>
        <p className="text-slate-400 mt-2 italic text-sm">Calcul des calories et équilibre nutritionnel en cours.</p>
      </div>
    );
  }

  return (
    <div className="p-6 max-w-7xl mx-auto">
      <div className="grid lg:grid-cols-4 gap-10">

        {/* SIDEBAR : MES DOSSIERS */}
        <aside className="lg:col-span-1 space-y-8">
          <div className="bg-white rounded-[40px] p-8 shadow-sm border border-slate-100">
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em] mb-8">📁 MES DOSSIERS</h3>
            <div className="space-y-4">
              {savedPlans.length === 0 ? (
                <div className="p-6 bg-slate-50 rounded-3xl border border-dashed border-slate-200">
                  <p className="text-[10px] text-slate-400 font-bold italic text-center leading-relaxed">Enregistrez un menu pour le retrouver ici.</p>
