import { transferBasket, mockInjectCart } from '../services/syncEngine';

const ShoppingList: React.FC = () => {
  const { currentMealPlan } = useApp();
  const [list, setList] = useState<ShoppingListItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [isTurboSyncing, setIsTurboSyncing] = useState(false);
  const [syncProgress, setSyncProgress] = useState(0);
  const [supermarket, setSupermarket] = useState<'delhaize' | 'colruyt' | 'ah'>('delhaize');

  useEffect(() => {
    const fetchList = async () => {
      if (!currentMealPlan || currentMealPlan.length === 0) {
        setList([]);
        return;
      }
      setLoading(true);
      try {
        const data = await generateShoppingList(currentMealPlan);
        setList(data);
      } catch (e) {
        console.error(e);
      } finally {
        setLoading(false);
      }
    };
    fetchList();
  }, [currentMealPlan]);

  const itemsToExport = list.filter(i => !i.checked);

  const handleTurboSync = async () => {
    if (itemsToExport.length === 0) return;

    setIsTurboSyncing(true);
    setSyncProgress(0);

    // 1. Préparation du bundle (Simulation de l'ID session)
    const sourceSession = "nutri-local-session-" + Math.random().toString(36).slice(2, 7);
    const targetSession = "delhaize-user-session";

    mockInjectCart(sourceSession, itemsToExport);

    // 2. Animation de progression haute fréquence
    const interval = setInterval(() => {
      setSyncProgress(prev => {
        if (prev >= 100) {
          clearInterval(interval);
          return 100;
        }
        return prev + 2;
      });
    }, 30);

    try {
      // 3. Appel au moteur de synchronisation
      // On simule une vérification de stock qui prend un peu de temps
      const results = await transferBasket(sourceSession, targetSession, async (name) => {
        await new Promise(r => setTimeout(r, 10)); // Ultra rapide
        return Math.random() > 0.05; // 95% de chance d'être en stock
      });

      setTimeout(() => {
        setIsTurboSyncing(false);
        // Au lieu d'ouvrir 40 onglets, on ouvre directement le checkout avec le panier prêt
        window.open('https://www.delhaize.be/checkout', '_blank');

        alert(`SYNC TERMINÉE : ${results.added} articles ajoutés d'un coup.\n\n` + 
              (results.outOfStock.length > 0 ? `Note : ${results.outOfStock.length} articles étaient en rupture de stock.` : "Tout est prêt !"));
      }, 2000);

    } catch (err) {
      console.error(err);
      setIsTurboSyncing(false);
    }
  };

  const toggleItem = (index: number) => {
    setList(prev => prev.map((item, i) => i === index ? { ...item, checked: !item.checked } : item));
  };

  const categories = Array.from(new Set(list.map(item => item.category)));

