      </div>
    );
  }

  return (
    <div className="p-6 max-w-4xl mx-auto relative">
      {/* MODAL TURBO SYNC - DOUX ET MODERNE */}
      {isTurboSyncing && (
        <div className="fixed inset-0 z-[100] bg-slate-900/40 backdrop-blur-md flex items-center justify-center p-6">
          <div className="max-w-md w-full bg-white rounded-[40px] p-12 text-center shadow-2xl relative overflow-hidden">
            <div className="absolute top-0 left-0 right-0 h-1.5 bg-slate-50">
               <div 
                className="h-full bg-emerald-500 transition-all duration-300 ease-out" 
                style={{ width: `${syncProgress}%` }}
               ></div>
            </div>

            <div className="w-24 h-24 bg-emerald-50 text-emerald-600 rounded-full flex items-center justify-center text-4xl mx-auto mb-8 animate-pulse">
              🚀
            </div>

            <h2 className="text-2xl font-black text-slate-900 mb-2">Turbo Transfert</h2>
            <p className="text-slate-500 text-sm mb-8">
              Synchronisation groupée de {itemsToExport.length} articles vers votre panier Delhaize.be
            </p>

            <div className="bg-slate-50 rounded-3xl p-6 mb-8 text-left space-y-3">
              <div className="flex justify-between items-center text-[10px] font-black uppercase tracking-widest text-slate-400">
                <span>Statut du moteur</span>
                <span className="text-emerald-500">Actif</span>
              </div>
              <div className="h-1 w-full bg-slate-200 rounded-full overflow-hidden">
                <div className="h-full bg-emerald-500 animate-shimmer" style={{ width: '100%', backgroundSize: '200% 100%' }}></div>
              </div>
              <p className="text-[9px] font-mono text-slate-400 italic">
                {`> Bundling session: ${itemsToExport.length} items...`}
                <br/>
                {`> Bypassing single-tab restriction...`}
                <br/>
                {`> Target: delhaize.be/cart/bulk_add`}
              </p>
            </div>

            <div className="text-emerald-600 font-black text-3xl tabular-nums">
              {syncProgress}%
            </div>
          </div>
