import React, { useState, useEffect } from 'react';
import { useApp } from '../App';
import { generateShoppingList } from '../services/gemini';
import { ShoppingListItem } from '../types';

const ShoppingList: React.FC = () => {
  const { currentMealPlan } = useApp();
  const [list, setList] = useState<ShoppingListItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [supermarket, setSupermarket] = useState<'delhaize' | 'colruyt' | 'ah'>('delhaize');

  useEffect(() => {
    const fetchList = async () => {
      if (!currentMealPlan || currentMealPlan.length === 0) {
        setList([]);
        return;
      }
      setLoading(true);
      try {
        const data = await generateShoppingList(currentMealPlan);
        setList(data);
      } catch (e) {
        console.error(e);
      } finally {
        setLoading(false);
      }
    };
    fetchList();
  }, [currentMealPlan]);

  const toggleItem = (index: number) => {
    setList(prev => prev.map((item, i) => i === index ? { ...item, checked: !item.checked } : item));
  };

  const addToCart = (item: string) => {
    // Construction de l'URL de recherche pour le supermarché choisi
    let baseUrl = '';
    if (supermarket === 'delhaize') baseUrl = `https://www.delhaize.be/fr-be/search?text=${encodeURIComponent(item)}`;
    else if (supermarket === 'colruyt') baseUrl = `https://www.collectandgo.be/colruyt/fr/recherche?searchTerm=${encodeURIComponent(item)}`;
    else if (supermarket === 'ah') baseUrl = `https://www.ah.be/zoeken?query=${encodeURIComponent(item)}`;

    window.open(baseUrl, '_blank');
  };

  const categories = Array.from(new Set(list.map(item => item.category)));

  if (loading) {
    return (
      <div className="p-8 flex flex-col items-center justify-center min-h-[60vh]">
        <div className="w-12 h-12 border-4 border-emerald-500/20 border-t-emerald-500 rounded-full animate-spin mb-4"></div>
        <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest">IA en cuisine...</p>
      </div>
    );
  }

  return (
    <div className="p-6 max-w-4xl mx-auto">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-10">
        <div>
          <h1 className="text-3xl font-black text-slate-900 tracking-tight">Courses</h1>
          <p className="text-slate-500 text-sm font-medium">Ajoutez vos articles au panier un par un.</p>
        </div>

        <div className="flex bg-slate-100 p-1 rounded-2xl border border-slate-200/50 self-start">
          {(['delhaize', 'colruyt', 'ah'] as const).map(s => (
            <button
              key={s}
              onClick={() => setSupermarket(s)}
              className={`px-5 py-2 rounded-xl text-[9px] font-black transition-all uppercase tracking-widest ${
                supermarket === s ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'
              }`}
            >
              {s}
            </button>
          ))}
        </div>
      </div>

      {list.length === 0 ? (
        <div className="p-20 text-center bg-white rounded-[40px] border border-slate-100 shadow-sm">
          <div className="text-6xl mb-6 opacity-20">🥦</div>
          <p className="text-slate-400 font-black uppercase tracking-widest text-[10px]">Générez un menu d'abord</p>
        </div>
      ) : (
        <div className="space-y-8">
          {categories.map(cat => (
            <div key={cat} className="bg-white rounded-[32px] p-8 border border-slate-100 shadow-sm">
              <h3 className="text-[10px] font-black text-slate-300 uppercase tracking-[0.3em] mb-6 border-b border-slate-50 pb-4">{cat}</h3>
              <div className="space-y-4">
                {list.filter(i => i.category === cat).map((item, idx) => {
                  const globalIndex = list.findIndex(li => li === item);
                  return (
                    <div 
                      key={idx} 
                      className="flex items-center gap-4 group"
                    >
                      <div 
                        className={`w-6 h-6 rounded-lg border-2 flex items-center justify-center transition-all cursor-pointer ${
                          item.checked ? 'bg-emerald-500 border-emerald-500' : 'border-slate-100'
                        }`}
                        onClick={() => toggleItem(globalIndex)}
                      >
                        {item.checked && <span className="text-white font-bold text-[10px]">✓</span>}
                      </div>

                      <div className="flex-grow flex items-center justify-between min-w-0">
                        <div className="flex flex-col min-w-0">
                          <span className={`text-sm font-bold truncate transition-all ${item.checked ? 'line-through text-slate-300' : 'text-slate-700'}`}>
                            {item.item}
                          </span>
                          <span className="text-[9px] font-black text-slate-400 uppercase tracking-tighter">{item.amount}</span>
                        </div>

                        {/* BOUTON À DROITE DEMANDÉ */}
                        <button 
                          onClick={() => addToCart(item.item)}
                          className="ml-4 w-10 h-10 bg-emerald-50 text-emerald-600 rounded-xl flex items-center justify-center hover:bg-emerald-100 transition-all active:scale-90 border border-emerald-100/50 shadow-sm flex-shrink-0"
                          title="Chercher sur le site"
                        >
                          <span className="text-lg">🛒</span>
                        </button>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          ))}
        </div>
      )}

      {list.length > 0 && (
        <div className="mt-12 flex justify-center">
          <button 
            onClick={() => window.print()}
            className="px-10 py-4 bg-slate-900 text-white font-bold rounded-2xl text-[10px] uppercase tracking-widest hover:bg-slate-800 transition-all shadow-xl"
          >
            Imprimer la liste
          </button>
        </div>
      )}
    </div>
  );
};

export default ShoppingList;

import React, { useState } from 'react';
