        <h3 className="text-lg font-black text-slate-900 mb-2 leading-tight group-hover:text-emerald-700 transition-colors">{meal.name}</h3>
        <p className="text-[11px] text-slate-400 line-clamp-2 font-medium mb-4 italic">Cliquez pour voir la recette complète</p>
        <div className="mt-auto flex justify-between items-center text-[10px] font-black text-emerald-600">
          <span className="bg-emerald-50 px-2 py-1 rounded-md">{meal.calories} KCAL</span>
          <span className="text-slate-300 uppercase tracking-widest group-hover:text-emerald-500 transition-colors">Détails →</span>
        </div>
      </div>
    </div>
  );
};

