import React, { useState, useEffect, useMemo } from 'react';
import { useApp } from '../App';
import { generateShoppingList } from '../services/gemini';
import { ShoppingListItem, SavedPlan } from '../types';

const ShoppingList: React.FC = () => {
  const { currentMealPlan, savedPlans } = useApp();
  const [list, setList] = useState<ShoppingListItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [supermarket, setSupermarket] = useState<'delhaize' | 'colruyt' | 'ah'>('delhaize');
  const [selectedWeekId, setSelectedWeekId] = useState<string>('current');
  const [portalMode, setPortalMode] = useState(false);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [toast, setToast] = useState<string | null>(null);

  // Déterminer quel plan de repas utiliser selon la semaine choisie
  const activePlan = useMemo(() => {
    if (selectedWeekId === 'current') return currentMealPlan;
    return savedPlans.find(p => p.id === selectedWeekId)?.plan || null;
  }, [selectedWeekId, currentMealPlan, savedPlans]);

  useEffect(() => {
    const fetchList = async () => {
      if (!activePlan || activePlan.length === 0) {
        setList([]);
        return;
      }
      setLoading(true);
      try {
        const data = await generateShoppingList(activePlan);
        setList(data);
      } catch (e) {
        console.error(e);
      } finally {
        setLoading(false);
      }
    };
    fetchList();
  }, [activePlan]);

  const toggleItem = (index: number) => {
    setList(prev => prev.map((item, i) => i === index ? { ...item, checked: !item.checked } : item));
  };

  const openSearch = (item: string) => {
    let baseUrl = '';
    if (supermarket === 'delhaize') baseUrl = `https://www.delhaize.be/fr-be/search?text=${encodeURIComponent(item)}`;
    else if (supermarket === 'colruyt') baseUrl = `https://www.collectandgo.be/colruyt/fr/recherche?searchTerm=${encodeURIComponent(item)}`;
    else if (supermarket === 'ah') baseUrl = `https://www.ah.be/zoeken?query=${encodeURIComponent(item)}`;

    window.open(baseUrl, '_blank');
    setToast(`Recherche de "${item}" lancée...`);
    setTimeout(() => setToast(null), 2000);
  };

  const nextItem = () => {
    if (currentIndex < list.length - 1) {
      const nextIdx = currentIndex + 1;
      setCurrentIndex(nextIdx);
      openSearch(list[nextIdx].item);
    } else {
      setPortalMode(false);
      setToast("Panier terminé !");
    }
  };

  const categories = Array.from(new Set(list.map(item => item.category)));

  if (loading) {
    return (
      <div className="p-8 flex flex-col items-center justify-center min-h-[60vh]">
        <div className="w-12 h-12 border-4 border-emerald-500/20 border-t-emerald-500 rounded-full animate-spin mb-4"></div>
        <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest italic">Analyse de la semaine sélectionnée...</p>
      </div>
    );
  }

  if (portalMode && list.length > 0) {
    const currentItem = list[currentIndex];
    return (
      <div className="fixed inset-0 z-[200] bg-slate-50 flex flex-col md:flex-row animate-in fade-in duration-300">
        {/* Colonne Gauche : Liste de contrôle */}
        <div className="w-full md:w-1/3 bg-white border-r border-slate-200 flex flex-col">
          <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
            <div>
              <h2 className="text-xl font-black text-slate-900">Assistant Panier</h2>
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Article {currentIndex + 1} sur {list.length}</p>
            </div>
            <button onClick={() => setPortalMode(false)} className="text-slate-400 hover:text-red-500 transition-colors">Quitter</button>
          </div>
          <div className="flex-grow overflow-y-auto p-4 space-y-2">
            {list.map((item, idx) => (
              <div 
                key={idx}
                className={`p-4 rounded-2xl flex items-center justify-between transition-all ${
                  currentIndex === idx ? 'bg-emerald-50 border-emerald-200 border-2' : 'bg-white border border-slate-100'
                }`}
              >
                <div className="flex flex-col min-w-0">
                  <span className={`text-xs font-bold truncate ${idx < currentIndex ? 'text-slate-300 line-through' : 'text-slate-700'}`}>{item.item}</span>
                  <span className="text-[9px] text-slate-400 font-black">{item.amount}</span>
                </div>
                {idx < currentIndex && <span className="text-emerald-500">✓</span>}
              </div>
            ))}
          </div>
        </div>

        {/* Colonne Droite : Action */}
        <div className="flex-grow flex items-center justify-center p-8 bg-slate-900 text-white relative">
          <div className="absolute top-10 text-center">
            <span className="text-emerald-400 text-[10px] font-black uppercase tracking-[0.4em] mb-4 block">Étape en cours</span>
            <h3 className="text-4xl font-black tracking-tight mb-2">{currentItem.item}</h3>
            <p className="text-slate-400 font-medium">Quantité requise : {currentItem.amount}</p>
          </div>

          <div className="text-center space-y-8 max-w-md">
             <div className="bg-white/5 border border-white/10 p-8 rounded-[40px] backdrop-blur-xl">
                <p className="text-sm text-slate-300 leading-relaxed mb-8">
                  Nutriplan va ouvrir l'onglet Delhaize. <br/>
                  <span className="font-bold text-white">Ajoutez le produit</span> puis revenez ici pour l'article suivant.
                </p>
                <div className="flex flex-col gap-3">
                  <button 
                    onClick={() => openSearch(currentItem.item)}
                    className="w-full py-5 bg-white text-slate-900 font-black rounded-2xl hover:bg-emerald-400 transition-all shadow-xl"
                  >
                    🔍 CHERCHER SUR DELHAIZE
                  </button>
                  <button 
                    onClick={nextItem}
                    className="w-full py-5 bg-emerald-600 text-white font-black rounded-2xl hover:bg-emerald-500 transition-all"
                  >
                    SUIVANT →
                  </button>
                </div>
             </div>
             <button onClick={() => toggleItem(currentIndex)} className="text-[10px] font-black text-slate-500 hover:text-white uppercase tracking-widest transition-colors">
               Marquer comme "Introuvable"
             </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="p-6 max-w-5xl mx-auto relative">
      {/* TOAST NOTIFICATION */}
      {toast && (
        <div className="fixed bottom-10 left-1/2 -translate-x-1/2 z-[100] bg-emerald-600 text-white px-8 py-4 rounded-[20px] shadow-2xl animate-in slide-in-from-bottom-5 fade-in duration-300 flex items-center gap-3">
          <span className="text-[10px] font-black uppercase tracking-widest">{toast}</span>
        </div>
      )}

      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-10">
        <div>
          <h1 className="text-4xl font-black text-slate-900 tracking-tight">Portail Courses</h1>
          <p className="text-slate-500 text-sm font-medium">Gérez vos listes par semaine et remplissez votre panier.</p>
        </div>

        <div className="flex flex-col sm:flex-row gap-4">
          {/* SÉLECTEUR DE SEMAINE */}
          <select 
            value={selectedWeekId}
            onChange={(e) => setSelectedWeekId(e.target.value)}
            className="px-6 py-3 bg-white border border-slate-200 rounded-xl text-[10px] font-black text-slate-600 uppercase tracking-widest outline-none focus:ring-2 focus:ring-emerald-500"
          >
            <option value="current">Menu Actuel</option>
            {savedPlans.map(plan => (
              <option key={plan.id} value={plan.id}>{plan.name} ({new Date(plan.date).toLocaleDateString()})</option>
            ))}
          </select>

          <div className="flex bg-slate-200/50 p-1 rounded-xl border border-slate-200">
            {(['delhaize', 'colruyt', 'ah'] as const).map(s => (
              <button
                key={s}
                onClick={() => setSupermarket(s)}
                className={`px-4 py-2 rounded-lg text-[9px] font-black transition-all uppercase tracking-widest ${
                  supermarket === s ? 'bg-white text-emerald-600 shadow-sm' : 'text-slate-500 hover:text-slate-700'
                }`}
              >
                {s}
              </button>
            ))}
          </div>
        </div>
      </div>

      {list.length === 0 ? (
        <div className="p-24 text-center bg-white rounded-[50px] border-4 border-dashed border-slate-100">
          <div className="text-7xl mb-6 opacity-20">🛒</div>
          <p className="text-slate-400 font-black uppercase tracking-widest text-[11px] max-w-xs mx-auto">Sélectionnez une semaine ou générez un menu pour voir la liste.</p>
        </div>
      ) : (
        <div className="space-y-8">
          <div className="bg-emerald-900 text-white p-8 rounded-[40px] shadow-2xl shadow-emerald-100 flex flex-col md:flex-row items-center justify-between gap-6 overflow-hidden relative">
            <div className="absolute top-0 right-0 w-64 h-64 bg-emerald-500/20 rounded-full blur-3xl"></div>
            <div className="relative z-10">
              <h3 className="text-2xl font-black mb-2">Synchronisation Semi-Auto</h3>
              <p className="text-emerald-200/80 text-xs font-medium max-w-md">Nous allons vous aider à remplir votre panier Delhaize article par article en copiant automatiquement les noms.</p>
            </div>
            <button 
              onClick={() => { setPortalMode(true); setCurrentIndex(0); openSearch(list[0].item); }}
              className="relative z-10 px-10 py-5 bg-white text-emerald-900 font-black rounded-2xl text-[10px] uppercase tracking-[0.2em] hover:bg-emerald-50 transition-all shadow-xl active:scale-95"
