                <div className="grid grid-cols-1 md:grid-cols-2 gap-x-12 gap-y-6">
                  {list.filter(i => i.category === cat).map((item, idx) => {
                    const globalIndex = list.findIndex(li => li === item);
                    return (
                      <div 
