import React, { useState, useEffect, useMemo, useRef } from 'react';
import { useApp } from '../App';
import { generateShoppingList } from '../services/gemini';
import { ShoppingListItem } from '../types';

const ShoppingList: React.FC = () => {
  const { currentMealPlan, savedPlans } = useApp();
  const [list, setList] = useState<ShoppingListItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [selectedWeekId, setSelectedWeekId] = useState<string>('current');
  const [isLive, setIsLive] = useState(false);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [logs, setLogs] = useState<string[]>(["Initialisation du Studio Nutriplan..."]);
  const portalWindow = useRef<Window | null>(null);

  // Sélection de la semaine
  const activePlan = useMemo(() => {
    if (selectedWeekId === 'current') return currentMealPlan;
    return savedPlans.find(p => p.id === selectedWeekId)?.plan || null;
  }, [selectedWeekId, currentMealPlan, savedPlans]);

  useEffect(() => {
    const fetchList = async () => {
      if (!activePlan || activePlan.length === 0) {
        setList([]);
        return;
      }
      setLoading(true);
      try {
        const data = await generateShoppingList(activePlan);
        setList(data);
        addLog("Liste d'ingrédients récupérée avec succès.");
      } catch (e) {
        addLog("Erreur de récupération de la liste.");
      } finally {
        setLoading(false);
      }
    };
    fetchList();
  }, [activePlan]);

  const addLog = (msg: string) => {
    setLogs(prev => [`[${new Date().toLocaleTimeString()}] ${msg}`, ...prev].slice(0, 5));
  };

  const syncProduct = (index: number) => {
    const item = list[index];
    if (!item) return;

    addLog(`Synchronisation : ${item.item}...`);
    const searchUrl = `https://www.delhaize.be/fr-be/search?text=${encodeURIComponent(item.item)}`;

    if (portalWindow.current && !portalWindow.current.closed) {
      portalWindow.current.location.href = searchUrl;
    } else {
      portalWindow.current = window.open(searchUrl, 'delhaize_stream', 'width=1200,height=800');
    }
    setCurrentIndex(index);
  };

  const startLiveSession = () => {
    setIsLive(true);
    syncProduct(0);
    addLog("Session Live démarrée. Fenêtre Delhaize synchronisée.");
  };

  const nextProduct = () => {
    if (currentIndex < list.length - 1) {
      syncProduct(currentIndex + 1);
    } else {
      setIsLive(false);
      addLog("Panier terminé !");
      alert("Tous les articles ont été traités.");
    }
  };

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] bg-slate-900 text-emerald-500">
        <div className="w-12 h-12 border-4 border-emerald-500/20 border-t-emerald-500 rounded-full animate-spin mb-4"></div>
        <p className="font-mono text-xs uppercase tracking-widest animate-pulse">Chargement du flux ingrédients...</p>
      </div>
    );
  }

  return (
    <div className={`min-h-screen ${isLive ? 'bg-slate-950 p-0' : 'p-6 bg-slate-50'}`}>

      {!isLive ? (
        <div className="max-w-6xl mx-auto">
          {/* HEADER CLASSIQUE */}
          <div className="flex flex-col md:flex-row justify-between items-end mb-12 gap-6">
            <div>
              <div className="flex items-center gap-2 mb-2">
                <span className="w-2 h-2 bg-red-500 rounded-full animate-ping"></span>
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Shopping Portal</span>
              </div>
              <h1 className="text-5xl font-black text-slate-900 tracking-tighter">Votre Panier Auto.</h1>
            </div>

            <div className="flex flex-col items-end gap-3">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Sélectionner la semaine</label>
              <select 
                value={selectedWeekId}
                onChange={(e) => setSelectedWeekId(e.target.value)}
                className="px-6 py-4 bg-white border-2 border-slate-100 rounded-2xl text-xs font-bold outline-none focus:border-emerald-500 transition-all min-w-[250px] shadow-sm"
              >
                <option value="current">Semaine en cours</option>
                {savedPlans.map(plan => (
                  <option key={plan.id} value={plan.id}>{plan.name} ({new Date(plan.date).toLocaleDateString()})</option>
                ))}
              </select>
            </div>
          </div>

          {list.length > 0 ? (
            <div className="grid lg:grid-cols-3 gap-8">
              <div className="lg:col-span-2 space-y-6">
                {list.map((item, idx) => (
                  <div key={idx} className="bg-white p-6 rounded-[32px] border border-slate-100 flex items-center justify-between group hover:shadow-xl transition-all">
                    <div className="flex items-center gap-6">
                      <div className="w-12 h-12 bg-slate-50 rounded-2xl flex items-center justify-center text-xl grayscale group-hover:grayscale-0 transition-all">🛒</div>
                      <div>
                        <p className="text-base font-black text-slate-800">{item.item}</p>
                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{item.amount} • {item.category}</p>
                      </div>
                    </div>
                    <button 
                      onClick={() => syncProduct(idx)}
                      className="px-6 py-3 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase hover:bg-emerald-600 transition-all"
                    >
                      Sync
                    </button>
                  </div>
                ))}
              </div>

              <aside>
                <div className="sticky top-24 bg-emerald-600 rounded-[40px] p-10 text-white shadow-2xl shadow-emerald-200 overflow-hidden relative">
                  <div className="absolute -top-10 -right-10 w-40 h-40 bg-white/10 rounded-full blur-2xl"></div>
                  <h3 className="text-3xl font-black mb-4 leading-tight">Mode Live Streaming</h3>
                  <p className="text-emerald-100 text-sm mb-10 leading-relaxed">Préparez votre panier Delhaize comme un pro. Le bot va piloter l'ajout de vos {list.length} articles.</p>
                  <button 
                    onClick={startLiveSession}
                    className="w-full py-6 bg-white text-emerald-600 font-black rounded-3xl text-xs uppercase tracking-[0.2em] shadow-xl hover:scale-105 transition-all"
                  >
                    DÉMARRER LE LIVE →
                  </button>
                </div>
              </aside>
            </div>
          ) : (
            <div className="text-center p-20 bg-white rounded-[50px] border-4 border-dashed border-slate-100">
              <p className="text-slate-400 font-black uppercase tracking-widest text-xs">Générez un menu pour activer le portail.</p>
            </div>
          )}
        </div>
      ) : (
        /* INTERFACE LIVE STREAMING (TWITCH STYLE) */
        <div className="h-screen flex flex-col overflow-hidden">
          {/* Header Studio */}
          <div className="h-20 bg-slate-900 border-b border-white/10 flex items-center justify-between px-8">
            <div className="flex items-center gap-4">
              <div className="w-10 h-10 bg-emerald-500 rounded-xl flex items-center justify-center font-black text-white">N</div>
              <div>
                <h2 className="text-white font-black text-sm uppercase tracking-widest">Nutriplan Live Studio</h2>
                <div className="flex items-center gap-2">
                  <span className="w-2 h-2 bg-red-500 rounded-full animate-pulse"></span>
                  <span className="text-[9px] text-slate-400 font-bold uppercase tracking-widest">Stream en direct vers Delhaize</span>
                </div>
              </div>
            </div>

            <div className="flex-grow flex justify-center">
              <div className="bg-white/5 border border-white/10 px-6 py-2 rounded-full flex items-center gap-8">
                <div className="text-center">
                  <p className="text-[8px] text-slate-500 font-black uppercase">Progression</p>
                  <p className="text-xs text-white font-bold">{currentIndex + 1} / {list.length}</p>
                </div>
                <div className="w-32 h-1.5 bg-white/10 rounded-full overflow-hidden">
                  <div className="h-full bg-emerald-500 transition-all duration-500" style={{ width: `${((currentIndex + 1) / list.length) * 100}%` }}></div>
                </div>
              </div>
            </div>

            <button 
              onClick={() => setIsLive(false)}
              className="px-6 py-3 bg-red-500/10 text-red-500 border border-red-500/20 rounded-xl text-[10px] font-black uppercase hover:bg-red-500 hover:text-white transition-all"
            >
              Arrêter le Stream
            </button>
          </div>

          <div className="flex-grow flex overflow-hidden">
            {/* Colonne Gauche : Liste de Commande (Flux Twitch) */}
            <div className="w-96 bg-slate-900 border-r border-white/5 flex flex-col">
              <div className="p-6 border-b border-white/5">
                <h3 className="text-white text-[10px] font-black uppercase tracking-[0.3em] mb-4">Ingrédients du flux</h3>
              </div>
              <div className="flex-grow overflow-y-auto p-4 space-y-3 custom-scrollbar">
                {list.map((item, idx) => (
                  <div 
                    key={idx}
                    className={`p-4 rounded-2xl transition-all ${
                      idx === currentIndex 
                        ? 'bg-emerald-500/20 border border-emerald-500/50 shadow-lg shadow-emerald-500/5 scale-[1.02]' 
                        : idx < currentIndex ? 'opacity-30' : 'bg-white/5 border border-transparent'
                    }`}
                  >
                    <div className="flex justify-between items-start">
                      <span className="text-white font-bold text-xs">{item.item}</span>
                      <span className="text-[9px] text-emerald-400 font-black uppercase tracking-tighter">{item.amount}</span>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Zone Centrale : L'Écran Delhaize (Visualisation) */}
            <div className="flex-grow bg-black flex flex-col">
              <div className="flex-grow flex items-center justify-center p-12 relative">
                {/* Background effect */}
                <div className="absolute inset-0 bg-gradient-to-br from-emerald-500/5 to-blue-500/5 opacity-50"></div>

                <div className="relative z-10 w-full max-w-2xl bg-slate-900/80 backdrop-blur-3xl border border-white/10 rounded-[50px] p-16 text-center shadow-2xl">
                   <div className="w-24 h-24 bg-emerald-500/20 rounded-full flex items-center justify-center mx-auto mb-8 animate-bounce">
                     <span className="text-5xl">🛒</span>
                   </div>
                   <h3 className="text-4xl font-black text-white mb-4 tracking-tighter">Étape : {list[currentIndex]?.item}</h3>
                   <p className="text-slate-400 font-medium text-lg mb-12">Le bot a ouvert Delhaize. <br/>Vérifiez la fenêtre séparée, ajoutez l'article et cliquez ici.</p>

                   <div className="flex flex-col gap-4">
                     <button 
                       onClick={nextProduct}
                       className="w-full py-6 bg-emerald-500 text-white font-black rounded-3xl text-xl shadow-2xl hover:bg-emerald-400 hover:scale-[1.02] active:scale-95 transition-all"
                     >
                       ARTICLE SUIVANT →
                     </button>
                     <button 
                       onClick={() => syncProduct(currentIndex)}
                       className="text-[10px] font-black text-slate-500 uppercase tracking-widest hover:text-white transition-colors"
