import React, { useState, useEffect, useMemo } from 'react';
import { useApp } from '../App';
import { generateShoppingList } from '../services/gemini';
import { ShoppingListItem } from '../types';

const ShoppingList: React.FC = () => {
  const { currentMealPlan, savedPlans } = useApp();
  const [list, setList] = useState<ShoppingListItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [selectedWeekId, setSelectedWeekId] = useState<string>('current');
  const [currentIndex, setCurrentIndex] = useState(0);
  const [viewMode, setViewMode] = useState<'standard' | 'bot'>('standard');
  const [logs, setLogs] = useState<string[]>([]);

  // 1. Filtrage et sélection de la semaine
  const activePlan = useMemo(() => {
    if (selectedWeekId === 'current') return currentMealPlan;
    const found = savedPlans.find(p => p.id === selectedWeekId);
    return found ? found.plan : null;
  }, [selectedWeekId, currentMealPlan, savedPlans]);

  // 2. Génération de la liste d'ingrédients via Gemini
  useEffect(() => {
    const fetchList = async () => {
      if (!activePlan || activePlan.length === 0) {
        setList([]);
        return;
      }
      setLoading(true);
      try {
        const data = await generateShoppingList(activePlan);
        setList(data);
        addLog("Liste d'ingrédients synchronisée.");
      } catch (e) {
        addLog("Erreur de synchronisation.");
      } finally {
        setLoading(false);
      }
    };
    fetchList();
  }, [activePlan]);

  const addLog = (msg: string) => {
    setLogs(prev => [`[${new Date().toLocaleTimeString()}] ${msg}`, ...prev].slice(0, 5));
  };

  const handleNext = () => {
    if (currentIndex < list.length - 1) {
      const nextIdx = currentIndex + 1;
      setCurrentIndex(nextIdx);
      addLog(`Recherche : ${list[nextIdx].item}`);
      // On ouvre l'URL dans un onglet dédié que le bot va "piloter"
      const url = `https://www.delhaize.be/fr-be/search?text=${encodeURIComponent(list[nextIdx].item)}`;
      window.open(url, 'delhaize_bot');
    } else {
      setViewMode('standard');
      alert("Félicitations ! Votre panier est prêt.");
    }
  };

  const startBot = () => {
    if (list.length === 0) return;
    setViewMode('bot');
    setCurrentIndex(0);
    addLog(`Bot lancé sur : ${list[0].item}`);
    window.open(`https://www.delhaize.be/fr-be/search?text=${encodeURIComponent(list[0].item)}`, 'delhaize_bot');
  };

  const exportCSV = () => {
    const headers = "Article,Quantite,Categorie\n";
    const rows = list.map(i => `${i.item},${i.amount},${i.category}`).join("\n");
    const blob = new Blob([headers + rows], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.setAttribute('hidden', '');
    a.setAttribute('href', url);
    a.setAttribute('download', `courses_nutriplan_${selectedWeekId}.csv`);
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  };

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] text-emerald-600">
        <div className="w-12 h-12 border-4 border-emerald-100 border-t-emerald-600 rounded-full animate-spin mb-4"></div>
        <p className="font-black text-[10px] uppercase tracking-widest">Le Bot prépare les données...</p>
      </div>
    );
  }

  return (
    <div className={`min-h-screen ${viewMode === 'bot' ? 'bg-slate-950 text-white' : 'bg-slate-50 text-slate-900'} transition-colors duration-500`}>
      <div className="max-w-7xl mx-auto p-6 lg:p-12">

        {/* HEADER PILOTAGE */}
        <div className="flex flex-col md:flex-row justify-between items-end gap-6 mb-12">
          <div>
            <div className="flex items-center gap-2 mb-2">
              <span className={`w-2 h-2 rounded-full ${viewMode === 'bot' ? 'bg-red-500 animate-pulse' : 'bg-emerald-500'}`}></span>
              <p className="text-[10px] font-black uppercase tracking-[0.3em] opacity-60">
                {viewMode === 'bot' ? 'Bot en cours de pilotage' : 'Gestionnaire de courses'}
              </p>
            </div>
            <h1 className="text-5xl font-black tracking-tighter">Mon Panier.</h1>
          </div>

          <div className="flex flex-col items-end gap-3">
             <label className="text-[10px] font-black uppercase tracking-widest opacity-40">Choisir une semaine</label>
             <div className="flex gap-2">
               <select 
                value={selectedWeekId}
                onChange={(e) => setSelectedWeekId(e.target.value)}
                className="px-6 py-4 bg-white border border-slate-200 rounded-2xl text-xs font-bold text-slate-800 outline-none focus:ring-4 focus:ring-emerald-500/10 min-w-[220px] shadow-sm"
               >
                 <option value="current">Semaine Actuelle</option>
                 {savedPlans.map(plan => (
                   <option key={plan.id} value={plan.id}>{plan.name}</option>
                 ))}
               </select>
               <button 
                onClick={exportCSV}
                className="p-4 bg-white border border-slate-200 rounded-2xl hover:bg-slate-50 transition-all shadow-sm"
                title="Exporter en CSV"
               >
                📥
               </button>
             </div>
          </div>
        </div>

        {list.length > 0 ? (
          <div className="grid lg:grid-cols-12 gap-10">

            {/* COLONNE GAUCHE : LA LISTE */}
            <div className="lg:col-span-8 space-y-6">
              {viewMode === 'bot' ? (
                <div className="bg-white/5 border border-white/10 rounded-[40px] p-12 text-center relative overflow-hidden">
                  <div className="absolute top-0 left-0 w-full h-1 bg-white/10">
                    <div 
                      className="h-full bg-emerald-500 transition-all duration-700" 
                      style={{ width: `${((currentIndex + 1) / list.length) * 100}%` }}
                    ></div>
                  </div>

                  <div className="mb-8">
                    <span className="text-[10px] font-black text-emerald-500 uppercase tracking-[0.4em]">Article actuel</span>
