import React, { useState, useEffect, useMemo } from 'react';
import { useApp } from '../App';
import { generateShoppingList } from '../services/gemini';
import { ShoppingListItem } from '../types';

const ShoppingList: React.FC = () => {
  const { currentMealPlan, savedPlans } = useApp();
  const [list, setList] = useState<ShoppingListItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [selectedWeekId, setSelectedWeekId] = useState<string>('current');
  const [currentIndex, setCurrentIndex] = useState(0);
  const [viewMode, setViewMode] = useState<'standard' | 'bot'>('standard');
  const [logs, setLogs] = useState<string[]>([]);

  // On essaie de récupérer le dernier nombre de servings utilisé
  const servings = useMemo(() => {
    if (selectedWeekId === 'current') {
      return localStorage.getItem('nutriplan_last_servings') || '2';
    }
    const found = savedPlans.find(p => p.id === selectedWeekId);
    return found?.servings?.toString() || '2';
  }, [selectedWeekId, savedPlans]);

  // 1. Filtrage et sélection de la semaine
  const activePlan = useMemo(() => {
    if (selectedWeekId === 'current') return currentMealPlan;
    const found = savedPlans.find(p => p.id === selectedWeekId);
    return found ? found.plan : null;
  }, [selectedWeekId, currentMealPlan, savedPlans]);

  // 2. Génération de la liste d'ingrédients via Gemini
  useEffect(() => {
    const fetchList = async () => {
      if (!activePlan || activePlan.length === 0) {
        setList([]);
        return;
      }
      setLoading(true);
      try {
        const data = await generateShoppingList(activePlan);
        setList(data);
        addLog("Liste d'ingrédients synchronisée.");
      } catch (e) {
        addLog("Erreur de synchronisation.");
      } finally {
        setLoading(false);
      }
    };
    fetchList();
  }, [activePlan]);

  const addLog = (msg: string) => {
    setLogs(prev => [`[${new Date().toLocaleTimeString()}] ${msg}`, ...prev].slice(0, 5));
  };

  const handleNext = () => {
    if (currentIndex < list.length - 1) {
      const nextIdx = currentIndex + 1;
      setCurrentIndex(nextIdx);
      addLog(`Recherche : ${list[nextIdx].item}`);
      // On ouvre l'URL dans un onglet dédié que le bot va "piloter"
      const url = `https://www.delhaize.be/fr-be/search?text=${encodeURIComponent(list[nextIdx].item)}`;
      window.open(url, 'delhaize_bot');
    } else {
      setViewMode('standard');
      alert("Félicitations ! Votre panier est prêt.");
    }
  };

  const startBot = () => {
    if (list.length === 0) return;
    setViewMode('bot');
    setCurrentIndex(0);
    addLog(`Bot lancé sur : ${list[0].item}`);
    window.open(`https://www.delhaize.be/fr-be/search?text=${encodeURIComponent(list[0].item)}`, 'delhaize_bot');
  };

  const exportCSV = () => {
    const headers = "Article,Quantite,Categorie\n";
    const rows = list.map(i => `${i.item},${i.amount},${i.category}`).join("\n");
    const blob = new Blob([headers + rows], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.setAttribute('hidden', '');
    a.setAttribute('href', url);
    a.setAttribute('download', `courses_nutriplan_${selectedWeekId}.csv`);
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  };

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[60vh] text-emerald-600">
        <div className="w-12 h-12 border-4 border-emerald-100 border-t-emerald-600 rounded-full animate-spin mb-4"></div>
        <p className="font-black text-[10px] uppercase tracking-widest">Le Bot prépare les données...</p>
      </div>
    );
  }

  return (
    <div className={`min-h-screen ${viewMode === 'bot' ? 'bg-slate-950 text-white' : 'bg-slate-50 text-slate-900'} transition-colors duration-500`}>
      <div className="max-w-7xl mx-auto p-6 lg:p-12">

        {/* HEADER PILOTAGE */}
        <div className="flex flex-col md:flex-row justify-between items-end gap-6 mb-12">
          <div>
            <div className="flex items-center gap-2 mb-2">
              <span className={`w-2 h-2 rounded-full ${viewMode === 'bot' ? 'bg-red-500 animate-pulse' : 'bg-emerald-500'}`}></span>
              <p className="text-[10px] font-black uppercase tracking-[0.3em] opacity-60">
                {viewMode === 'bot' ? 'Bot en cours de pilotage' : 'Gestionnaire de courses'}
              </p>
            </div>
            <h1 className="text-5xl font-black tracking-tighter">Mon Panier.</h1>
            <p className="text-[10px] font-bold text-slate-400 mt-2 uppercase tracking-widest bg-white border border-slate-100 px-3 py-1 rounded-full inline-block">
              Calculé pour {servings} personnes
            </p>
          </div>

          <div className="flex flex-col items-end gap-3">
             <label className="text-[10px] font-black uppercase tracking-widest opacity-40">Choisir une semaine</label>
             <div className="flex gap-2">
               <select 
                value={selectedWeekId}
                onChange={(e) => setSelectedWeekId(e.target.value)}
                className="px-6 py-4 bg-white border border-slate-200 rounded-2xl text-xs font-bold text-slate-800 outline-none focus:ring-4 focus:ring-emerald-500/10 min-w-[220px] shadow-sm"
               >
                 <option value="current">Semaine Actuelle</option>
                 {savedPlans.map(plan => (
                   <option key={plan.id} value={plan.id}>{plan.name} ({plan.servings} pers.)</option>
                 ))}
               </select>
               <button 
                onClick={exportCSV}
                className="p-4 bg-white border border-slate-200 rounded-2xl hover:bg-slate-50 transition-all shadow-sm"
                title="Exporter en CSV"
               >
                📥
               </button>
             </div>
          </div>
        </div>

        {list.length > 0 ? (
          <div className="grid lg:grid-cols-12 gap-10">

            {/* COLONNE GAUCHE : LA LISTE */}
            <div className="lg:col-span-8 space-y-6">
              {viewMode === 'bot' ? (
                <div className="bg-white/5 border border-white/10 rounded-[40px] p-12 text-center relative overflow-hidden">
                  <div className="absolute top-0 left-0 w-full h-1 bg-white/10">
                    <div 
                      className="h-full bg-emerald-500 transition-all duration-700" 
                      style={{ width: `${((currentIndex + 1) / list.length) * 100}%` }}
                    ></div>
                  </div>

                  <div className="mb-8">
                    <span className="text-[10px] font-black text-emerald-500 uppercase tracking-[0.4em]">Article actuel ({servings} pers.)</span>
                    <h2 className="text-6xl font-black mt-4 mb-2">{list[currentIndex].item}</h2>
                    <p className="text-2xl font-bold text-slate-400">Quantité : <span className="text-white">{list[currentIndex].amount}</span></p>
                  </div>

                  <div className="flex flex-col gap-4 max-w-md mx-auto">
                    <button 
                      onClick={handleNext}
                      className="w-full py-6 bg-emerald-600 text-white font-black rounded-3xl text-xl shadow-2xl hover:bg-emerald-500 hover:scale-[1.02] active:scale-95 transition-all"
                    >
                      {currentIndex === list.length - 1 ? 'TERMINER LE PANIER' : 'ARTICLE SUIVANT →'}
                    </button>
                    <button 
                      onClick={() => setViewMode('standard')}
                      className="text-[10px] font-black text-slate-500 uppercase tracking-widest hover:text-white transition-colors"
                    >
                      Annuler et revenir à la liste
                    </button>
                  </div>

                  <div className="mt-12 pt-8 border-t border-white/5 text-left font-mono">
                    <p className="text-[9px] text-slate-600 uppercase font-black mb-2">Bot Logs :</p>
                    {logs.map((log, i) => (
                      <p key={i} className="text-[10px] text-slate-500">{log}</p>
                    ))}
                  </div>
                </div>
              ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {list.map((item, idx) => (
                    <div key={idx} className="bg-white p-6 rounded-3xl border border-slate-100 flex items-center justify-between group hover:border-emerald-500 transition-all">
                      <div>
                        <p className="text-xs font-black text-slate-800">{item.item}</p>
                        <p className="text-[9px] font-bold text-slate-400 uppercase mt-1">{item.amount} • {item.category}</p>
                      </div>
                      <div className="w-2 h-2 rounded-full bg-slate-100 group-hover:bg-emerald-500 transition-colors"></div>
                    </div>
                  ))}
                </div>
              )}
            </div>

            {/* COLONNE DROITE : LE BOT CONTROL */}
            <aside className="lg:col-span-4">
              <div className="sticky top-24 space-y-6">
                <div className={`rounded-[40px] p-10 transition-all duration-500 ${viewMode === 'bot' ? 'bg-emerald-600 text-white' : 'bg-slate-900 text-white shadow-2xl shadow-emerald-200'}`}>
                  <div className="w-16 h-16 bg-white/10 rounded-2xl flex items-center justify-center text-3xl mb-8 animate-bounce">🤖</div>
                  <h3 className="text-3xl font-black mb-4 leading-tight">Bot Nutri-Delhaize</h3>
                  <p className="text-sm opacity-60 mb-10 leading-relaxed">
                    Le bot va synchroniser votre liste pour <strong>{servings} personnes</strong>.
                  </p>

                  {viewMode !== 'bot' && (
                    <button 
                      onClick={startBot}
                      className="w-full py-6 bg-emerald-600 text-white font-black rounded-3xl text-xs uppercase tracking-[0.2em] shadow-xl hover:scale-105 transition-all"
                    >
                      DÉMARRER LE BOT →
                    </button>
                  )}

                  {viewMode === 'bot' && (
                    <div className="p-4 bg-white/10 rounded-2xl">
                      <p className="text-[10px] font-black uppercase mb-1">Status</p>
                      <p className="text-xs font-bold">Synchronisation en cours...</p>
