  const handleGenerate = async () => {
    if (!authState.user) return;
    updateUser({ diet: tempDiet, allergies: tempAllergies });
    setLoading(true);
    try {
      const data = await generateMealPlan(tempDiet, tempAllergies, servings, instructions);
      // On initialise isSelected à true par défaut pour tous les repas
      const initializedData = data.map(day => ({
        ...day,
        meals: {
          breakfast: { ...day.meals.breakfast, isSelected: true, isTakeAway: false },
          lunch: { ...day.meals.lunch, isSelected: true, isTakeAway: false },
          dinner: { ...day.meals.dinner, isSelected: true, isTakeAway: false },
        }
