const getDietEmoji = (pref: DietPreference) => {
  switch (pref) {
    case DietPreference.OMNIVORE: return '🍗';
    case DietPreference.VEGETARIAN: return '🥕';
    case DietPreference.VEGAN: return '🌿';
    case DietPreference.KETO: return '🥑';
    case DietPreference.PALEO: return '🥩';
    case DietPreference.GLUTEN_FREE: return '🌾';
    default: return '🍽️';
  }
};

interface MealCardProps {
  title: string;
  meal?: Meal;
  onClick: () => void;
  onToggleSelect: () => void;
  onToggleTakeAway: (e: React.MouseEvent) => void;
}

const MealCard = ({ title, meal, onClick, onToggleSelect, onToggleTakeAway }: MealCardProps) => {
  if (!meal) return null;
  const isSelected = meal.isSelected !== false;

  return (
    <div 
      className={`relative bg-white rounded-[32px] overflow-hidden border transition-all duration-300 flex flex-col h-full group ${
        isSelected ? 'border-slate-100 shadow-sm opacity-100' : 'border-slate-100 opacity-50 grayscale scale-[0.98]'
      }`}
    >
      {/* Checkbox Selection */}
      <button 
        onClick={(e) => { e.stopPropagation(); onToggleSelect(); }}
        className={`absolute top-4 right-4 z-20 w-8 h-8 rounded-full border-2 flex items-center justify-center transition-all ${
          isSelected ? 'bg-emerald-600 border-emerald-600 text-white' : 'bg-white/80 border-slate-300 text-transparent'
        }`}
      >
        <span className="text-xs font-bold">✓</span>
      </button>

      <div className="h-44 relative overflow-hidden cursor-pointer" onClick={onClick}>
        <img src={meal.image} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700" alt={meal.name} />
        <div className="absolute top-3 left-3 px-3 py-1 bg-white/95 backdrop-blur rounded-lg text-[9px] font-black text-slate-900 uppercase tracking-widest shadow-sm">{title}</div>
      </div>

      <div className="p-6 flex flex-col flex-grow">
        <div className="flex justify-between items-start mb-2">
          <h3 className="text-lg font-black text-slate-900 leading-tight cursor-pointer hover:text-emerald-700 transition-colors" onClick={onClick}>{meal.name}</h3>
        </div>

        <div className="flex gap-2 mb-4">
           <button 
             onClick={onToggleTakeAway}
             className={`px-3 py-1 rounded-full text-[8px] font-black uppercase transition-all ${
               meal.isTakeAway 
                ? 'bg-amber-100 text-amber-700 border border-amber-200' 
                : 'bg-slate-100 text-slate-400 border border-slate-100 hover:border-slate-200'
             }`}
           >
             {meal.isTakeAway ? 'À Emporter 🥡' : 'Sur Place 🍽️'}
           </button>
        </div>

        <div className="mt-auto flex justify-between items-center text-[10px] font-black text-emerald-600">
          <span className="bg-emerald-50 px-2 py-1 rounded-md">{meal.calories} KCAL</span>
          <button onClick={onClick} className="text-slate-300 uppercase tracking-widest hover:text-emerald-500 transition-colors">Détails →</button>
        </div>
      </div>
    </div>
  );
};

