import React, { useState, useEffect, useMemo } from 'react';
import { useApp } from '../App';
import { generateShoppingList } from '../services/gemini';
import { ShoppingListItem, DayPlan } from '../types';

const ShoppingList: React.FC = () => {
  const { currentMealPlan, savedPlans } = useApp();
  const [list, setList] = useState<ShoppingListItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [selectedWeekId, setSelectedWeekId] = useState<string>('current');

  // On essaie de récupérer le dernier nombre de servings utilisé
  const servings = useMemo(() => {
    if (selectedWeekId === 'current') {
      return localStorage.getItem('nutriplan_last_servings') || '2';
    }
    const found = savedPlans.find(p => p.id === selectedWeekId);
    return found?.servings?.toString() || '2';
  }, [selectedWeekId, savedPlans]);

  // 1. Filtrage et sélection de la semaine + filtrage des repas non-sélectionnés
  const activePlan = useMemo(() => {
    let planToProcess: DayPlan[] | null = null;
    if (selectedWeekId === 'current') {
      planToProcess = currentMealPlan;
    } else {
      const found = savedPlans.find(p => p.id === selectedWeekId);
      planToProcess = found ? found.plan : null;
    }

    if (!planToProcess) return null;

    // IMPORTANT: On ne garde que les ingrédients des repas sélectionnés
    return planToProcess.map(day => ({
      ...day,
      meals: {
        breakfast: day.meals.breakfast?.isSelected !== false ? day.meals.breakfast : null as any,
        lunch: day.meals.lunch?.isSelected !== false ? day.meals.lunch : null as any,
        dinner: day.meals.dinner?.isSelected !== false ? day.meals.dinner : null as any,
      }
    })).filter(day => day.meals.breakfast || day.meals.lunch || day.meals.dinner);
  }, [selectedWeekId, currentMealPlan, savedPlans]);

  // 2. Génération de la liste d'ingrédients via Gemini
  useEffect(() => {
    const fetchList = async () => {
      if (!activePlan || activePlan.length === 0) {
        setList([]);
        return;
      }
      setLoading(true);
      try {
        const data = await generateShoppingList(activePlan);
        setList(data);
      } catch (e) {
        console.error("Erreur de synchronisation:", e);
      } finally {
        setLoading(false);
      }
    };
    fetchList();
  }, [activePlan]);

  const exportCSV = () => {
    const headers = "Article,Quantite,Categorie\n";
    const rows = list.map(i => `"${i.item}","${i.amount}","${i.category}"`).join("\n");
    const blob = new Blob([headers + rows], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.setAttribute('hidden', '');
    a.setAttribute('href', url);
    a.setAttribute('download', `courses_nutriplan_${selectedWeekId}.csv`);
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
  };

  const openRetailerSearch = (item: string, retailer: 'delhaize' | 'colruyt' | 'carrefour') => {
    let url = '';
    const query = encodeURIComponent(item);
    switch (retailer) {
      case 'delhaize':
        url = `https://www.delhaize.be/fr-be/search?text=${query}`;
        break;
      case 'colruyt':
        url = `https://www.collectandgo.be/colruyt/fr/recherche?searchTerm=${query}`;
        break;
      case 'carrefour':
        url = `https://www.carrefour.be/fr/recherche.html?q=${query}`;
        break;
