      <div className="flex flex-col items-center justify-center min-h-[60vh] text-emerald-600">
        <div className="w-12 h-12 border-4 border-emerald-100 border-t-emerald-600 rounded-full animate-spin mb-4"></div>
        <p className="font-black text-[10px] uppercase tracking-widest">Optimisation de votre liste...</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900">
      <div className="max-w-7xl mx-auto p-6 lg:p-12">

        {/* HEADER */}
        <div className="flex flex-col md:flex-row justify-between items-end gap-6 mb-12">
          <div>
            <div className="flex items-center gap-2 mb-2">
              <span className="w-2 h-2 rounded-full bg-emerald-500"></span>
              <p className="text-[10px] font-black uppercase tracking-[0.3em] opacity-60">Panier intelligent</p>
            </div>
            <h1 className="text-5xl font-black tracking-tighter">Mes Courses.</h1>
            <p className="text-[10px] font-bold text-slate-400 mt-2 uppercase tracking-widest bg-white border border-slate-100 px-3 py-1 rounded-full inline-block">
              Calculé pour {servings} personnes
            </p>
          </div>

          <div className="flex flex-col items-end gap-3">
             <label className="text-[10px] font-black uppercase tracking-widest opacity-40">Semaine sélectionnée</label>
             <div className="flex gap-2">
               <select 
                value={selectedWeekId}
                onChange={(e) => setSelectedWeekId(e.target.value)}
                className="px-6 py-4 bg-white border border-slate-200 rounded-2xl text-xs font-bold text-slate-800 outline-none focus:ring-4 focus:ring-emerald-500/10 min-w-[220px] shadow-sm"
               >
                 <option value="current">Semaine Actuelle</option>
                 {savedPlans.map(plan => (
                   <option key={plan.id} value={plan.id}>{plan.name} ({plan.servings} pers.)</option>
                 ))}
               </select>
               <button 
                onClick={exportCSV}
                className="p-4 bg-white border border-slate-200 rounded-2xl hover:bg-slate-50 transition-all shadow-sm flex items-center gap-2"
                title="Exporter en CSV"
               >
                <span className="text-xs font-bold text-slate-600">Exporter</span>
                <span>📥</span>
               </button>
             </div>
          </div>
        </div>

        {list.length > 0 ? (
          <div className="space-y-12">

            {/* INSTRUCTION */}
            <div className="bg-emerald-600 rounded-[32px] p-8 text-white flex flex-col md:flex-row items-center gap-8 shadow-xl shadow-emerald-100">
               <div className="w-16 h-16 bg-white/20 rounded-2xl flex items-center justify-center text-3xl">🛒</div>
               <div>
                 <h3 className="text-xl font-black mb-1">Remplissez votre panier</h3>
                 <p className="text-white/70 text-sm">Cliquez sur l'enseigne de votre choix pour chaque ingrédient. Votre liste ne contient que les repas sélectionnés.</p>
               </div>
            </div>

            {/* LISTE PAR CATEGORIE */}
            <div className="grid grid-cols-1 gap-12">
              {Array.from(new Set(list.map(i => i.category))).map(cat => (
                <div key={cat}>
                  <h2 className="text-[10px] font-black text-slate-300 uppercase tracking-[0.5em] mb-6 flex items-center gap-4">
                    {cat}
                    <div className="h-[1px] bg-slate-100 flex-grow"></div>
                  </h2>
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {list.filter(i => i.category === cat).map((item, idx) => (
                      <div key={idx} className="bg-white p-6 rounded-[32px] border border-slate-100 shadow-sm flex flex-col h-full group hover:border-emerald-500 transition-all">
                        <div className="flex justify-between items-start mb-6">
                          <div>
                            <p className="text-sm font-black text-slate-800">{item.item}</p>
                            <p className="text-[10px] font-bold text-slate-400 uppercase mt-1 italic">{item.amount}</p>
                          </div>
                          <div className="w-2 h-2 rounded-full bg-slate-100 group-hover:bg-emerald-500 transition-colors"></div>
