                             >
                               Delhaize
                             </button>
                             <button 
                               onClick={() => openRetailerSearch(item.item, 'colruyt')}
                               className="py-2 px-1 bg-orange-50 text-orange-600 rounded-xl text-[8px] font-black uppercase hover:bg-orange-600 hover:text-white transition-all text-center"
                             >
                               Colruyt
                             </button>
                             <button 
                               onClick={() => openRetailerSearch(item.item, 'carrefour')}
                               className="py-2 px-1 bg-blue-50 text-blue-600 rounded-xl text-[8px] font-black uppercase hover:bg-blue-600 hover:text-white transition-all text-center"
                             >
                               Carrefour
                             </button>
                           </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              ))}
            </div>

          </div>
        ) : (
          <div className="text-center py-32 bg-white rounded-[60px] border-4 border-dashed border-slate-100">
            <div className="text-6xl mb-6 opacity-20">🛒</div>
            <h3 className="text-2xl font-black text-slate-300 uppercase tracking-widest">Votre panier est vide.</h3>
            <p className="text-slate-400 mt-2 font-medium">Vérifiez que vous avez sélectionné des repas dans votre planning.</p>
            <button 
              onClick={() => window.location.reload()} 
              className="mt-8 px-8 py-4 bg-emerald-600 text-white font-black rounded-2xl text-[10px] uppercase tracking-widest shadow-xl shadow-emerald-100"
            >
              Aller au planning
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default ShoppingList;

import { GoogleGenAI, Type } from "@google/genai";
import { DietPreference, DayPlan, ShoppingListItem } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

const MEAL_PROPERTIES = {
  name: { type: Type.STRING },
  description: { type: Type.STRING },
  calories: { type: Type.NUMBER },
  ingredients: { type: Type.ARRAY, items: { type: Type.STRING } },
  instructions: { type: Type.ARRAY, items: { type: Type.STRING } },
  image: { type: Type.STRING }
};

const REQUIRED_MEAL_FIELDS = ['name', 'description', 'calories', 'ingredients', 'instructions', 'image'];

const MEAL_PLAN_SCHEMA = {
  type: Type.ARRAY,
  items: {
    type: Type.OBJECT,
    properties: {
      day: { type: Type.STRING },
      meals: {
        type: Type.OBJECT,
        properties: {
          breakfast: {
            type: Type.OBJECT,
            properties: MEAL_PROPERTIES,
            required: REQUIRED_MEAL_FIELDS
          },
          lunch: {
            type: Type.OBJECT,
            properties: MEAL_PROPERTIES,
            required: REQUIRED_MEAL_FIELDS
          },
          dinner: {
            type: Type.OBJECT,
            properties: MEAL_PROPERTIES,
            required: REQUIRED_MEAL_FIELDS
          }
        },
        required: ['breakfast', 'lunch', 'dinner']
      }
    },
    required: ['day', 'meals']
  }
};

export const generateMealPlan = async (
  diet: DietPreference, 
  allergies: string[], 
  servings: number, 
  days: string[], 
  instructions?: string
): Promise<DayPlan[]> => {
  try {
    const customPrompt = instructions ? `Prend en compte ces instructions : "${instructions}".` : "";

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Génère un menu pour les jours suivants : ${days.join(', ')}.
                Régime : ${diet}. 
                Nombre de personnes : ${servings}. 
                Allergies : ${allergies.join(', ') || 'Aucune'}. 
                ${customPrompt}
                IMPORTANT: Calcule les quantités pour exactement ${servings} personnes.
                Chaque jour doit avoir Petit-déjeuner, Déjeuner et Dîner.
                Ajoute une URL d'image Unsplash pertinente (ex: https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=400).`,
      config: {
        responseMimeType: "application/json",
        responseSchema: MEAL_PLAN_SCHEMA
      }
    });

    const text = response.text;
    if (!text) return [];
    return JSON.parse(text);
  } catch (error) {
    console.error("Error generating meal plan:", error);
    return [];
  }
};

export const generateShoppingList = async (mealPlan: any[]): Promise<ShoppingListItem[]> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Crée une liste de courses consolidée pour ces repas (ignore les repas non sélectionnés) : ${JSON.stringify(mealPlan)}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              item: { type: Type.STRING },
              amount: { type: Type.STRING },
              category: { type: Type.STRING },
              checked: { type: Type.BOOLEAN }
            },
            required: ['item', 'amount', 'category', 'checked']
          }
        }
      }
    });

    const text = response.text;
    if (!text) return [];
    return JSON.parse(text);
  } catch (error) {
    console.error("Error generating shopping list:", error);
    return [];
  }
};

import React, { useState } from 'react';
import { useApp } from '../App';
import { generateMealPlan } from '../services/gemini';
import { DayPlan, DietPreference, Meal } from '../types';

const DAYS_OF_WEEK = ['Lundi', 'Mardi', 'Mercredi', 'Jeudi', 'Vendredi', 'Samedi', 'Dimanche'];

const Dashboard: React.FC = () => {
  const { authState, updateUser, currentMealPlan, setCurrentMealPlan, savedPlans, saveCurrentPlan } = useApp();
  const [loading, setLoading] = useState(false);
  const [activeDay, setActiveDay] = useState(0);
  const [isSaving, setIsSaving] = useState(false);
  const [saveName, setSaveName] = useState('');
  const [instructions, setInstructions] = useState('');
  const [selectedMeal, setSelectedMeal] = useState<Meal | null>(null);
  const [servings, setServings] = useState(2);
  const [selectedDays, setSelectedDays] = useState<string[]>(DAYS_OF_WEEK);
  const [defaultTakeAway, setDefaultTakeAway] = useState(false);

  const [tempDiet, setTempDiet] = useState<DietPreference>(authState.user?.diet || DietPreference.OMNIVORE);
  const [tempAllergies, setTempAllergies] = useState<string[]>(authState.user?.allergies || []);

  const toggleDay = (day: string) => {
    setSelectedDays(prev => 
      prev.includes(day) ? prev.filter(d => d !== day) : [...prev, day]
    );
  };

  const handleGenerate = async () => {
    if (!authState.user || selectedDays.length === 0) return;
    updateUser({ diet: tempDiet, allergies: tempAllergies });
    setLoading(true);
    try {
      const data = await generateMealPlan(tempDiet, tempAllergies, servings, selectedDays, instructions);
      const initializedData = data.map(day => ({
        ...day,
        meals: {
          breakfast: { ...day.meals.breakfast, isSelected: true, isTakeAway: false },
          lunch: { ...day.meals.lunch, isSelected: true, isTakeAway: defaultTakeAway },
          dinner: { ...day.meals.dinner, isSelected: true, isTakeAway: false },
        }
      }));
      setCurrentMealPlan(initializedData || []);
      localStorage.setItem('nutriplan_last_servings', servings.toString());
      setActiveDay(0);
    } catch (err) {
      console.error("Erreur génération:", err);
    } finally {
      setLoading(false);
    }
  };

  const toggleMealSelection = (dayIdx: number, mealType: 'breakfast' | 'lunch' | 'dinner') => {
    if (!currentMealPlan) return;
    const newPlan = [...currentMealPlan];
    const meal = newPlan[dayIdx].meals[mealType];
    meal.isSelected = !meal.isSelected;
    setCurrentMealPlan(newPlan);
  };

  const toggleMealTakeAway = (dayIdx: number, mealType: 'breakfast' | 'lunch' | 'dinner', e: React.MouseEvent) => {
    e.stopPropagation();
    if (!currentMealPlan) return;
    const newPlan = [...currentMealPlan];
    const meal = newPlan[dayIdx].meals[mealType];
    meal.isTakeAway = !meal.isTakeAway;
    setCurrentMealPlan(newPlan);
  };

  if (loading) {
    return (
      <div className="p-8 flex flex-col items-center justify-center min-h-[60vh]">
        <div className="w-16 h-16 border-4 border-emerald-500/20 border-t-emerald-500 rounded-full animate-spin mb-6"></div>
        <p className="text-xl font-bold text-slate-900 tracking-tight">IA Nutriplan compose votre menu...</p>
        <p className="text-slate-400 mt-2 text-sm italic">Planification pour {selectedDays.length} jours...</p>
      </div>
    );
  }

  return (
    <div className="p-6 max-w-7xl mx-auto">
      {selectedMeal && <MealDetailModal meal={selectedMeal} onClose={() => setSelectedMeal(null)} />}

      <div className="grid lg:grid-cols-4 gap-8">
        <aside className="lg:col-span-1 space-y-6">
          <div className="bg-emerald-600 rounded-[32px] p-6 text-white shadow-xl shadow-emerald-200">
            <h3 className="text-[10px] font-black opacity-60 uppercase tracking-widest mb-4">Action Rapide</h3>
            <button 
              onClick={() => setCurrentMealPlan(null)}
              className="w-full py-4 bg-white/20 hover:bg-white/30 transition-all rounded-2xl font-black text-xs uppercase tracking-widest"
            >
              🚀 Nouveau Plan
            </button>
          </div>

          <div className="bg-white rounded-[32px] p-6 shadow-sm border border-slate-100">
            <h3 className="text-[10px] font-black text-slate-300 uppercase tracking-[0.3em] mb-6">📂 HISTORIQUE</h3>
            <div className="space-y-3">
              {savedPlans.length === 0 ? (
                <div className="p-4 bg-slate-50/50 rounded-2xl border border-dashed border-slate-100 text-center">
                  <p className="text-[10px] text-slate-400 font-medium italic">Aucun menu sauvegardé.</p>
                </div>
              ) : (
                savedPlans.slice(0, 5).map(plan => (
                  <button 
                    key={plan.id}
                    onClick={() => { setCurrentMealPlan(plan.plan); setServings(plan.servings || 2); setActiveDay(0); }}
                    className="w-full text-left p-4 rounded-2xl hover:bg-emerald-50 transition-all border border-transparent hover:border-emerald-100 group"
                  >
                    <div className="flex justify-between items-start">
                      <p className="text-xs font-bold text-slate-700 group-hover:text-emerald-700">{plan.name}</p>
                      <span className="text-[8px] bg-slate-100 px-1.5 py-0.5 rounded text-slate-500 font-black">{plan.servings} PERS.</span>
                    </div>
                  </button>
                ))
              )}
            </div>
          </div>
        </aside>

        <div className="lg:col-span-3">
          {currentMealPlan && currentMealPlan.length > 0 ? (
            <>
              <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 mb-8">
                <div>
                  <h1 className="text-3xl font-black text-slate-900 tracking-tight">Mon Planning</h1>
                  <p className="text-slate-500 text-sm italic">Personnalisez chaque repas avant les courses.</p>
                </div>
                <div className="flex gap-3">
                  <button onClick={() => setIsSaving(true)} className="px-6 py-3 bg-white border border-slate-200 rounded-xl text-[10px] font-bold text-slate-600">📁 Classer</button>
                  <button onClick={() => setCurrentMealPlan(null)} className="px-6 py-3 bg-slate-900 text-white rounded-xl text-[10px] font-bold shadow-lg">Regénérer</button>
                </div>
              </div>

              {isSaving && (
                <div className="mb-8 p-6 bg-white border border-emerald-100 rounded-[32px] flex flex-col sm:flex-row gap-4 items-center shadow-xl">
                  <input 
                    type="text" placeholder="Nom du menu..."
                    className="flex-grow px-5 py-3 rounded-xl bg-slate-50 border-none outline-none text-sm font-bold"
                    value={saveName} onChange={(e) => setSaveName(e.target.value)}
                  />
                  <button onClick={() => { saveCurrentPlan(saveName); setIsSaving(false); setSaveName(''); }} className="px-8 py-3 bg-emerald-600 text-white font-bold rounded-xl text-xs uppercase">OK</button>
                </div>
              )}

              <div className="flex gap-2 mb-8 overflow-x-auto pb-4 no-scrollbar">
                {currentMealPlan.map((plan, idx) => (
                  <button
                    key={idx}
                    onClick={() => setActiveDay(idx)}
                    className={`px-8 py-4 rounded-2xl whitespace-nowrap font-bold text-[10px] uppercase tracking-widest transition-all ${
                      activeDay === idx ? 'bg-emerald-600 text-white shadow-lg scale-105' : 'bg-white text-slate-400 border border-slate-100'
                    }`}
                  >
                    {plan.day}
                  </button>
                ))}
              </div>

              <div className="grid md:grid-cols-3 gap-6">
                <MealCard 
                  title="Matin" meal={currentMealPlan[activeDay]?.meals?.breakfast} 
                  onToggleSelect={() => toggleMealSelection(activeDay, 'breakfast')}
                  onToggleTakeAway={(e) => toggleMealTakeAway(activeDay, 'breakfast', e)}
                  onClick={() => setSelectedMeal(currentMealPlan[activeDay].meals.breakfast)} 
                />
                <MealCard 
                  title="Midi" meal={currentMealPlan[activeDay]?.meals?.lunch} 
                  onToggleSelect={() => toggleMealSelection(activeDay, 'lunch')}
                  onToggleTakeAway={(e) => toggleMealTakeAway(activeDay, 'lunch', e)}
                  onClick={() => setSelectedMeal(currentMealPlan[activeDay].meals.lunch)} 
                />
                <MealCard 
                  title="Soir" meal={currentMealPlan[activeDay]?.meals?.dinner} 
                  onToggleSelect={() => toggleMealSelection(activeDay, 'dinner')}
                  onToggleTakeAway={(e) => toggleMealTakeAway(activeDay, 'dinner', e)}
                  onClick={() => setSelectedMeal(currentMealPlan[activeDay].meals.dinner)} 
                />
              </div>
            </>
          ) : (
            <div className="bg-white rounded-[40px] p-10 md:p-14 shadow-sm border border-slate-100">
              <div className="max-w-3xl mx-auto">
                <div className="text-center mb-12">
                  <div className="w-20 h-20 bg-emerald-50 text-emerald-600 rounded-[30px] flex items-center justify-center text-4xl mx-auto mb-6 animate-bounce">🌱</div>
                  <h2 className="text-4xl font-black text-slate-900 mb-3 tracking-tight">Planification IA</h2>
                  <p className="text-slate-400 font-medium text-sm">Configurez votre semaine sur-mesure.</p>
                </div>

                <div className="space-y-12">
                  {/* CHOIX DES JOURS */}
                  <div>
                    <label className="block text-[10px] font-black text-slate-300 uppercase tracking-[0.2em] mb-4">1. Pour quels jours ?</label>
                    <div className="flex flex-wrap gap-2">
                      {DAYS_OF_WEEK.map(day => (
                        <button
                          key={day}
                          onClick={() => toggleDay(day)}
                          className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${
                            selectedDays.includes(day) ? 'bg-emerald-600 text-white shadow-lg' : 'bg-slate-50 text-slate-400 border border-slate-100'
                          }`}
                        >
                          {day}
                        </button>
                      ))}
                    </div>
                  </div>

                  <div className="grid md:grid-cols-2 gap-8">
                    {/* SERVINGS & TAKE AWAY */}
                    <div className="space-y-6">
                      <div className="bg-slate-50/50 p-6 rounded-[32px] border border-slate-100 text-center">
                        <label className="block text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-4">Nombre de personnes</label>
                        <div className="flex items-center justify-center gap-6">
                          <button onClick={() => setServings(Math.max(1, servings - 1))} className="w-10 h-10 bg-white rounded-full shadow-sm font-black">-</button>
                          <span className="text-4xl font-black text-slate-900">{servings}</span>
                          <button onClick={() => setServings(Math.min(12, servings + 1))} className="w-10 h-10 bg-white rounded-full shadow-sm font-black">+</button>
                        </div>
                      </div>

                      <button 
                        onClick={() => setDefaultTakeAway(!defaultTakeAway)}
                        className={`w-full p-6 rounded-[32px] border-2 flex items-center justify-between transition-all ${
                          defaultTakeAway ? 'border-amber-500 bg-amber-50' : 'border-slate-100 bg-white'
                        }`}
                      >
                        <div className="text-left">
                          <p className={`text-xs font-black uppercase ${defaultTakeAway ? 'text-amber-700' : 'text-slate-400'}`}>Mode Nomade 🥡</p>
                          <p className="text-[10px] font-medium text-slate-500 mt-1">Repas du midi "à emporter" par défaut</p>
                        </div>
                        <div className={`w-6 h-6 rounded-full border-2 flex items-center justify-center ${defaultTakeAway ? 'bg-amber-600 border-amber-600 text-white' : 'border-slate-200'}`}>
                          {defaultTakeAway && '✓'}
                        </div>
                      </button>
                    </div>

                    {/* DIET & ALLERGIES */}
                    <div className="bg-slate-50/50 p-6 rounded-[32px] border border-slate-100">
                      <label className="block text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-4">Régime & Instructions</label>
                      <select 
                        value={tempDiet} onChange={(e) => setTempDiet(e.target.value as DietPreference)}
                        className="w-full p-3 rounded-xl mb-4 bg-white border border-slate-100 text-xs font-bold"
                      >
                        {Object.values(DietPreference).map(d => <option key={d} value={d}>{d}</option>)}
                      </select>
                      <textarea 
                        placeholder="Instructions spéciales..."
                        className="w-full h-20 p-4 bg-white border border-slate-100 rounded-2xl text-xs font-medium resize-none"
                        value={instructions} onChange={(e) => setInstructions(e.target.value)}
                      />
                    </div>
                  </div>

                  <button 
                    onClick={handleGenerate}
                    className="w-full py-6 bg-emerald-600 text-white font-black text-lg rounded-[28px] hover:bg-emerald-700 transition-all shadow-xl shadow-emerald-100"
                  >
                    GÉNÉRER MON MENU IA
                  </button>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

const MealDetailModal = ({ meal, onClose }: { meal: Meal, onClose: () => void }) => (
  <div className="fixed inset-0 z-[100] bg-slate-900/60 backdrop-blur-sm flex items-center justify-center p-4">
    <div className="bg-white w-full max-w-4xl max-h-[90vh] rounded-[40px] overflow-hidden shadow-2xl flex flex-col md:flex-row relative animate-in zoom-in duration-200">
      <button onClick={onClose} className="absolute top-6 right-6 z-10 w-10 h-10 bg-white/90 rounded-full shadow-lg flex items-center justify-center text-slate-900">✕</button>
      <div className="md:w-1/2 h-64 md:h-auto overflow-hidden">
        <img src={meal.image} className="w-full h-full object-cover" alt={meal.name} />
      </div>
      <div className="md:w-1/2 p-8 md:p-12 overflow-y-auto custom-scrollbar">
        <span className="text-[10px] font-black text-emerald-600 uppercase tracking-widest bg-emerald-50 px-3 py-1 rounded-lg">Recette</span>
        <h2 className="text-3xl font-black text-slate-900 mt-4 leading-tight">{meal.name}</h2>
        <div className="mt-8 space-y-6">
          <div>
            <h4 className="text-[10px] font-black text-slate-300 uppercase tracking-widest mb-3">Ingrédients</h4>
            <ul className="space-y-2">
              {meal.ingredients.map((ing, i) => <li key={i} className="text-sm font-bold text-slate-700 flex gap-2"><span className="text-emerald-500">•</span> {ing}</li>)}
            </ul>
          </div>
        </div>
      </div>
    </div>
  </div>
);

const MealCard = ({ title, meal, onClick, onToggleSelect, onToggleTakeAway }: any) => {
  if (!meal) return null;
  const isSelected = meal.isSelected !== false;
  return (
    <div className={`relative bg-white rounded-[32px] overflow-hidden border transition-all duration-300 flex flex-col h-full group ${isSelected ? 'border-slate-100 opacity-100' : 'opacity-40 grayscale scale-95'}`}>
      <button onClick={(e) => { e.stopPropagation(); onToggleSelect(); }} className={`absolute top-4 right-4 z-20 w-8 h-8 rounded-full border-2 flex items-center justify-center transition-all ${isSelected ? 'bg-emerald-600 border-emerald-600 text-white' : 'bg-white border-slate-200'}`}>✓</button>
      <div className="h-44 overflow-hidden cursor-pointer" onClick={onClick}>
        <img src={meal.image} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" alt={meal.name} />
        <div className="absolute top-3 left-3 px-3 py-1 bg-white/95 backdrop-blur rounded-lg text-[9px] font-black text-slate-900 uppercase tracking-widest">{title}</div>
      </div>
      <div className="p-6 flex flex-col flex-grow">
        <h3 className="text-md font-black text-slate-900 mb-4 leading-tight cursor-pointer" onClick={onClick}>{meal.name}</h3>
        <div className="mt-auto flex justify-between items-center">
          <button onClick={onToggleTakeAway} className={`px-3 py-1 rounded-full text-[8px] font-black uppercase transition-all ${meal.isTakeAway ? 'bg-amber-100 text-amber-700' : 'bg-slate-100 text-slate-400'}`}>
            {meal.isTakeAway ? '🥡 À Emporter' : '🍽️ Maison'}
          </button>
          <span className="text-[10px] font-black text-emerald-600">{meal.calories} KCAL</span>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect, useMemo } from 'react';
import { useApp } from '../App';
import { generateShoppingList } from '../services/gemini';
import { ShoppingListItem } from '../types';

const ShoppingList: React.FC = () => {
  const { currentMealPlan, savedPlans } = useApp();
  const [list, setList] = useState<ShoppingListItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [selectedWeekId, setSelectedWeekId] = useState<string>('current');
  const [viewMode, setViewMode] = useState<'standard' | 'assistant'>('standard');
  const [currentIndex, setCurrentIndex] = useState(0);

  const servings = useMemo(() => {
    if (selectedWeekId === 'current') return localStorage.getItem('nutriplan_last_servings') || '2';
    return savedPlans.find(p => p.id === selectedWeekId)?.servings?.toString() || '2';
  }, [selectedWeekId, savedPlans]);

  const activePlan = useMemo(() => {
    let p = selectedWeekId === 'current' ? currentMealPlan : savedPlans.find(p => p.id === selectedWeekId)?.plan;
    if (!p) return null;
    return p.filter(day => day.meals.breakfast?.isSelected || day.meals.lunch?.isSelected || day.meals.dinner?.isSelected);
  }, [selectedWeekId, currentMealPlan, savedPlans]);

  useEffect(() => {
    const fetchList = async () => {
      if (!activePlan || activePlan.length === 0) {
        setList([]);
        return;
      }
      setLoading(true);
      try {
        const data = await generateShoppingList(activePlan);
        setList(data);
      } catch (e) {
        console.error(e);
      } finally {
        setLoading(false);
      }
    };
    fetchList();
  }, [activePlan]);

  const openRetailerSearch = (item: string, retailer: 'delhaize' | 'colruyt' | 'carrefour') => {
    let url = '';
    const q = encodeURIComponent(item);
    if (retailer === 'delhaize') url = `https://www.delhaize.be/fr-be/search?text=${q}`;
    else if (retailer === 'colruyt') url = `https://www.collectandgo.be/colruyt/fr/recherche?searchTerm=${q}`;
    else url = `https://www.carrefour.be/fr/recherche.html?q=${q}`;
    window.open(url, '_blank');
  };

  const nextItem = () => {
    if (currentIndex < list.length - 1) setCurrentIndex(currentIndex + 1);
    else setViewMode('standard');
  };

  if (loading) return (
    <div className="flex flex-col items-center justify-center min-h-[60vh] text-emerald-600">
      <div className="w-12 h-12 border-4 border-emerald-100 border-t-emerald-600 rounded-full animate-spin mb-4"></div>
      <p className="font-black text-[10px] uppercase tracking-widest">IA Nutriplan optimise vos achats...</p>
    </div>
  );

  return (
    <div className={`min-h-screen transition-colors duration-500 ${viewMode === 'assistant' ? 'bg-slate-900 text-white' : 'bg-slate-50 text-slate-900'}`}>
      <div className="max-w-7xl mx-auto p-6 lg:p-12">

        {/* HEADER */}
        <div className="flex flex-col md:flex-row justify-between items-end gap-6 mb-12">
          <div>
            <h1 className="text-5xl font-black tracking-tighter">Mon Panier.</h1>
            <p className="text-[10px] font-bold text-slate-400 mt-2 uppercase tracking-widest">
              Pour {servings} personnes • {list.length} articles
            </p>
          </div>

          <div className="flex gap-4">
             <select 
              value={selectedWeekId} onChange={(e) => setSelectedWeekId(e.target.value)}
              className="px-6 py-4 bg-white border border-slate-200 rounded-2xl text-xs font-bold text-slate-800 shadow-sm"
             >
               <option value="current">Semaine Actuelle</option>
               {savedPlans.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}
             </select>
             {list.length > 0 && viewMode === 'standard' && (
               <button 
                onClick={() => { setViewMode('assistant'); setCurrentIndex(0); }}
                className="px-8 py-4 bg-emerald-600 text-white font-black rounded-2xl text-[10px] uppercase tracking-widest shadow-xl shadow-emerald-200"
               >
                 Démarrer l'Assistance Panier 🚀
               </button>
             )}
          </div>
        </div>

        {list.length > 0 ? (
          <div className="grid lg:grid-cols-12 gap-10">
            {viewMode === 'assistant' ? (
              <div className="lg:col-span-12">
                <div className="bg-white/5 border border-white/10 rounded-[40px] p-10 md:p-20 text-center relative overflow-hidden">
                  <div className="absolute top-0 left-0 w-full h-1 bg-white/5">
                    <div className="h-full bg-emerald-500 transition-all duration-500" style={{ width: `${((currentIndex+1)/list.length)*100}%` }}></div>
                  </div>

                  <div className="mb-12">
                    <span className="text-[10px] font-black text-emerald-500 uppercase tracking-[0.4em]">Article {currentIndex + 1} / {list.length}</span>
                    <h2 className="text-6xl md:text-8xl font-black mt-6 mb-4">{list[currentIndex].item}</h2>
                    <p className="text-3xl font-bold text-slate-400">Besoin : <span className="text-white">{list[currentIndex].amount}</span></p>
                  </div>

                  <div className="max-w-2xl mx-auto space-y-6">
                    <p className="text-[10px] font-black text-slate-500 uppercase tracking-widest">1. Choisir l'enseigne pour ouvrir la recherche :</p>
                    <div className="grid grid-cols-3 gap-4">
                      <button onClick={() => openRetailerSearch(list[currentIndex].item, 'delhaize')} className="py-6 bg-red-600 hover:bg-red-500 text-white font-black rounded-3xl text-xs uppercase tracking-widest transition-all">Delhaize</button>
                      <button onClick={() => openRetailerSearch(list[currentIndex].item, 'colruyt')} className="py-6 bg-orange-600 hover:bg-orange-500 text-white font-black rounded-3xl text-xs uppercase tracking-widest transition-all">Colruyt</button>
                      <button onClick={() => openRetailerSearch(list[currentIndex].item, 'carrefour')} className="py-6 bg-blue-600 hover:bg-blue-500 text-white font-black rounded-3xl text-xs uppercase tracking-widest transition-all">Carrefour</button>
                    </div>

                    <div className="pt-10">
                      <button 
                        onClick={nextItem}
                        className="w-full py-8 bg-white text-slate-900 font-black rounded-[32px] text-xl shadow-2xl hover:bg-slate-100 transition-all"
                      >
                        {currentIndex === list.length - 1 ? 'TERMINER' : 'ARTICLE SUIVANT →'}
                      </button>
                      <button onClick={() => setViewMode('standard')} className="mt-6 text-[10px] font-black text-slate-500 uppercase tracking-widest hover:text-white transition-colors">Quitter l'assistance</button>
                    </div>
                  </div>
                </div>
              </div>
            ) : (
              <div className="lg:col-span-12 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                {list.map((item, idx) => (
                  <div key={idx} className="bg-white p-6 rounded-[32px] border border-slate-100 shadow-sm flex flex-col group hover:border-emerald-500 transition-all">
                    <div className="mb-6">
                      <p className="text-xs font-black text-slate-800">{item.item}</p>
                      <p className="text-[10px] font-bold text-slate-400 uppercase mt-1 italic">{item.amount}</p>
                    </div>
                    <div className="mt-auto grid grid-cols-3 gap-1">
                       <button onClick={() => openRetailerSearch(item.item, 'delhaize')} className="p-2 bg-red-50 text-red-600 rounded-lg text-[8px] font-black uppercase hover:bg-red-600 hover:text-white transition-all">D.</button>
                       <button onClick={() => openRetailerSearch(item.item, 'colruyt')} className="p-2 bg-orange-50 text-orange-600 rounded-lg text-[8px] font-black uppercase hover:bg-orange-600 hover:text-white transition-all">C.</button>
                       <button onClick={() => openRetailerSearch(item.item, 'carrefour')} className="p-2 bg-blue-50 text-blue-600 rounded-lg text-[8px] font-black uppercase hover:bg-blue-600 hover:text-white transition-all">F.</button>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        ) : (
          <div className="text-center py-32 bg-white rounded-[60px] border-4 border-dashed border-slate-100">
            <h3 className="text-2xl font-black text-slate-300 uppercase tracking-widest">Panier vide.</h3>
            <p className="text-slate-400 mt-2 font-medium">Générez un menu pour commencer vos achats.</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default ShoppingList;

import React, { useState } from 'react';
import { useApp } from '../App';
import { generateMealPlan } from '../services/gemini';
import { DayPlan, DietPreference, Meal } from '../types';

const DAYS_OF_WEEK = ['Lundi', 'Mardi', 'Mercredi', 'Jeudi', 'Vendredi', 'Samedi', 'Dimanche'];

const Dashboard: React.FC = () => {
  const { authState, updateUser, currentMealPlan, setCurrentMealPlan, savedPlans, saveCurrentPlan } = useApp();
  const [loading, setLoading] = useState(false);
  const [activeDay, setActiveDay] = useState(0);
  const [isSaving, setIsSaving] = useState(false);
  const [saveName, setSaveName] = useState('');
  const [instructions, setInstructions] = useState('');
  const [selectedMeal, setSelectedMeal] = useState<Meal | null>(null);
  const [servings, setServings] = useState(2);
  const [selectedDays, setSelectedDays] = useState<string[]>(DAYS_OF_WEEK);
  const [defaultTakeAway, setDefaultTakeAway] = useState(true);

  const toggleDay = (day: string) => {
    setSelectedDays(prev => 
      prev.includes(day) ? prev.filter(d => d !== day) : [...prev, day]
    );
  };

  const handleGenerate = async () => {
    if (!authState.user || selectedDays.length === 0) return;
    setLoading(true);
    try {
      const data = await generateMealPlan(authState.user.diet, authState.user.allergies, servings, selectedDays, instructions);
      const initializedData = data.map(day => ({
        ...day,
        meals: {
          breakfast: { ...day.meals.breakfast, isSelected: true, isTakeAway: false },
          lunch: { ...day.meals.lunch, isSelected: true, isTakeAway: defaultTakeAway },
          dinner: { ...day.meals.dinner, isSelected: true, isTakeAway: false },
        }
      }));
      setCurrentMealPlan(initializedData);
      localStorage.setItem('nutriplan_last_servings', servings.toString());
      setActiveDay(0);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const toggleMealProperty = (dayIdx: number, mealType: 'breakfast' | 'lunch' | 'dinner', property: 'isSelected' | 'isTakeAway') => {
    if (!currentMealPlan) return;
    const newPlan = [...currentMealPlan];
    const meal = newPlan[dayIdx].meals[mealType];
    (meal as any)[property] = !(meal as any)[property];
    setCurrentMealPlan(newPlan);
  };

  if (loading) {
    return (
      <div className="p-8 flex flex-col items-center justify-center min-h-[60vh]">
        <div className="w-16 h-16 border-4 border-emerald-500/20 border-t-emerald-500 rounded-full animate-spin mb-6"></div>
        <p className="text-xl font-bold text-slate-900">IA Nutriplan compose votre menu...</p>
        <p className="text-slate-400 mt-2 text-sm">Préparation pour {selectedDays.length} jours</p>
      </div>
    );
  }

  return (
    <div className="p-6 max-w-7xl mx-auto">
      {selectedMeal && <MealDetailModal meal={selectedMeal} onClose={() => setSelectedMeal(null)} />}

      <div className="grid lg:grid-cols-4 gap-8">
        <aside className="lg:col-span-1 space-y-6">
          <div className="bg-emerald-600 rounded-[32px] p-6 text-white shadow-xl shadow-emerald-200">
            <h3 className="text-[10px] font-black opacity-60 uppercase tracking-widest mb-4">Actions</h3>
            <button 
              onClick={() => setCurrentMealPlan(null)}
              className="w-full py-4 bg-white/20 hover:bg-white/30 transition-all rounded-2xl font-black text-xs uppercase"
            >
              🔄 Nouveau Planning
            </button>
          </div>

          <div className="bg-white rounded-[32px] p-6 shadow-sm border border-slate-100">
            <h3 className="text-[10px] font-black text-slate-300 uppercase tracking-widest mb-6">HISTORIQUE</h3>
            <div className="space-y-2">
              {savedPlans.length === 0 ? (
                <p className="text-[10px] text-slate-400 italic">Aucun menu enregistré.</p>
              ) : (
                savedPlans.map(plan => (
                  <button 
                    key={plan.id}
                    onClick={() => { setCurrentMealPlan(plan.plan); setServings(plan.servings); setActiveDay(0); }}
                    className="w-full text-left p-3 rounded-xl hover:bg-emerald-50 transition-all text-xs font-bold text-slate-600"
                  >
                    {plan.name} • {plan.servings}p
                  </button>
                ))
              )}
            </div>
          </div>
        </aside>

        <div className="lg:col-span-3">
          {currentMealPlan ? (
            <>
              <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 mb-8">
                <div>
                  <h1 className="text-3xl font-black text-slate-900 tracking-tight">Mon Planning Semaine</h1>
                  <p className="text-slate-500 text-sm">Décochez les repas que vous ne voulez pas cuisiner.</p>
                </div>
                <div className="flex gap-2">
                  <button onClick={() => setIsSaving(true)} className="px-5 py-3 bg-white border border-slate-200 rounded-xl text-[10px] font-bold">Sauvegarder</button>
                  <button onClick={() => setCurrentMealPlan(null)} className="px-5 py-3 bg-slate-900 text-white rounded-xl text-[10px] font-bold">Modifier critères</button>
                </div>
              </div>

              {isSaving && (
                <div className="mb-8 p-6 bg-white border border-emerald-100 rounded-[32px] flex gap-4 shadow-xl animate-in slide-in-from-top duration-300">
                  <input 
                    type="text" placeholder="Nom de ce menu..."
                    className="flex-grow px-5 py-3 rounded-xl bg-slate-50 outline-none text-sm font-bold"
                    value={saveName} onChange={(e) => setSaveName(e.target.value)}
                  />
                  <button onClick={() => { saveCurrentPlan(saveName); setIsSaving(false); }} className="px-8 py-3 bg-emerald-600 text-white font-bold rounded-xl text-xs">OK</button>
                </div>
              )}

              <div className="flex gap-2 mb-8 overflow-x-auto pb-2 no-scrollbar">
                {currentMealPlan.map((plan, idx) => (
                  <button
                    key={idx}
                    onClick={() => setActiveDay(idx)}
                    className={`px-6 py-3 rounded-xl whitespace-nowrap font-bold text-[10px] uppercase tracking-widest transition-all ${
                      activeDay === idx ? 'bg-emerald-600 text-white shadow-lg' : 'bg-white text-slate-400 border border-slate-100'
                    }`}
                  >
                    {plan.day}
                  </button>
                ))}
              </div>

              <div className="grid md:grid-cols-3 gap-6">
                <MealCard 
                  title="Matin" meal={currentMealPlan[activeDay].meals.breakfast} 
                  onToggleSelect={() => toggleMealProperty(activeDay, 'breakfast', 'isSelected')}
                  onToggleTakeAway={() => toggleMealProperty(activeDay, 'breakfast', 'isTakeAway')}
                  onClick={() => setSelectedMeal(currentMealPlan[activeDay].meals.breakfast)} 
                />
                <MealCard 
                  title="Midi" meal={currentMealPlan[activeDay].meals.lunch} 
                  onToggleSelect={() => toggleMealProperty(activeDay, 'lunch', 'isSelected')}
                  onToggleTakeAway={() => toggleMealProperty(activeDay, 'lunch', 'isTakeAway')}
                  onClick={() => setSelectedMeal(currentMealPlan[activeDay].meals.lunch)} 
                />
                <MealCard 
                  title="Soir" meal={currentMealPlan[activeDay].meals.dinner} 
                  onToggleSelect={() => toggleMealProperty(activeDay, 'dinner', 'isSelected')}
                  onToggleTakeAway={() => toggleMealProperty(activeDay, 'dinner', 'isTakeAway')}
                  onClick={() => setSelectedMeal(currentMealPlan[activeDay].meals.dinner)} 
                />
              </div>
            </>
          ) : (
            <div className="bg-white rounded-[40px] p-8 md:p-12 shadow-sm border border-slate-100">
              <div className="max-w-2xl mx-auto space-y-10">
                <div className="text-center">
                  <h2 className="text-3xl font-black text-slate-900 mb-2">Configuration IA</h2>
                  <p className="text-slate-400 text-sm">Quels sont vos besoins pour les prochains jours ?</p>
                </div>

                <div className="space-y-8">
                  <div>
                    <label className="block text-[10px] font-black text-slate-300 uppercase tracking-widest mb-4">1. Choisissez les jours</label>
                    <div className="flex flex-wrap gap-2">
                      {DAYS_OF_WEEK.map(day => (
                        <button
                          key={day}
                          onClick={() => toggleDay(day)}
                          className={`px-4 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${
                            selectedDays.includes(day) ? 'bg-emerald-600 text-white shadow-md' : 'bg-slate-50 text-slate-400 border border-slate-100'
                          }`}
                        >
                          {day}
                        </button>
                      ))}
                    </div>
                  </div>

                  <div className="grid md:grid-cols-2 gap-6">
                    <div className="bg-slate-50/50 p-6 rounded-[24px] border border-slate-100 text-center">
                      <label className="block text-[10px] font-black text-slate-400 uppercase mb-4">Nombre de convives</label>
                      <div className="flex items-center justify-center gap-4">
                        <button onClick={() => setServings(Math.max(1, servings - 1))} className="w-8 h-8 bg-white rounded-full shadow-sm font-bold">-</button>
                        <span className="text-3xl font-black text-slate-900">{servings}</span>
                        <button onClick={() => setServings(Math.min(10, servings + 1))} className="w-8 h-8 bg-white rounded-full shadow-sm font-bold">+</button>
                      </div>
                    </div>
                    <button 
                      onClick={() => setDefaultTakeAway(!defaultTakeAway)}
                      className={`p-6 rounded-[24px] border-2 flex flex-col items-center justify-center transition-all ${
                        defaultTakeAway ? 'border-amber-500 bg-amber-50 text-amber-700' : 'border-slate-100 bg-white text-slate-400'
                      }`}
                    >
                      <span className="text-2xl mb-1">🥡</span>
                      <span className="text-[10px] font-black uppercase">Midi à emporter ?</span>
                      <span className="text-[8px] font-bold mt-1 opacity-60">{defaultTakeAway ? 'OUI' : 'NON (Cuisiné maison)'}</span>
                    </button>
                  </div>

                  <div>
                    <label className="block text-[10px] font-black text-slate-300 uppercase mb-4">2. Instructions complémentaires</label>
                    <textarea 
                      placeholder="Ex: Pas de brocolis, repas rapides le soir..."
                      className="w-full h-24 p-4 bg-slate-50 border border-slate-100 rounded-2xl text-sm font-medium focus:ring-2 focus:ring-emerald-500 outline-none"
                      value={instructions} onChange={(e) => setInstructions(e.target.value)}
                    />
                  </div>

                  <button 
                    onClick={handleGenerate}
                    className="w-full py-5 bg-emerald-600 text-white font-black rounded-2xl hover:bg-emerald-700 shadow-xl shadow-emerald-100 transition-all"
                  >
                    GÉNÉRER MON MENU SUR-MESURE
                  </button>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

const MealCard = ({ title, meal, onClick, onToggleSelect, onToggleTakeAway }: any) => {
  if (!meal) return null;
  const isSelected = meal.isSelected !== false;
  return (
    <div className={`bg-white rounded-[32px] overflow-hidden border transition-all duration-300 flex flex-col h-full relative ${isSelected ? 'border-slate-100 shadow-sm' : 'opacity-40 grayscale scale-95 border-slate-200'}`}>
      <button onClick={onToggleSelect} className={`absolute top-3 right-3 z-10 w-8 h-8 rounded-full flex items-center justify-center text-xs font-bold transition-all ${isSelected ? 'bg-emerald-600 text-white' : 'bg-slate-200 text-slate-500'}`}>
        {isSelected ? '✓' : '+'}
      </button>
      <div className="h-40 overflow-hidden cursor-pointer" onClick={onClick}>
        <img src={meal.image} className="w-full h-full object-cover" alt={meal.name} />
        <div className="absolute top-3 left-3 px-2 py-1 bg-white/90 rounded-lg text-[8px] font-black text-slate-900 uppercase">{title}</div>
      </div>
      <div className="p-5 flex flex-col flex-grow">
        <h3 className="text-sm font-black text-slate-900 mb-3 leading-tight line-clamp-2">{meal.name}</h3>
        <div className="mt-auto flex justify-between items-center pt-2">
          <button 
            onClick={onToggleTakeAway}
            className={`px-3 py-1.5 rounded-full text-[8px] font-black uppercase transition-all ${meal.isTakeAway ? 'bg-amber-100 text-amber-700' : 'bg-slate-100 text-slate-400'}`}
          >
            {meal.isTakeAway ? '🥡 Emporter' : '🍽️ Maison'}
          </button>
          <span className="text-[10px] font-black text-emerald-600">{meal.calories} KCAL</span>
        </div>
      </div>
    </div>
  );
};

const MealDetailModal = ({ meal, onClose }: { meal: Meal, onClose: () => void }) => (
  <div className="fixed inset-0 z-50 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center p-4">
    <div className="bg-white w-full max-w-3xl rounded-[32px] overflow-hidden shadow-2xl flex flex-col md:flex-row max-h-[90vh]">
      <div className="md:w-1/2 h-64 md:h-auto">
        <img src={meal.image} className="w-full h-full object-cover" alt={meal.name} />
      </div>
      <div className="md:w-1/2 p-8 overflow-y-auto">
        <button onClick={onClose} className="float-right text-slate-400 hover:text-slate-900">✕</button>
        <h2 className="text-2xl font-black mb-6">{meal.name}</h2>
        <div className="space-y-6">
          <div>
            <h4 className="text-[10px] font-black text-slate-300 uppercase mb-3">Ingrédients</h4>
