      <div className="p-6 flex flex-col flex-grow">
        <h3 className="text-[15px] font-black text-slate-900 mb-4 leading-tight group-hover:text-emerald-700 transition-colors cursor-pointer" onClick={onClick}>{meal.name}</h3>
