import React, { useState, useEffect, useMemo } from 'react';
import { useApp } from '../App';
import { generateShoppingList } from '../services/gemini';
import { ShoppingListItem } from '../types';

type Retailer = 'delhaize' | 'colruyt' | 'carrefour';

const ShoppingList: React.FC = () => {
  const { currentMealPlan, savedPlans } = useApp();
  const [list, setList] = useState<ShoppingListItem[]>([]);
  const [loading, setLoading] = useState(false);
  const [selectedWeekId, setSelectedWeekId] = useState<string>('current');
  const [retailer, setRetailer] = useState<Retailer>(() => {
    return (localStorage.getItem('nutriplan_fav_retailer') as Retailer) || 'delhaize';
  });
  const [viewMode, setViewMode] = useState<'standard' | 'assistant'>('standard');
  const [currentIndex, setCurrentIndex] = useState(0);

  useEffect(() => {
    localStorage.setItem('nutriplan_fav_retailer', retailer);
  }, [retailer]);

  const activePlan = useMemo(() => {
    let p = selectedWeekId === 'current' ? currentMealPlan : savedPlans.find(p => p.id === selectedWeekId)?.plan;
    if (!p) return null;
    return p.map(day => ({
      ...day,
      meals: {
        breakfast: day.meals.breakfast.isSelected !== false ? day.meals.breakfast : null as any,
        lunch: day.meals.lunch.isSelected !== false ? day.meals.lunch : null as any,
        dinner: day.meals.dinner.isSelected !== false ? day.meals.dinner : null as any,
      }
    })).filter(day => day.meals.breakfast || day.meals.lunch || day.meals.dinner);
  }, [selectedWeekId, currentMealPlan, savedPlans]);

  useEffect(() => {
    const fetchList = async () => {
      if (!activePlan || activePlan.length === 0) {
        setList([]);
        return;
      }
      setLoading(true);
      try {
        const data = await generateShoppingList(activePlan);
        setList(data);
      } catch (e) {
        console.error("Erreur liste courses:", e);
      } finally {
        setLoading(false);
      }
    };
    fetchList();
  }, [activePlan]);

  // Fonction pour enlever les quantités et chiffres du nom pour une meilleure recherche
  const cleanItemForSearch = (name: string) => {
    // On enlève ce qui ressemble à des quantités : "500g", "2 boites de", etc.
    return name
      .replace(/^\d+\s*(g|kg|ml|l|boîtes|unités|cl|pots|sachets|tranches|cuillères|pincées|verres|tasses|gousses|ml|l)\s*(de\s+|d')?/i, '')
      .replace(/\d+/g, '') // Enlever tous les chiffres restants
      .trim();
  };

  const getRetailerUrl = (item: string) => {
    const cleanedItem = cleanItemForSearch(item);
    // On remplace les espaces par des + pour Carrefour et Colruyt qui sont tatillons
    const q = encodeURIComponent(cleanedItem).replace(/%20/g, '+');

    if (retailer === 'delhaize') return `https://www.delhaize.be/fr-be/search?text=${q}`;
    // Colruyt (Collect & Go) utilise souvent searchTerm
    if (retailer === 'colruyt') return `https://www.collectandgo.be/colruyt/fr/recherche?searchTerm=${q}`;
    // Carrefour Belgique utilise recherche.html
    if (retailer === 'carrefour') return `https://www.carrefour.be/fr/recherche.html?q=${q}`;
    return '';
  };

  const openSearch = (item: string) => {
    const url = getRetailerUrl(item);
    // IMPORTANT: On nomme la fenêtre 'nutriplan_search' pour qu'elle soit réutilisée
    window.open(url, 'nutriplan_search');
  };

  const handleNextWithSearch = () => {
    // 1. On ouvre/met à jour l'onglet unique de recherche
    openSearch(list[currentIndex].item);

    // 2. On incrémente localement l'assistant
    if (currentIndex < list.length - 1) {
      setCurrentIndex(currentIndex + 1);
    } else {
      setViewMode('standard');
      alert("Liste terminée ! Vérifiez votre panier sur le site du magasin.");
    }
  };

  if (loading) return (
    <div className="flex flex-col items-center justify-center min-h-[60vh]">
      <div className="w-12 h-12 border-4 border-emerald-100 border-t-emerald-600 rounded-full animate-spin mb-4"></div>
      <p className="font-black text-[10px] uppercase text-emerald-600 tracking-widest">Calcul du panier optimal...</p>
    </div>
  );

  return (
    <div className={`min-h-screen transition-all duration-500 ${viewMode === 'assistant' ? 'bg-slate-950 text-white' : 'bg-slate-50 text-slate-900'}`}>
      <div className="max-w-6xl mx-auto p-6 lg:p-12">

        <div className="flex flex-col md:flex-row justify-between items-end gap-6 mb-12">
          <div className={`${viewMode === 'assistant' ? 'opacity-20' : 'opacity-100'} transition-opacity`}>
            <h1 className="text-5xl font-black tracking-tighter mb-2">Ma Liste.</h1>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest bg-white/5 px-3 py-1 rounded-full border border-slate-100 inline-block">
              {list.length} articles consolidés
            </p>
          </div>

          <div className="flex flex-wrap items-end gap-4">
            <div className="flex flex-col gap-2">
              <label className="text-[9px] font-black uppercase text-slate-400 tracking-widest">Enseigne cible</label>
              <div className="flex bg-white p-1 rounded-2xl border border-slate-200 shadow-sm">
                {(['delhaize', 'colruyt', 'carrefour'] as Retailer[]).map(r => (
                  <button 
                    key={r}
                    onClick={() => setRetailer(r)}
                    className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${
                      retailer === r ? 'bg-emerald-600 text-white' : 'text-slate-400 hover:text-slate-600'
                    }`}
                  >
                    {r}
                  </button>
                ))}
              </div>
            </div>

            {list.length > 0 && viewMode === 'standard' && (
              <button 
                onClick={() => { setViewMode('assistant'); setCurrentIndex(0); }}
                className="px-8 py-4 bg-slate-900 text-white font-black rounded-2xl text-[11px] uppercase tracking-widest shadow-2xl hover:scale-105 active:scale-95 transition-all"
              >
                🚀 Lancer l'Assistance Panier
              </button>
            )}
          </div>
        </div>

        {list.length > 0 ? (
          viewMode === 'assistant' ? (
            <div className="bg-white/5 border border-white/10 rounded-[50px] p-12 md:p-24 text-center animate-in zoom-in duration-500 shadow-2xl relative">
              <div className="absolute top-0 left-0 w-full h-1.5 bg-white/5 overflow-hidden rounded-t-[50px]">
                <div 
                  className="h-full bg-emerald-500 transition-all duration-700" 
                  style={{ width: `${((currentIndex + 1) / list.length) * 100}%` }}
                ></div>
              </div>

              <div className="max-w-3xl mx-auto">
                <div className="mb-10">
                  <span className="px-4 py-1.5 bg-emerald-500/10 text-emerald-500 rounded-full text-[10px] font-black uppercase tracking-widest border border-emerald-500/20 mr-4">
                    MAGASIN : {retailer.toUpperCase()}
                  </span>
                  <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">
                    ART. {currentIndex + 1} / {list.length}
                  </span>
                </div>

                <h2 className="text-5xl md:text-7xl font-black mt-4 mb-6 leading-tight tracking-tighter">{list[currentIndex].item}</h2>
                <p className="text-2xl font-bold text-slate-400 mb-16 italic">Besoin : <span className="text-white not-italic">{list[currentIndex].amount}</span></p>

                <div className="space-y-6">
                  <div className="flex gap-4">
                    <button 
                      disabled={currentIndex === 0}
                      onClick={() => setCurrentIndex(currentIndex - 1)}
                      className="w-20 py-6 bg-white/5 text-white font-bold rounded-[30px] border border-white/10 disabled:opacity-20 hover:bg-white/10"
                    >
                      ←
                    </button>
                    <button 
                      onClick={handleNextWithSearch}
                      className={`flex-grow py-8 rounded-[30px] font-black text-xl uppercase tracking-widest shadow-2xl transition-all transform hover:scale-[1.02] active:scale-95 flex items-center justify-center gap-4 ${
                        retailer === 'delhaize' ? 'bg-red-600' : 
                        retailer === 'colruyt' ? 'bg-orange-600' : 
                        'bg-blue-600'
                      }`}
                    >
                      <span>🔍 Rechercher & Suivant</span>
                      <span className="text-white/40">→</span>
                    </button>
                  </div>

                  <div className="pt-10 flex flex-col items-center gap-4">
                    <p className="text-[10px] text-slate-500 font-medium">L'onglet {retailer} se met à jour automatiquement.</p>
                    <button onClick={() => setViewMode('standard')} className="text-[11px] font-black text-slate-600 uppercase tracking-widest hover:text-white transition-colors">Quitter l'assistance</button>
                  </div>
                </div>
              </div>
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {list.map((item, idx) => (
                <div key={idx} className="bg-white p-6 rounded-3xl border border-slate-100 flex items-center justify-between group hover:border-emerald-500 transition-all shadow-sm">
                  <div className="pr-4">
                    <p className="text-[13px] font-black text-slate-800 leading-tight mb-1">{item.item}</p>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{item.amount}</p>
                  </div>
                  <button 
                    onClick={() => openSearch(item.item)}
                    className="w-10 h-10 rounded-2xl bg-slate-50 text-slate-300 group-hover:bg-emerald-50 group-hover:text-emerald-600 flex items-center justify-center transition-all border border-transparent group-hover:border-emerald-100"
                    title={`Chercher sur ${retailer}`}
                  >
                    🛒
                  </button>
                </div>
              ))}
            </div>
          )
        ) : (
          <div className="text-center py-32 bg-white rounded-[60px] border-4 border-dashed border-slate-100">
            <h3 className="text-2xl font-black text-slate-300 uppercase tracking-widest">Panier vide.</h3>
            <p className="text-slate-400 text-sm mt-2 font-medium">Générez d'abord un planning dans le tableau de bord.</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default ShoppingList;

import React, { useState } from 'react';
import { useApp } from '../App';
import { generateMealPlan } from '../services/gemini';
import { DayPlan, DietPreference, Meal } from '../types';

const DAYS_OF_WEEK = ['Lundi', 'Mardi', 'Mercredi', 'Jeudi', 'Vendredi', 'Samedi', 'Dimanche'];

const Dashboard: React.FC = () => {
  const { authState, currentMealPlan, setCurrentMealPlan, savedPlans, saveCurrentPlan } = useApp();
  const [loading, setLoading] = useState(false);
  const [activeDay, setActiveDay] = useState(0);
  const [isSaving, setIsSaving] = useState(false);
  const [saveName, setSaveName] = useState('');
  const [instructions, setInstructions] = useState('');
  const [selectedMeal, setSelectedMeal] = useState<Meal | null>(null);
  const [servings, setServings] = useState(2);
  const [selectedDays, setSelectedDays] = useState<string[]>(DAYS_OF_WEEK);
  const [defaultTakeAway, setDefaultTakeAway] = useState(true);

  const toggleDay = (day: string) => {
    setSelectedDays(prev => 
      prev.includes(day) ? prev.filter(d => d !== day) : [...prev, day]
    );
  };

  const handleGenerate = async () => {
    if (!authState.user || selectedDays.length === 0) return;
    setLoading(true);
    try {
      const data = await generateMealPlan(authState.user.diet, authState.user.allergies, servings, selectedDays, instructions);
      const initializedData = data.map(day => ({
        ...day,
        meals: {
          breakfast: { ...day.meals.breakfast, isSelected: true, isTakeAway: false },
          lunch: { ...day.meals.lunch, isSelected: true, isTakeAway: defaultTakeAway },
          dinner: { ...day.meals.dinner, isSelected: true, isTakeAway: false },
        }
      }));
      setCurrentMealPlan(initializedData);
      localStorage.setItem('nutriplan_last_servings', servings.toString());
      setActiveDay(0);
    } catch (err) {
      console.error("Erreur génération:", err);
    } finally {
      setLoading(false);
    }
  };

  const handleNewPlan = () => {
    setCurrentMealPlan(null);
    setActiveDay(0);
    setIsSaving(false);
    setSaveName('');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const toggleMealProperty = (dayIdx: number, mealType: 'breakfast' | 'lunch' | 'dinner', property: 'isSelected' | 'isTakeAway') => {
    if (!currentMealPlan) return;
    const newPlan = [...currentMealPlan];
    const meal = newPlan[dayIdx].meals[mealType];
    if (meal) {
      (meal as any)[property] = !(meal as any)[property];
      setCurrentMealPlan(newPlan);
    }
  };

  if (loading) {
    return (
      <div className="p-8 flex flex-col items-center justify-center min-h-[60vh]">
        <div className="w-16 h-16 border-4 border-emerald-500/20 border-t-emerald-500 rounded-full animate-spin mb-6"></div>
        <p className="text-xl font-bold text-slate-900 tracking-tight">IA Nutriplan compose votre menu...</p>
        <p className="text-slate-400 mt-2 text-sm italic">Personnalisation en cours</p>
      </div>
    );
  }

  return (
    <div className="p-6 max-w-7xl mx-auto">
      {selectedMeal && <MealDetailModal meal={selectedMeal} onClose={() => setSelectedMeal(null)} />}

      <div className="grid lg:grid-cols-4 gap-8">
        <aside className="lg:col-span-1 space-y-6">
          <div className="bg-emerald-600 rounded-[32px] p-6 text-white shadow-xl shadow-emerald-200">
            <h3 className="text-[10px] font-black opacity-60 uppercase tracking-widest mb-4">Actions</h3>
            <button 
              onClick={handleNewPlan}
              className="w-full py-4 bg-white/20 hover:bg-white/30 transition-all rounded-2xl font-black text-xs uppercase tracking-widest"
            >
              🔄 Nouveau Planning
            </button>
          </div>

          <div className="bg-white rounded-[32px] p-6 shadow-sm border border-slate-100">
            <h3 className="text-[10px] font-black text-slate-300 uppercase tracking-widest mb-6">HISTORIQUE</h3>
            <div className="space-y-3">
              {savedPlans.length === 0 ? (
                <p className="text-[10px] text-slate-400 italic font-medium px-2">Aucun menu enregistré.</p>
              ) : (
                savedPlans.slice(0, 8).map(plan => (
                  <button 
                    key={plan.id}
                    onClick={() => { setCurrentMealPlan(plan.plan); setActiveDay(0); }}
                    className="w-full text-left p-3 rounded-xl hover:bg-emerald-50 transition-all text-[11px] font-bold text-slate-600 border border-transparent hover:border-emerald-100"
                  >
                    {plan.name} <span className="opacity-40 ml-1">• {plan.servings}p</span>
                  </button>
                ))
              )}
            </div>
          </div>
        </aside>

        <div className="lg:col-span-3">
          {currentMealPlan ? (
            <>
              <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 mb-8">
                <div>
                  <h1 className="text-3xl font-black text-slate-900 tracking-tight">Mon Planning</h1>
                  <p className="text-slate-500 text-sm">Gérez vos repas avant d'exporter la liste de courses.</p>
                </div>
                <div className="flex gap-2">
                  <button onClick={() => setIsSaving(true)} className="px-5 py-3 bg-white border border-slate-200 rounded-xl text-[10px] font-bold text-slate-600">Sauvegarder</button>
                  <button onClick={handleNewPlan} className="px-5 py-3 bg-slate-900 text-white rounded-xl text-[10px] font-bold shadow-lg">Modifier</button>
                </div>
              </div>

              {isSaving && (
                <div className="mb-8 p-6 bg-white border border-emerald-100 rounded-[32px] flex gap-4 shadow-xl animate-in slide-in-from-top duration-300">
                  <input 
                    type="text" placeholder="Nom de ce menu..."
                    className="flex-grow px-5 py-3 rounded-xl bg-slate-50 outline-none text-sm font-bold border-none"
                    value={saveName} onChange={(e) => setSaveName(e.target.value)}
                  />
                  <button onClick={() => { saveCurrentPlan(saveName); setIsSaving(false); setSaveName(''); }} className="px-8 py-3 bg-emerald-600 text-white font-bold rounded-xl text-xs uppercase tracking-widest">OK</button>
                </div>
              )}

              <div className="flex gap-2 mb-8 overflow-x-auto pb-2 no-scrollbar">
                {currentMealPlan.map((plan, idx) => (
                  <button
                    key={idx}
                    onClick={() => setActiveDay(idx)}
                    className={`px-6 py-3 rounded-xl whitespace-nowrap font-bold text-[10px] uppercase tracking-widest transition-all ${
                      activeDay === idx ? 'bg-emerald-600 text-white shadow-lg' : 'bg-white text-slate-400 border border-slate-100'
                    }`}
                  >
                    {plan.day}
                  </button>
                ))}
              </div>

              <div className="grid md:grid-cols-3 gap-6">
                <MealCard 
                  title="Matin" meal={currentMealPlan[activeDay].meals.breakfast} 
                  onToggleSelect={() => toggleMealProperty(activeDay, 'breakfast', 'isSelected')}
                  onToggleTakeAway={() => toggleMealProperty(activeDay, 'breakfast', 'isTakeAway')}
                  onClick={() => setSelectedMeal(currentMealPlan[activeDay].meals.breakfast)} 
                />
                <MealCard 
                  title="Midi" meal={currentMealPlan[activeDay].meals.lunch} 
                  onToggleSelect={() => toggleMealProperty(activeDay, 'lunch', 'isSelected')}
                  onToggleTakeAway={() => toggleMealProperty(activeDay, 'lunch', 'isTakeAway')}
                  onClick={() => setSelectedMeal(currentMealPlan[activeDay].meals.lunch)} 
                />
                <MealCard 
                  title="Soir" meal={currentMealPlan[activeDay].meals.dinner} 
                  onToggleSelect={() => toggleMealProperty(activeDay, 'dinner', 'isSelected')}
                  onToggleTakeAway={() => toggleMealProperty(activeDay, 'dinner', 'isTakeAway')}
                  onClick={() => setSelectedMeal(currentMealPlan[activeDay].meals.dinner)} 
                />
              </div>
            </>
          ) : (
            <div className="bg-white rounded-[40px] p-8 md:p-12 shadow-sm border border-slate-100 animate-in fade-in duration-500">
              <div className="max-w-3xl mx-auto space-y-12">
                <div className="text-center">
                  <div className="w-16 h-16 bg-emerald-50 text-emerald-600 rounded-2xl flex items-center justify-center text-3xl mx-auto mb-6">⚙️</div>
                  <h2 className="text-3xl font-black text-slate-900 mb-2 tracking-tight">Configuration IA</h2>
                  <p className="text-slate-400 text-sm font-medium">Définissez vos besoins pour la génération.</p>
                </div>

                <div className="space-y-10">
                  <div>
                    <label className="block text-[10px] font-black text-slate-300 uppercase tracking-widest mb-4">1. Pour quels jours ?</label>
                    <div className="flex flex-wrap gap-2">
                      {DAYS_OF_WEEK.map(day => (
                        <button
                          key={day}
                          onClick={() => toggleDay(day)}
                          className={`px-5 py-3 rounded-xl text-[10px] font-black uppercase transition-all ${
                            selectedDays.includes(day) ? 'bg-emerald-600 text-white shadow-md' : 'bg-slate-50 text-slate-400 border border-slate-100'
                          }`}
                        >
                          {day}
                        </button>
                      ))}
                    </div>
                  </div>

                  <div className="grid md:grid-cols-2 gap-8">
                    <div className="bg-slate-50/50 p-6 rounded-[32px] border border-slate-100 text-center">
                      <label className="block text-[10px] font-black text-slate-400 uppercase mb-4 tracking-widest">Nombre de convives</label>
                      <div className="flex items-center justify-center gap-6">
                        <button onClick={() => setServings(Math.max(1, servings - 1))} className="w-10 h-10 bg-white rounded-full shadow-sm font-black text-slate-400 hover:text-emerald-600 transition-colors">-</button>
                        <span className="text-4xl font-black text-slate-900">{servings}</span>
