export interface User {
  id: string;
  name: string;
  email: string;
  age: number;
  diet: DietPreference;
  allergies: string[];
  subscriptionType: 'free' | 'premium';
}

export interface Meal {
  id: string;
  name: string;
  description: string;
  calories: number;
  ingredients: string[];
  instructions: string[];
  image: string;
  type: 'breakfast' | 'lunch' | 'dinner';
  isSelected?: boolean; // Pour choisir si on inclut le repas
  isTakeAway?: boolean; // Pour définir si c'est à emporter
}

export interface DayPlan {
  day: string;
  meals: {
    breakfast: Meal;
    lunch: Meal;
    dinner: Meal;
  };
}

export interface SavedPlan {
  id: string;
  name: string;
  date: string;
  plan: DayPlan[];
  diet: DietPreference;
  servings: number;
}

export interface ShoppingListItem {
  item: string;
  amount: string;
  category: string;
  checked: boolean;
  inStock?: boolean;
}

export interface AuthState {
  user: User | null;
  token: string | null;
  isAuthenticated: boolean;
  isLoading: boolean;
}

export interface CartItem {
  name: string;
  quantity: string;
  timestamp: number;
}

import React, { useState, createContext, useContext, useEffect } from 'react';
import { DietPreference, User, AuthState, DayPlan, SavedPlan } from './types';
import LandingPage from './pages/LandingPage';
import Dashboard from './pages/Dashboard';
import Auth from './pages/Auth';
import Preferences from './pages/Preferences';
import ShoppingList from './pages/ShoppingList';
import Subscription from './pages/Subscription';
import Navbar from './components/Navbar';

interface AppContextType {
  authState: AuthState;
  login: (email: string, pass: string) => Promise<{success: boolean, message?: string}>;
  signup: (name: string, email: string, pass: string, age: number) => Promise<{success: boolean, message?: string}>;
  logout: () => void;
  updateUser: (data: Partial<User>) => void;
  currentMealPlan: DayPlan[] | null;
  setCurrentMealPlan: (plan: DayPlan[] | null) => void;
  savedPlans: SavedPlan[];
  saveCurrentPlan: (name: string) => void;
}

const AppContext = createContext<AppContextType | null>(null);

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useApp must be used within AppProvider");
  return context;
};

export const useAuth = useApp;

// Structure pour simuler une DB locale des utilisateurs
interface LocalUserDB extends User {
  password: string;
}

const App: React.FC = () => {
  const [view, setView] = useState<'landing' | 'auth' | 'dashboard' | 'preferences' | 'shopping' | 'subscription'>('landing');

  const [currentMealPlan, setCurrentMealPlan] = useState<DayPlan[] | null>(() => {
    const saved = localStorage.getItem('nutriplan_current_plan');
    return saved ? JSON.parse(saved) : null;
  });

  const [savedPlans, setSavedPlans] = useState<SavedPlan[]>(() => {
    const saved = localStorage.getItem('nutriplan_saved_plans');
    return saved ? JSON.parse(saved) : [];
  });

  const [authState, setAuthState] = useState<AuthState>(() => {
    const saved = localStorage.getItem('nutriplan_auth');
    return saved ? JSON.parse(saved) : {
      user: null,
      token: null,
      isAuthenticated: false,
      isLoading: false
    };
  });

  useEffect(() => {
    localStorage.setItem('nutriplan_current_plan', JSON.stringify(currentMealPlan));
  }, [currentMealPlan]);

  useEffect(() => {
    localStorage.setItem('nutriplan_saved_plans', JSON.stringify(savedPlans));
  }, [savedPlans]);

  useEffect(() => {
    localStorage.setItem('nutriplan_auth', JSON.stringify(authState));
  }, [authState]);

  // Récupérer la "base de données" locale
  const getUsersDB = (): LocalUserDB[] => {
    const db = localStorage.getItem('nutriplan_users_db');
    return db ? JSON.parse(db) : [];
  };

  const signup = async (name: string, email: string, pass: string, age: number) => {
    setAuthState(prev => ({ ...prev, isLoading: true }));
    await new Promise(resolve => setTimeout(resolve, 1000));

    const db = getUsersDB();
    if (db.some(u => u.email.toLowerCase() === email.toLowerCase())) {
      setAuthState(prev => ({ ...prev, isLoading: false }));
      return { success: false, message: "Cet email est déjà utilisé." };
    }

    const newUser: LocalUserDB = {
      id: Math.random().toString(36).substr(2, 9),
      name,
      email: email.toLowerCase(),
      password: pass, // Note: Dans un vrai système, on hasherait le MDP côté serveur
      age,
      diet: DietPreference.OMNIVORE,
      allergies: [],
      subscriptionType: 'free'
    };

    localStorage.setItem('nutriplan_users_db', JSON.stringify([...db, newUser]));

    // Auto-login après inscription
    const { password, ...userSession } = newUser;
    setAuthState({
      user: userSession,
      token: 'session-' + userSession.id,
      isAuthenticated: true,
      isLoading: false
    });
    setView('dashboard');
    return { success: true };
  };

  const login = async (email: string, pass: string) => {
    setAuthState(prev => ({ ...prev, isLoading: true }));
    await new Promise(resolve => setTimeout(resolve, 800));

    const db = getUsersDB();
    const foundUser = db.find(u => u.email.toLowerCase() === email.toLowerCase());

    if (!foundUser) {
      setAuthState(prev => ({ ...prev, isLoading: false }));
      return { success: false, message: "Aucun compte trouvé avec cet email." };
    }

    if (foundUser.password !== pass) {
      setAuthState(prev => ({ ...prev, isLoading: false }));
      return { success: false, message: "Mot de passe incorrect." };
    }

    const { password, ...userSession } = foundUser;
    setAuthState({
      user: userSession,
      token: 'session-' + userSession.id,
      isAuthenticated: true,
      isLoading: false
    });
    setView('dashboard');
    return { success: true };
  };

  const logout = () => {
    setAuthState({ user: null, token: null, isAuthenticated: false, isLoading: false });
    setCurrentMealPlan(null);
    // On garde le localStorage des plans mais on change de vue
    setView('landing');
  };

  const updateUser = (data: Partial<User>) => {
    if (authState.user) {
      const updatedUser = { ...authState.user!, ...data };

      // Update session
      setAuthState(prev => ({
        ...prev,
        user: updatedUser
      }));

      // Persist in DB
      const db = getUsersDB();
      const newDb = db.map(u => u.id === updatedUser.id ? { ...u, ...data } : u);
      localStorage.setItem('nutriplan_users_db', JSON.stringify(newDb));
    }
  };

  const saveCurrentPlan = (name: string) => {
    if (!currentMealPlan || !authState.user) return;
    const lastServings = parseInt(localStorage.getItem('nutriplan_last_servings') || '2');

    const newSavedPlan: SavedPlan = {
      id: Math.random().toString(36).substr(2, 9),
      name: name || `Menu du ${new Date().toLocaleDateString()}`,
      date: new Date().toISOString(),
      plan: currentMealPlan,
      diet: authState.user.diet,
      servings: lastServings
    };
    setSavedPlans(prev => [newSavedPlan, ...prev]);
  };

  const renderView = () => {
    switch (view) {
      case 'landing': return <LandingPage onGetStarted={() => setView('auth')} />;
      case 'auth': return <Auth onAuthSuccess={() => setView('dashboard')} />;
      case 'dashboard': return <Dashboard />;
      case 'preferences': return <Preferences />;
      case 'shopping': return <ShoppingList />;
      case 'subscription': return <Subscription />;
      default: return <LandingPage onGetStarted={() => setView('auth')} />;
    }
  };

  return (
    <AppContext.Provider value={{ 
      authState, login, signup, logout, updateUser, 
      currentMealPlan, setCurrentMealPlan, 
      savedPlans, saveCurrentPlan 
    }}>
      <div className="min-h-screen flex flex-col bg-slate-50">
        {authState.isAuthenticated && <Navbar currentView={view} setView={setView} />}
        <main className="flex-grow">
          {renderView()}
        </main>
      </div>
    </AppContext.Provider>
  );
};

export default App;

import React, { useState } from 'react';
import { useApp } from '../App';

interface AuthProps {
  onAuthSuccess: () => void;
}

const Auth: React.FC<AuthProps> = ({ onAuthSuccess }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [age, setAge] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState<string | null>(null);

  const { login, signup, authState } = useApp();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    if (password.length < 6) {
      setError("Le mot de passe doit faire au moins 6 caractères.");
      return;
    }

    if (isLogin) {
      const result = await login(email, password);
      if (!result.success) {
        setError(result.message || "Une erreur est survenue.");
      } else {
        onAuthSuccess();
      }
    } else {
      if (!name.trim()) {
        setError("Veuillez entrer votre nom.");
        return;
      }
      if (!age || isNaN(parseInt(age)) || parseInt(age) < 1) {
        setError("Veuillez entrer un âge valide.");
        return;
      }
      const result = await signup(name, email, password, parseInt(age));
      if (!result.success) {
        setError(result.message || "Une erreur est survenue.");
      } else {
        onAuthSuccess();
      }
    }
  };

  return (
    <div className="min-h-[calc(100vh-80px)] flex items-center justify-center p-6 bg-slate-50">
      <div className="w-full max-w-md bg-white rounded-[40px] p-8 md:p-12 shadow-2xl shadow-slate-200 border border-slate-100 relative overflow-hidden">
        {/* Decorative elements */}
        <div className="absolute -top-24 -right-24 w-48 h-48 bg-emerald-100 rounded-full blur-3xl opacity-50"></div>
        <div className="absolute -bottom-24 -left-24 w-48 h-48 bg-teal-100 rounded-full blur-3xl opacity-50"></div>

        <div className="text-center mb-10 relative">
          <div className="w-16 h-16 bg-emerald-600 rounded-2xl flex items-center justify-center text-white font-black text-3xl mx-auto mb-6 shadow-xl shadow-emerald-100">N</div>
          <h2 className="text-3xl font-black text-slate-900 tracking-tight">
            {isLogin ? 'Bon retour !' : 'Créer un compte'}
          </h2>
          <p className="text-slate-400 mt-2 font-medium text-sm">
            {isLogin ? 'Ravis de vous revoir sur Nutriplan.' : 'Rejoignez-nous pour manger mieux.'}
          </p>
        </div>

        {error && (
          <div className="mb-6 p-4 bg-red-50 border border-red-100 text-red-600 rounded-2xl text-xs font-bold animate-in fade-in slide-in-from-top-1 duration-200">
            ⚠️ {error}
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-4 relative">
          {!isLogin && (
            <div className="animate-in fade-in slide-in-from-left-4 duration-300 grid grid-cols-3 gap-4">
              <div className="col-span-2">
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Nom complet</label>
                <input 
                  type="text" 
                  required
                  className="w-full px-6 py-4 bg-slate-50 border border-slate-100 rounded-2xl focus:ring-4 focus:ring-emerald-500/10 focus:bg-white focus:border-emerald-500 outline-none transition-all font-medium text-slate-700"
                  placeholder="Ex: Jean Dupont"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                />
              </div>
              <div className="col-span-1">
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Âge</label>
                <input 
                  type="number" 
                  required
                  min="1"
                  max="120"
                  className="w-full px-4 py-4 bg-slate-50 border border-slate-100 rounded-2xl focus:ring-4 focus:ring-emerald-500/10 focus:bg-white focus:border-emerald-500 outline-none transition-all font-medium text-slate-700"
                  placeholder="28"
                  value={age}
                  onChange={(e) => setAge(e.target.value)}
                />
              </div>
            </div>
          )}

          <div>
            <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Email</label>
            <input 
              type="email" 
              required
              className="w-full px-6 py-4 bg-slate-50 border border-slate-100 rounded-2xl focus:ring-4 focus:ring-emerald-500/10 focus:bg-white focus:border-emerald-500 outline-none transition-all font-medium text-slate-700"
              placeholder="votre@email.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
            />
          </div>

          <div>
            <div className="flex justify-between items-center mb-2 ml-1">
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest">Mot de passe</label>
            </div>
            <input 
              type="password" 
              required
              className="w-full px-6 py-4 bg-slate-50 border border-slate-100 rounded-2xl focus:ring-4 focus:ring-emerald-500/10 focus:bg-white focus:border-emerald-500 outline-none transition-all font-medium text-slate-700"
              placeholder="••••••••"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
            />
            {!isLogin && <p className="text-[9px] text-slate-400 mt-2 ml-1 font-bold">Minimum 6 caractères.</p>}
          </div>

          <button 
            type="submit"
            disabled={authState.isLoading}
            className="w-full py-5 mt-4 bg-emerald-600 text-white font-black rounded-[20px] hover:bg-emerald-700 transition-all shadow-xl shadow-emerald-100 disabled:opacity-50 flex items-center justify-center gap-2 transform active:scale-95"
          >
            {authState.isLoading ? (
              <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
            ) : isLogin ? 'SE CONNECTER' : "CRÉER MON COMPTE"}
          </button>
        </form>

        <div className="mt-8 text-center relative">
          <button 
            onClick={() => {
              setIsLogin(!isLogin);
              setError(null);
            }}
            className="text-xs font-bold text-slate-500 hover:text-emerald-600 transition-colors py-2"
          >
            {isLogin ? "Nouveau sur Nutriplan ? S'inscrire" : "Déjà membre ? Se connecter"}
          </button>
        </div>
      </div>
    </div>
  );
};

export default Auth;

