import React, { useState, createContext, useContext, useEffect } from 'react';
import { DietPreference, User, AuthState, DayPlan, SavedPlan } from './types';
import LandingPage from './pages/LandingPage';
import Dashboard from './pages/Dashboard';
import Auth from './pages/Auth';
import Preferences from './pages/Preferences';
import ShoppingList from './pages/ShoppingList';
import Subscription from './pages/Subscription';
import Navbar from './components/Navbar';

interface AppContextType {
  authState: AuthState;
  login: (email: string, pass: string) => Promise<{success: boolean, message?: string}>;
  signup: (name: string, email: string, pass: string, birthDate: string) => Promise<{success: boolean, message?: string}>;
  socialLogin: (provider: 'google' | 'apple') => Promise<void>;
  logout: () => void;
  updateUser: (data: Partial<User>) => void;
  currentMealPlan: DayPlan[] | null;
  setCurrentMealPlan: (plan: DayPlan[] | null) => void;
  savedPlans: SavedPlan[];
  saveCurrentPlan: (name: string) => void;
}

const AppContext = createContext<AppContextType | null>(null);

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useApp must be used within AppProvider");
  return context;
};

export const useAuth = useApp;

interface LocalUserDB extends User {
  password?: string;
}

const App: React.FC = () => {
  const [view, setView] = useState<'landing' | 'auth' | 'dashboard' | 'preferences' | 'shopping' | 'subscription'>('landing');

  const [currentMealPlan, setCurrentMealPlan] = useState<DayPlan[] | null>(() => {
    const saved = localStorage.getItem('nutriplan_current_plan');
    return saved ? JSON.parse(saved) : null;
  });

  const [savedPlans, setSavedPlans] = useState<SavedPlan[]>(() => {
    const saved = localStorage.getItem('nutriplan_saved_plans');
    return saved ? JSON.parse(saved) : [];
  });

  const [authState, setAuthState] = useState<AuthState>(() => {
    const saved = localStorage.getItem('nutriplan_auth');
    return saved ? JSON.parse(saved) : {
      user: null,
      token: null,
      isAuthenticated: false,
      isLoading: false
    };
  });

  // Persistance automatique
  useEffect(() => {
    localStorage.setItem('nutriplan_current_plan', JSON.stringify(currentMealPlan));
  }, [currentMealPlan]);

  useEffect(() => {
    localStorage.setItem('nutriplan_saved_plans', JSON.stringify(savedPlans));
  }, [savedPlans]);

  useEffect(() => {
    localStorage.setItem('nutriplan_auth', JSON.stringify(authState));
    if (authState.isAuthenticated && view === 'landing') {
        setView('dashboard');
    }
  }, [authState, view]);

  const getUsersDB = (): LocalUserDB[] => {
    const db = localStorage.getItem('nutriplan_users_db');
    return db ? JSON.parse(db) : [];
  };

  const signup = async (name: string, email: string, pass: string, birthDate: string) => {
    setAuthState(prev => ({ ...prev, isLoading: true }));
    await new Promise(resolve => setTimeout(resolve, 1200));

    const db = getUsersDB();
    if (db.some(u => u.email.toLowerCase() === email.toLowerCase())) {
      setAuthState(prev => ({ ...prev, isLoading: false }));
      return { success: false, message: "Cet email est déjà lié à un compte." };
    }

    const newUser: LocalUserDB = {
      id: Math.random().toString(36).substr(2, 9),
      name,
      email: email.toLowerCase(),
      password: pass,
      birthDate,
      diet: DietPreference.OMNIVORE,
      allergies: [],
      subscriptionType: 'free'
    };

    localStorage.setItem('nutriplan_users_db', JSON.stringify([...db, newUser]));

    const { password, ...userSession } = newUser;
    setAuthState({
      user: userSession,
      token: 'sess_' + userSession.id,
      isAuthenticated: true,
      isLoading: false
    });
    setView('dashboard');
    return { success: true };
  };

  const login = async (email: string, pass: string) => {
    setAuthState(prev => ({ ...prev, isLoading: true }));
    await new Promise(resolve => setTimeout(resolve, 800));

    const db = getUsersDB();
    const foundUser = db.find(u => u.email.toLowerCase() === email.toLowerCase());

    if (!foundUser) {
      setAuthState(prev => ({ ...prev, isLoading: false }));
      return { success: false, message: "Email inconnu. Créez un compte !" };
    }

    if (foundUser.password !== pass) {
      setAuthState(prev => ({ ...prev, isLoading: false }));
      return { success: false, message: "Le mot de passe ne correspond pas." };
    }

    const { password, ...userSession } = foundUser;
    setAuthState({
      user: userSession,
      token: 'sess_' + userSession.id,
      isAuthenticated: true,
      isLoading: false
    });
    setView('dashboard');
    return { success: true };
  };

  const socialLogin = async (provider: 'google' | 'apple') => {
    setAuthState(prev => ({ ...prev, isLoading: true }));
    // Simulation d'un délai d'authentification sociale réelle
    await new Promise(resolve => setTimeout(resolve, 1500));

    const mockId = `social_${provider}_${Math.random().toString(36).substr(2, 5)}`;
    const mockUser: User = {
      id: mockId,
      name: provider === 'google' ? 'Google User' : 'Apple User',
      email: `${provider}_user@nutriplan.com`,
      birthDate: '1995-01-01',
      diet: DietPreference.OMNIVORE,
      allergies: [],
      subscriptionType: 'free'
    };

    setAuthState({
      user: mockUser,
      token: 'sess_' + mockUser.id,
      isAuthenticated: true,
      isLoading: false
    });
    setView('dashboard');
  };

  const logout = () => {
    setAuthState({ user: null, token: null, isAuthenticated: false, isLoading: false });
    setCurrentMealPlan(null);
    setView('landing');
  };

  const updateUser = (data: Partial<User>) => {
    if (authState.user) {
      const updatedUser = { ...authState.user!, ...data };
      setAuthState(prev => ({ ...prev, user: updatedUser }));

      const db = getUsersDB();
      const newDb = db.map(u => u.id === updatedUser.id ? { ...u, ...data } : u);
      localStorage.setItem('nutriplan_users_db', JSON.stringify(newDb));
    }
  };

  const saveCurrentPlan = (name: string) => {
    if (!currentMealPlan || !authState.user) return;
    const lastServings = parseInt(localStorage.getItem('nutriplan_last_servings') || '2');
    const newSavedPlan: SavedPlan = {
      id: Math.random().toString(36).substr(2, 9),
      name: name || `Menu du ${new Date().toLocaleDateString()}`,
      date: new Date().toISOString(),
      plan: currentMealPlan,
      diet: authState.user.diet,
      servings: lastServings
    };
    setSavedPlans(prev => [newSavedPlan, ...prev]);
  };

  const renderView = () => {
    switch (view) {
      case 'landing': return <LandingPage onGetStarted={() => setView('auth')} />;
      case 'auth': return <Auth onAuthSuccess={() => setView('dashboard')} />;
      case 'dashboard': return <Dashboard />;
      case 'preferences': return <Preferences />;
      case 'shopping': return <ShoppingList />;
      case 'subscription': return <Subscription />;
      default: return <LandingPage onGetStarted={() => setView('auth')} />;
    }
  };

  return (
    <AppContext.Provider value={{ 
      authState, login, signup, socialLogin, logout, updateUser, 
      currentMealPlan, setCurrentMealPlan, 
      savedPlans, saveCurrentPlan 
    }}>
      <div className="min-h-screen flex flex-col bg-slate-50 selection:bg-emerald-100 selection:text-emerald-900">
        {authState.isAuthenticated && <Navbar currentView={view} setView={setView} />}
        <main className="flex-grow">
          {renderView()}
        </main>
      </div>
    </AppContext.Provider>
  );
};

export default App;

