              checked: { type: Type.BOOLEAN }
            },
            required: ['item', 'amount', 'category', 'checked']
          }
        }
      }
    });

    // Fix: Access response.text property directly (not as a method)
    const text = response.text;
    if (!text) return [];
    return JSON.parse(text);
  } catch (error) {
