            {steps[currentStep].icon}
          </div>

          <h2 className="text-3xl font-black text-slate-900 tracking-tighter mb-4 leading-tight">
            {steps[currentStep].title}
          </h2>

          <p className="text-slate-500 font-medium leading-relaxed mb-12">
            {steps[currentStep].description}
          </p>
        </div>

        {/* Buttons */}
        <div className="w-full space-y-4">
          <button 
            onClick={handleNext}
            className="w-full py-5 bg-slate-900 text-white font-black rounded-3xl hover:bg-emerald-600 transition-all shadow-xl shadow-slate-200 active:scale-95 uppercase tracking-widest text-[11px]"
          >
            {currentStep === steps.length - 1 ? "Commencer maintenant" : "Continuer"}
          </button>

          <button 
            onClick={onComplete}
            className="text-xs font-bold text-slate-400 hover:text-slate-600 transition-all py-2 px-4"
          >
            Passer le tutoriel
          </button>
        </div>

        {/* Decor */}
        <div className="absolute -bottom-20 -right-20 w-48 h-48 bg-slate-50 rounded-full blur-3xl opacity-50"></div>
      </div>
    </div>
  );
};

export default Onboarding;

import React, { useState, createContext, useContext, useEffect } from 'react';
import { DietPreference, User, AuthState, DayPlan, SavedPlan } from './types';
import LandingPage from './pages/LandingPage';
import Dashboard from './pages/Dashboard';
import Auth from './pages/Auth';
import Preferences from './pages/Preferences';
import ShoppingList from './pages/ShoppingList';
import Subscription from './pages/Subscription';
import HowItWorks from './pages/HowItWorks';
import Onboarding from './pages/Onboarding';
import Navbar from './components/Navbar';

interface AppContextType {
  authState: AuthState;
  login: (email: string, pass: string) => Promise<{success: boolean, message?: string}>;
  signup: (name: string, email: string, pass: string, birthDate: string) => Promise<{success: boolean, message?: string}>;
  handleGoogleSuccess: (userData: any) => void;
  logout: () => void;
  updateUser: (data: Partial<User>) => void;
  currentMealPlan: DayPlan[] | null;
  setCurrentMealPlan: (plan: DayPlan[] | null) => void;
  savedPlans: SavedPlan[];
  saveCurrentPlan: (name: string) => void;
  setView: (v: any) => void;
}

const AppContext = createContext<AppContextType | null>(null);

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useApp must be used within AppProvider");
  return context;
};

interface LocalUserDB extends User {
  password?: string;
  hasSeenTutorial?: boolean;
}

const App: React.FC = () => {
  const [view, setView] = useState<'landing' | 'auth' | 'dashboard' | 'preferences' | 'shopping' | 'subscription' | 'how-it-works' | 'onboarding'>('landing');

  const safeParse = (key: string, fallback: any) => {
    try {
      const item = localStorage.getItem(key);
      return item ? JSON.parse(item) : fallback;
    } catch (e) {
      console.error(`Error parsing localStorage key "${key}":`, e);
      return fallback;
    }
  };

  const [currentMealPlan, setCurrentMealPlan] = useState<DayPlan[] | null>(() => safeParse('nutriplan_current_plan', null));
  const [savedPlans, setSavedPlans] = useState<SavedPlan[]>(() => safeParse('nutriplan_saved_plans', []));
  const [authState, setAuthState] = useState<AuthState>(() => safeParse('nutriplan_auth', {
    user: null,
    token: null,
    isAuthenticated: false,
    isLoading: false
  }));

  useEffect(() => {
    localStorage.setItem('nutriplan_current_plan', JSON.stringify(currentMealPlan));
  }, [currentMealPlan]);

  useEffect(() => {
    localStorage.setItem('nutriplan_saved_plans', JSON.stringify(savedPlans));
  }, [savedPlans]);

  useEffect(() => {
    localStorage.setItem('nutriplan_auth', JSON.stringify(authState));

    // CORRECTION: On ne redirige vers dashboard QUE si on n'est pas déjà en train de voir le tuto
    if (authState.isAuthenticated && (view === 'landing' || view === 'auth')) {
        // Si c'est un vieil utilisateur, dashboard. Si c'est un nouveau (flag onboarding), on laisse le state onboarding gérer.
        setView('dashboard');
    }
  }, [authState.isAuthenticated]); // On n'écoute que le changement d'auth pour la redirection initiale

  const getUsersDB = (): LocalUserDB[] => safeParse('nutriplan_users_db', []);

  const signup = async (name: string, email: string, pass: string, birthDate: string) => {
    setAuthState(prev => ({ ...prev, isLoading: true }));
    await new Promise(resolve => setTimeout(resolve, 1000));

    const db = getUsersDB();
    if (db.some(u => u.email.toLowerCase() === email.toLowerCase())) {
      setAuthState(prev => ({ ...prev, isLoading: false }));
      return { success: false, message: "Cet email est déjà utilisé." };
    }

    const newUser: LocalUserDB = {
      id: Math.random().toString(36).substr(2, 9),
      name,
      email: email.toLowerCase(),
      password: pass,
      birthDate,
      diet: DietPreference.OMNIVORE,
      allergies: [],
      subscriptionType: 'free',
      hasSeenTutorial: false
    };

    localStorage.setItem('nutriplan_users_db', JSON.stringify([...db, newUser]));

    const { password, ...userSession } = newUser;
    setAuthState({
      user: userSession,
      token: 'sess_' + userSession.id,
      isAuthenticated: true,
      isLoading: false
    });

    // On force la vue Onboarding IMMÉDIATEMENT
    setView('onboarding');
    return { success: true };
  };

  const login = async (email: string, pass: string) => {
    setAuthState(prev => ({ ...prev, isLoading: true }));
    await new Promise(resolve => setTimeout(resolve, 800));

    const db = getUsersDB();
    const foundUser = db.find(u => u.email.toLowerCase() === email.toLowerCase());

    if (!foundUser) {
      setAuthState(prev => ({ ...prev, isLoading: false }));
      return { success: false, message: "Compte introuvable." };
    }

    if (foundUser.password !== pass) {
      setAuthState(prev => ({ ...prev, isLoading: false }));
      return { success: false, message: "Mot de passe incorrect." };
    }

    const { password, ...userSession } = foundUser;
    setAuthState({
      user: userSession,
      token: 'sess_' + userSession.id,
      isAuthenticated: true,
      isLoading: false
    });

    setView('dashboard');
    return { success: true };
  };

  const handleGoogleSuccess = (googleData: any) => {
    setAuthState(prev => ({ ...prev, isLoading: true }));

    const user: User = {
      id: `google_${googleData.sub}`,
      name: googleData.name,
      email: googleData.email,
      birthDate: '1990-01-01',
      diet: DietPreference.OMNIVORE,
      allergies: [],
      subscriptionType: 'free'
    };

    setAuthState({
      user,
      token: 'google_token_' + googleData.sub,
      isAuthenticated: true,
      isLoading: false
    });

    // Par défaut pour Google on va au dashboard, mais on pourrait vérifier si c'est la 1ère fois
    setView('dashboard');
  };

  const logout = () => {
    setAuthState({ user: null, token: null, isAuthenticated: false, isLoading: false });
    setCurrentMealPlan(null);
    setView('landing');
  };

  const updateUser = (data: Partial<User>) => {
    if (authState.user) {
      const updatedUser = { ...authState.user!, ...data };
      setAuthState(prev => ({ ...prev, user: updatedUser }));
      const db = getUsersDB();
      const newDb = db.map(u => u.id === updatedUser.id ? { ...u, ...data } : u);
      localStorage.setItem('nutriplan_users_db', JSON.stringify(newDb));
    }
  };

  const saveCurrentPlan = (name: string) => {
    if (!currentMealPlan || !authState.user) return;
    const lastServings = parseInt(localStorage.getItem('nutriplan_last_servings') || '2');
    const newSavedPlan: SavedPlan = {
      id: Math.random().toString(36).substr(2, 9),
      name: name || `Menu du ${new Date().toLocaleDateString()}`,
      date: new Date().toISOString(),
      plan: currentMealPlan,
      diet: authState.user.diet,
      servings: lastServings
    };
    setSavedPlans(prev => [newSavedPlan, ...prev]);
  };

  const renderView = () => {
    switch (view) {
      case 'landing': return <LandingPage onGetStarted={() => setView('auth')} onHowItWorks={() => setView('how-it-works')} />;
      case 'auth': return <Auth onAuthSuccess={() => {}} />; // Success géré en interne via signup/login
      case 'dashboard': return <Dashboard />;
      case 'preferences': return <Preferences />;
      case 'shopping': return <ShoppingList />;
      case 'subscription': return <Subscription />;
      case 'how-it-works': return <HowItWorks />;
      case 'onboarding': return <Onboarding onComplete={() => setView('dashboard')} />;
      default: return <LandingPage onGetStarted={() => setView('auth')} onHowItWorks={() => setView('how-it-works')} />;
    }
  };

  return (
    <AppContext.Provider value={{ 
      authState, login, signup, handleGoogleSuccess, logout, updateUser, 
      currentMealPlan, setCurrentMealPlan, 
      savedPlans, saveCurrentPlan, setView
    }}>
      <div className="min-h-screen flex flex-col bg-slate-50">
        {(authState.isAuthenticated || view !== 'landing') && view !== 'onboarding' && view !== 'auth' && <Navbar currentView={view} setView={setView} />}
        <main className="flex-grow">
          {renderView()}
        </main>
      </div>
    </AppContext.Provider>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { useApp } from '../App';

interface AuthProps {
  onAuthSuccess: () => void;
}

const Auth: React.FC<AuthProps> = ({ onAuthSuccess }) => {
  const [isLogin, setIsLogin] = useState(true);
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [birthDate, setBirthDate] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [showConfigHelp, setShowConfigHelp] = useState(false);

  const { login, signup, handleGoogleSuccess, authState } = useApp();

  const GOOGLE_CLIENT_ID = "876547268030-nfgelidbo8p0jvd3hbnp4tosaeng74a0.apps.googleusercontent.com";

  useEffect(() => {
    const initializeGoogle = () => {
      const win = window as any;
      if (win.google && win.google.accounts) {
        try {
          win.google.accounts.id.initialize({
            client_id: GOOGLE_CLIENT_ID,
            callback: (response: any) => {
              const payload = JSON.parse(atob(response.credential.split('.')[1]));
              handleGoogleSuccess(payload);
            },
            cancel_on_tap_outside: false,
          });

          const btnParent = document.getElementById("googleBtn");
          if (btnParent) {
            win.google.accounts.id.renderButton(
              btnParent,
              { 
                theme: "filled_blue", 
                size: "large", 
                width: 320, // FIX: Utiliser un nombre de pixels (200-400) et non "100%"
                shape: "pill",
                text: isLogin ? "signin_with" : "signup_with"
              }
            );
          }
        } catch (e) {
          console.error("Google Auth Init Error:", e);
          setShowConfigHelp(true);
        }
      } else {
        setTimeout(() => {
          if (!win.google) setShowConfigHelp(true);
        }, 3000);
      }
    };

    const timer = setTimeout(initializeGoogle, 500);
    return () => clearTimeout(timer);
  }, [isLogin]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    if (password.length < 6) {
      setError("Le mot de passe doit comporter au moins 6 caractères.");
      return;
    }

    if (isLogin) {
      const result = await login(email, password);
      if (!result.success) setError(result.message || "Identifiants invalides.");
      // Note: redirection gérée par App.tsx suite au changement d'authState
    } else {
      if (!name.trim() || !birthDate) {
        setError("Tous les champs sont requis.");
        return;
      }
      const result = await signup(name, email, password, birthDate);
      if (!result.success) setError(result.message || "Erreur lors de la création.");
      // Note: redirection gérée par App.tsx suite au changement d'authState
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center p-4 bg-slate-50 relative overflow-hidden">
      {/* Background decoration */}
      <div className="absolute top-0 left-0 w-full h-full pointer-events-none">
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-emerald-100/50 rounded-full blur-[120px]"></div>
        <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-blue-100/50 rounded-full blur-[120px]"></div>
      </div>

      <div className="w-full max-w-lg bg-white rounded-[48px] p-8 md:p-12 shadow-2xl shadow-slate-200/60 border border-slate-100 relative z-10 transition-all duration-500">

        <div className="text-center mb-8">
          <div className="w-16 h-16 bg-gradient-to-br from-emerald-500 to-teal-600 rounded-2xl flex items-center justify-center text-white font-black text-3xl mx-auto mb-6 shadow-xl shadow-emerald-200">N</div>
          <h2 className="text-3xl font-black text-slate-900 tracking-tighter mb-2">
            {isLogin ? 'Bon retour !' : 'Rejoindre Nutriplan'}
          </h2>
          <p className="text-sm text-slate-400 font-medium">Votre santé commence dans votre assiette.</p>
        </div>

        {error && (
          <div className="mb-6 p-4 bg-red-50 border border-red-100 text-red-600 rounded-2xl text-xs font-bold animate-in fade-in slide-in-from-top-2">
            ⚠️ {error}
          </div>
        )}

        {showConfigHelp && (
          <div className="mb-6 p-4 bg-amber-50 border border-amber-100 text-amber-700 rounded-2xl text-[10px] font-bold leading-relaxed">
            <p className="uppercase tracking-widest mb-1 text-amber-900">Note sur Google Auth :</p>
            Le bouton Google peut prendre quelques secondes à charger. Si l'erreur 401 persiste sur un domaine personnalisé, vérifiez les réglages Google Cloud.
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-4">
          {!isLogin && (
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-2 ml-1">Nom</label>
                <input 
                  type="text" required
                  className="w-full px-6 py-4 bg-slate-50 border border-slate-100 rounded-2xl focus:bg-white focus:ring-4 focus:ring-emerald-500/10 focus:border-emerald-500 outline-none transition-all font-semibold text-slate-700"
                  placeholder="Jean Dupont"
                  value={name} onChange={(e) => setName(e.target.value)}
                />
              </div>
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-2 ml-1">Naissance</label>
                <input 
                  type="date" required
                  className="w-full px-6 py-4 bg-slate-50 border border-slate-100 rounded-2xl focus:bg-white focus:ring-4 focus:ring-emerald-500/10 focus:border-emerald-500 outline-none transition-all font-semibold text-slate-700"
                  value={birthDate} onChange={(e) => setBirthDate(e.target.value)}
                />
              </div>
            </div>
          )}

          <div>
            <label className="block text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-2 ml-1">Email</label>
            <input 
              type="email" required
              className="w-full px-6 py-4 bg-slate-50 border border-slate-100 rounded-2xl focus:bg-white focus:ring-4 focus:ring-emerald-500/10 focus:border-emerald-500 outline-none transition-all font-semibold text-slate-700"
              placeholder="jean@exemple.com"
              value={email} onChange={(e) => setEmail(e.target.value)}
            />
          </div>

          <div>
            <label className="block text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-2 ml-1">Mot de passe</label>
            <input 
              type="password" required
              className="w-full px-6 py-4 bg-slate-50 border border-slate-100 rounded-2xl focus:bg-white focus:ring-4 focus:ring-emerald-500/10 focus:border-emerald-500 outline-none transition-all font-semibold text-slate-700"
              placeholder="••••••••"
              value={password} onChange={(e) => setPassword(e.target.value)}
            />
          </div>

          <button 
            type="submit"
            disabled={authState.isLoading}
            className="w-full py-5 bg-slate-900 text-white font-black rounded-3xl hover:bg-emerald-600 transition-all shadow-xl shadow-slate-200 active:scale-95 flex items-center justify-center uppercase tracking-widest text-[11px]"
          >
            {authState.isLoading ? <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div> : isLogin ? 'Se connecter' : "Créer mon accès"}
          </button>
        </form>

        <div className="my-8 flex items-center justify-center">
          <div className="flex-grow border-t border-slate-100"></div>
          <span className="px-4 text-[9px] font-black text-slate-300 uppercase tracking-[0.3em] bg-white">ou</span>
          <div className="flex-grow border-t border-slate-100"></div>
        </div>

        <div className="flex justify-center">
          <div id="googleBtn" className="inline-block overflow-hidden rounded-full"></div>
        </div>

        <div className="mt-8 text-center flex flex-col gap-2">
          {window.location.hostname === 'localhost' && (
            <button 
              onClick={() => signup('Développeur', `dev${Date.now()}@nutriplan.local`, 'password123', '1990-01-01')}
              className="text-[10px] font-bold text-emerald-600 border border-emerald-100 rounded-xl py-2 px-4 hover:bg-emerald-50 transition-all"
            >
              Test Rapid Inscription (Dev Only)
            </button>
          )}

          <button 
            onClick={() => { setIsLogin(!isLogin); setError(null); }}
            className="text-xs font-bold text-slate-400 hover:text-emerald-600 transition-all py-2 px-4 rounded-full hover:bg-emerald-50"
          >
            {isLogin ? "Nouveau ici ? Créer un compte" : "Déjà membre ? Se connecter"}
          </button>
        </div>
      </div>
    </div>
  );
};

export default Auth;

import React, { useState, createContext, useContext, useEffect } from 'react';
import { DietPreference, User, AuthState, DayPlan, SavedPlan } from './types';
import LandingPage from './pages/LandingPage';
import Dashboard from './pages/Dashboard';
import Auth from './pages/Auth';
import Preferences from './pages/Preferences';
import ShoppingList from './pages/ShoppingList';
import Subscription from './pages/Subscription';
import HowItWorks from './pages/HowItWorks';
import Onboarding from './pages/Onboarding';
import Navbar from './components/Navbar';

interface AppContextType {
  authState: AuthState;
  login: (email: string, pass: string) => Promise<{success: boolean, message?: string}>;
  signup: (name: string, email: string, pass: string, birthDate: string) => Promise<{success: boolean, message?: string}>;
  handleGoogleSuccess: (userData: any) => void;
  logout: () => void;
  updateUser: (data: Partial<User>) => void;
  currentMealPlan: DayPlan[] | null;
  setCurrentMealPlan: (plan: DayPlan[] | null) => void;
  savedPlans: SavedPlan[];
  saveCurrentPlan: (name: string) => void;
  setView: (v: any) => void;
}

const AppContext = createContext<AppContextType | null>(null);

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error("useApp must be used within AppProvider");
  return context;
};

interface LocalUserDB extends User {
  password?: string;
  hasSeenTutorial?: boolean;
}

const App: React.FC = () => {
  const [view, setView] = useState<'landing' | 'auth' | 'dashboard' | 'preferences' | 'shopping' | 'subscription' | 'how-it-works' | 'onboarding'>('landing');

  const safeParse = (key: string, fallback: any) => {
    try {
      const item = localStorage.getItem(key);
      return item ? JSON.parse(item) : fallback;
    } catch (e) {
      console.error(`Error parsing localStorage key "${key}":`, e);
      return fallback;
    }
  };

  const [currentMealPlan, setCurrentMealPlan] = useState<DayPlan[] | null>(() => safeParse('nutriplan_current_plan', null));
  const [savedPlans, setSavedPlans] = useState<SavedPlan[]>(() => safeParse('nutriplan_saved_plans', []));
  const [authState, setAuthState] = useState<AuthState>(() => safeParse('nutriplan_auth', {
    user: null,
    token: null,
    isAuthenticated: false,
    isLoading: false
  }));

  useEffect(() => {
    localStorage.setItem('nutriplan_current_plan', JSON.stringify(currentMealPlan));
  }, [currentMealPlan]);

  useEffect(() => {
    localStorage.setItem('nutriplan_saved_plans', JSON.stringify(savedPlans));
  }, [savedPlans]);

  useEffect(() => {
    localStorage.setItem('nutriplan_auth', JSON.stringify(authState));

    if (authState.isAuthenticated && (view === 'landing' || view === 'auth')) {
        setView('dashboard');
    }
  }, [authState.isAuthenticated]);

  const getUsersDB = (): LocalUserDB[] => safeParse('nutriplan_users_db', []);

  const calculateAge = (birthDate: string): number => {
    const today = new Date();
    const birth = new Date(birthDate);
    let age = today.getFullYear() - birth.getFullYear();
    const m = today.getMonth() - birth.getMonth();
    if (m < 0 || (m === 0 && today.getDate() < birth.getDate())) {
        age--;
    }
    return age;
  };

  const signup = async (name: string, email: string, pass: string, birthDate: string) => {
    setAuthState(prev => ({ ...prev, isLoading: true }));
    await new Promise(resolve => setTimeout(resolve, 1000));

    // 1. Vérification de l'âge (18 ans min)
    const age = calculateAge(birthDate);
    if (age < 18) {
      setAuthState(prev => ({ ...prev, isLoading: false }));
      return { success: false, message: "Vous devez avoir au moins 18 ans pour vous inscrire." };
    }

    // 2. Vérification si déjà inscrit
    const db = getUsersDB();
    if (db.some(u => u.email.toLowerCase() === email.toLowerCase())) {
      setAuthState(prev => ({ ...prev, isLoading: false }));
      return { success: false, message: "Cet email est déjà associé à un compte." };
    }

    const newUser: LocalUserDB = {
      id: Math.random().toString(36).substr(2, 9),
      name,
      email: email.toLowerCase(),
      password: pass,
      birthDate,
      diet: DietPreference.OMNIVORE,
      allergies: [],
      subscriptionType: 'free',
      hasSeenTutorial: false
    };

    localStorage.setItem('nutriplan_users_db', JSON.stringify([...db, newUser]));

    const { password, ...userSession } = newUser;
    setAuthState({
      user: userSession,
      token: 'sess_' + userSession.id,
      isAuthenticated: true,
      isLoading: false
    });

    setView('onboarding');
    return { success: true };
  };

  const login = async (email: string, pass: string) => {
    setAuthState(prev => ({ ...prev, isLoading: true }));
    await new Promise(resolve => setTimeout(resolve, 800));

    const db = getUsersDB();
    const foundUser = db.find(u => u.email.toLowerCase() === email.toLowerCase());

    if (!foundUser) {
      setAuthState(prev => ({ ...prev, isLoading: false }));
      return { success: false, message: "Compte introuvable." };
    }

    if (foundUser.password !== pass) {
      setAuthState(prev => ({ ...prev, isLoading: false }));
      return { success: false, message: "Mot de passe incorrect." };
    }

    const { password, ...userSession } = foundUser;
    setAuthState({
      user: userSession,
      token: 'sess_' + userSession.id,
      isAuthenticated: true,
      isLoading: false
    });

    setView('dashboard');
    return { success: true };
  };

  const handleGoogleSuccess = (googleData: any) => {
    setAuthState(prev => ({ ...prev, isLoading: true }));

    const user: User = {
      id: `google_${googleData.sub}`,
      name: googleData.name,
      email: googleData.email,
      birthDate: '1990-01-01',
      diet: DietPreference.OMNIVORE,
      allergies: [],
      subscriptionType: 'free'
    };

    setAuthState({
      user,
      token: 'google_token_' + googleData.sub,
      isAuthenticated: true,
      isLoading: false
    });

    setView('dashboard');
  };

  const logout = () => {
    setAuthState({ user: null, token: null, isAuthenticated: false, isLoading: false });
    setCurrentMealPlan(null);
    setView('landing');
  };

  const updateUser = (data: Partial<User>) => {
    if (authState.user) {
      const updatedUser = { ...authState.user!, ...data };
      setAuthState(prev => ({ ...prev, user: updatedUser }));
      const db = getUsersDB();
      const newDb = db.map(u => u.id === updatedUser.id ? { ...u, ...data } : u);
      localStorage.setItem('nutriplan_users_db', JSON.stringify(newDb));
    }
  };

  const saveCurrentPlan = (name: string) => {
    if (!currentMealPlan || !authState.user) return;
    const lastServings = parseInt(localStorage.getItem('nutriplan_last_servings') || '2');
    const newSavedPlan: SavedPlan = {
      id: Math.random().toString(36).substr(2, 9),
      name: name || `Menu du ${new Date().toLocaleDateString()}`,
      date: new Date().toISOString(),
      plan: currentMealPlan,
      diet: authState.user.diet,
      servings: lastServings
    };
    setSavedPlans(prev => [newSavedPlan, ...prev]);
  };

  const renderView = () => {
    switch (view) {
      case 'landing': return <LandingPage onGetStarted={() => setView('auth')} onHowItWorks={() => setView('how-it-works')} />;
      case 'auth': return <Auth onAuthSuccess={() => {}} />;
      case 'dashboard': return <Dashboard />;
      case 'preferences': return <Preferences />;
      case 'shopping': return <ShoppingList />;
      case 'subscription': return <Subscription />;
      case 'how-it-works': return <HowItWorks />;
      case 'onboarding': return <Onboarding onComplete={() => setView('dashboard')} />;
      default: return <LandingPage onGetStarted={() => setView('auth')} onHowItWorks={() => setView('how-it-works')} />;
    }
  };

  return (
    <AppContext.Provider value={{ 
      authState, login, signup, handleGoogleSuccess, logout, updateUser, 
      currentMealPlan, setCurrentMealPlan, 
      savedPlans, saveCurrentPlan, setView
    }}>
      <div className="min-h-screen flex flex-col bg-slate-50">
        {(authState.isAuthenticated || view !== 'landing') && view !== 'onboarding' && view !== 'auth' && <Navbar currentView={view} setView={setView} />}
        <main className="flex-grow">
          {renderView()}
        </main>
      </div>
    </AppContext.Provider>
  );
};

export default App;

